INSERT INTO "classifications" VALUES(6,'claude-haiku-5-5','2026-10-16T15:04:05Z',1,0.93,0,'{"actions_taken": ["Installation of advanced GLOF early warning system at Geepang Gath glacial lake at about 4,100 m altitude", "Submission of disaster loss assessment (about Rs 3,525 crore) to the Centre"], "agencies": [{"country": "IN", "name": "Himachal Pradesh State Disaster Management Authority", "type": "other_national_agency"}, {"country": "IN", "name": "Supreme Court-empowered committee", "type": "other"}], "confidence": 0.93, "countries": ["IN"], "dissemination_channels": [], "event_date": "2026-10-16", "event_location": "Geepang Gath glacial lake, Himachal Pradesh, India", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "glacial_lake_outburst", "impacts": {"affected": null, "deaths": null, "economic_losses": "Rs 3,525 crore", "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "en", "lead_time": null, "lead_time_hours": null, "original_title": "Himachal hopes advanced GLOF early warning system will save lives; seeks Centre aid for Rs 3,525 cr disaster losses", "outcome": "not_reported", "outcome_justification": "The item expresses hope that the newly installed system will reduce response time and save lives, but reports no actual outcome of warnings yet.", "relevant": true, "review": false, "summary_en": "Himachal Pradesh has installed an advanced GLOF early warning system at Geepang Gath glacial lake at about 4,100 metres, which the state hopes will significantly reduce disaster response time and save lives. The state has submitted an assessment of roughly Rs 3,525 crore in disaster-related losses to the Centre seeking aid. A Supreme Court-empowered committee is simultaneously examining disaster risks and the carrying capacity of vulnerable areas.", "summary_original": null, "title_en": "Himachal hopes advanced GLOF early warning system will save lives; seeks Centre aid for Rs 3,525 cr disaster losses", "wmo_regions": ["II"]}');
