INSERT INTO "classifications" VALUES(232,'claude-haiku-5-5','2026-10-16T15:36:40Z',0,0.9,0,'{"actions_taken": [], "agencies": [{"country": null, "name": "Famine Early Warning Systems Network (FEWS NET)", "type": "international"}], "confidence": 0.9, "countries": ["BI"], "dissemination_channels": [], "event_date": "2026-10-16", "event_location": "Burundi", "event_name": null, "ew4all_pillars": [], "hazard": "drought", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "fr", "lead_time": null, "lead_time_hours": null, "original_title": "Burundi - Mise à jour des messages clés : Le démarrage tardif des pluies, la faiblesse des revenus et la pénurie d’engrais entravent le début de la saison A, Septembre 2026 - Janvier 2027", "outcome": "not_reported", "outcome_justification": "The item is a food security outlook on drought-related agricultural and livelihood stress; it does not describe warnings, forecasts or responses in an early warning context.", "relevant": false, "review": false, "summary_en": "A FEWS NET key messages update for Burundi reports late onset of rains and depleted household food stocks after below-average harvests, shifting the Northern Lowlands livelihood zone toward IPC Phase 3 (Crisis) during the October-January lean season. The item focuses on food security outcomes rather than early warning monitoring, forecasting, warning dissemination or response.", "summary_original": "Mise à jour de FEWS NET pour le Burundi : le démarrage tardif des pluies et la faiblesse des revenus font passer la zone des Dépressions du Nord vers la Phase 3 de l''IPC pendant la période de soudure.", "title_en": "Burundi - Key messages update: Late onset of rains, low incomes and fertilizer shortage hamper the start of season A, September 2026 - January 2027", "wmo_regions": ["I"]}');
