INSERT INTO "classifications" VALUES(1394,'claude-haiku-5-5','2026-10-17T09:50:24Z',1,0.8,0,'{"actions_taken": ["Evacuation and displacement of more than 2,100 people", "Assistance to around 570 affected families"], "agencies": [{"country": "PY", "name": "Local authorities of Ayolas", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PY"], "dissemination_channels": [], "event_date": "2026-10-16", "event_location": "Ayolas, Paraguay", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 2100, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Diario HOY | Emergencia en Ayolas: más de 2.100 personas evacuadas tras la crecida del río Paraná", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and expected prolonged critical river levels but does not state whether warnings were issued in advance or how well they worked.", "relevant": true, "review": false, "summary_en": "More than 2,100 people have been displaced and about 570 families affected by rising water levels in Ayolas district as the Paraná River rises. Local authorities expect the river to reach 6.50 metres and remain at critical levels possibly into the first months of next year. The snippet does not describe the forecasts or warnings that preceded the evacuations.", "summary_original": "Más de 2.100 personas desplazadas y unas 570 familias afectadas por el aumento del nivel de los cauces hídricos en el distrito de Ayolas. Las autoridades prevén que el río Paraná alcance los 6,50 metros y se mantenga en nivel crítico hasta los primeros meses del próximo año.", "title_en": "Emergency in Ayolas: more than 2,100 people evacuated after the Paraná River rise", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1395,'claude-haiku-5-5','2026-10-17T09:50:28Z',1,0.7,0,'{"actions_taken": ["Relocation of dozens of families from riverside localities"], "agencies": [], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-16", "event_location": "Corrientes, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 200, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "El río Paraná inundó Corrientes y hay más de 200 evacuados", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations due to river flooding but does not state whether warnings were issued in advance or how effective they were.", "relevant": true, "review": false, "summary_en": "The Paraná River flooded northern areas of Corrientes city, waterlogging neighbourhoods and forcing the relocation of more than 200 people, including dozens of families in riverside localities, linked to the impact of El Niño. The snippet does not describe any warnings or forecasts issued in advance.", "summary_original": "El río Paraná inundó zonas del norte de Corrientes y obligó a reubicar a más de 200 personas en localidades ribereñas, en un contexto asociado al fenómeno El Niño.", "title_en": "The Paraná River flooded Corrientes and more than 200 people have been evacuated", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1396,'claude-haiku-5-5','2026-10-17T09:50:35Z',1,0.93,0,'{"actions_taken": [], "agencies": [{"country": "AR", "name": "Instituto Nacional del Agua (INA)", "type": "NMHS"}], "confidence": 0.93, "countries": ["AR"], "dissemination_channels": ["other"], "event_date": "2026-10-16", "event_location": "Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "during the last days of October", "lead_time_hours": null, "original_title": "El Paraná tendrá una crecida significativa y en Santa Fe podría acercarse a los cinco metros", "outcome": "not_reported", "outcome_justification": "The item reports a hydrological alert/forecast of a significant river rise but no observed outcomes or actions taken are given in the snippet.", "relevant": true, "review": false, "summary_en": "The Instituto Nacional del Agua (INA) warned through its hydrological alert subdivision that the Paraná River is heading towards a significant flood, with levels in Santa Fe city possibly approaching five metres in late October, following recent rainfall. The item is a hydrological forecast/alert communication; the snippet does not describe response actions or outcomes.", "summary_original": "El INA advirtió, a través de su subgerente de Alerta Hidrológico, que el río Paraná se encamina a una crecida significativa que podría llevar su nivel en Santa Fe capital cerca de los cinco metros a fines de octubre, tras las lluvias recientes.", "title_en": "The Paraná will have a significant flood and in Santa Fe it could approach five metres", "wmo_regions": ["III"]}');
