INSERT INTO "classifications" VALUES(1591,'claude-haiku-5-5','2026-10-18T03:09:27Z',1,0.85,0,'{"actions_taken": ["Protección Civil de Michoacán issued an alert for the Sierra-Costa zone"], "agencies": [{"country": "MX", "name": "Protección Civil de Michoacán", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Sierra-Costa zone, Michoacán, Mexico", "event_name": "Hurricane Trudy", "ew4all_pillars": [3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Huracán Trudy provocará lluvias intensas en Michoacán", "outcome": "not_reported", "outcome_justification": "The snippet reports an issued alert for heavy rain and swells up to 7 m but gives no information on impacts or how the warning was received or acted upon.", "relevant": true, "review": false, "summary_en": "Michoacán''s civil protection agency issued an alert for the Sierra-Costa zone warning of intense rain and swells up to 7 metres associated with Hurricane Trudy. The snippet does not describe dissemination channels, evacuations or outcomes.", "summary_original": "Protección Civil de Michoacán emitió una alerta para la zona de la Sierra-Costa por lluvias intensas y oleaje de hasta 7 metros provocados por el huracán Trudy.", "title_en": "Hurricane Trudy will bring heavy rain to Michoacán", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(1592,'claude-haiku-5-5','2026-10-18T03:09:30Z',1,0.8,0,'{"actions_taken": ["Enabled the Cabezo Beaza pavilion in Cartagena as a shelter for possible evacuations", "Activated the local emergency device in response to rainfall"], "agencies": [{"country": "ES", "name": "Cartagena City Council emergency services", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Cartagena, Spain", "event_name": null, "ew4all_pillars": [4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Habilitan el pabellón Cabezo Beaza en Cartagena para posibles evacuaciones por las fuertes lluvias", "outcome": "not_reported", "outcome_justification": "The snippet reports preparedness actions and heavy rainfall but gives no information on the outcome of the evacuations or warnings.", "relevant": true, "review": false, "summary_en": "Heavy rainfall exceeding 40 litres per square metre in some areas of Cartagena caused traffic disruptions and led authorities to activate the emergency device. The Cabezo Beaza pavilion was made available as a shelter in case evacuations became necessary. The snippet does not report warnings issued or their outcome.", "summary_original": "Las lluvias intensas superiores a 40 litros por metro cuadrado en algunos puntos de Cartagena provocaron cortes de tráfico y la activación del dispositivo de emergencia, habilitándose el pabellón Cabezo Beaza para posibles evacuaciones.", "title_en": "Cabezo Beaza pavilion in Cartagena enabled for possible evacuations due to heavy rain", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(1593,'claude-haiku-5-5','2026-10-18T03:10:10Z',0,0.85,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "IGP (Instituto Geofísico del Perú)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Peru", "event_name": null, "ew4all_pillars": [], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Temblor en Perú hoy EN VIVO, sábado 17 de octubre: último sismo, magnitud y epicentro según el IGP", "outcome": "not_reported", "outcome_justification": "Live routine reporting of the latest earthquake parameters with no warning, forecast or response content described.", "relevant": false, "review": false, "summary_en": "A Peruvian news live blog reports the latest earthquake in Peru on 17 October, citing magnitude, epicentre and depth from the Instituto Geofísico del Perú. The snippet is a routine seismic bulletin with no description of warnings, impacts or response actions.", "summary_original": "Un blog en vivo de un medio peruano informa sobre el último sismo en Perú el 17 de octubre, con magnitud, epicentro y profundidad según el IGP. Es un boletín sísmico rutinario sin contenido sobre alertas o respuesta.", "title_en": "Earthquake in Peru live today, Saturday 17 October: latest quake, magnitude and epicentre according to IGP", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1596,'claude-haiku-5-5','2026-10-18T03:09:34Z',1,0.7,0,'{"actions_taken": ["Evacuation of nearly 500 people from six localities"], "agencies": [], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Entre Ríos Province, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 500, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Acá no te ayuda nadie: el reclamo de los vecinos evacuados por la crecida de los ríos Paraná y Uruguay", "outcome": "negative", "outcome_justification": "Residents complain of lack of support after evacuation; no information on warning timeliness or dissemination is given, but the complaint about insufficient assistance points to response shortcomings.", "relevant": true, "review": false, "summary_en": "Authorities recorded almost 500 people forced to leave their homes in six localities of the province due to rising waters of the Paraná and Uruguay rivers. Coastal areas remain on alert and new floods are feared. Evacuated residents complain they are receiving little help.", "summary_original": "Las autoridades registraron casi quinientas personas que debieron abandonar sus hogares en seis localidades de la provincia por la crecida de los ríos Paraná y Uruguay. Los vecinos evacuados reclaman falta de asistencia mientras las zonas costeras siguen en alerta.", "title_en": "Nobody helps us here: residents evacuated by the flooding of the Paraná and Uruguay rivers complain", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1598,'claude-haiku-5-5','2026-10-18T03:08:39Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Andalusia, Valencian Community, Murcia and Barcelona, Spain", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Andalucía, Comunidad Valenciana, Murcia y Barcelona, en alerta roja por las lluvias", "outcome": "not_reported", "outcome_justification": "The item reports red warnings for rain in several Spanish regions but gives no information on outcomes or impacts.", "relevant": true, "review": false, "summary_en": "Red alerts for rainfall have been issued for Andalusia, the Valencian Community, Murcia and Barcelona, indicating the highest level of warning for heavy precipitation. The item provides no details on the forecasts, dissemination channels or actions taken.", "summary_original": "Alerta roja por lluvias en Andalucía, la Comunidad Valenciana, Murcia y Barcelona. El aviso indica el nivel más alto por precipitaciones intensas, aunque la noticia no detalla medidas adoptadas.", "title_en": "Andalusia, Valencian Community, Murcia and Barcelona on red alert due to rain", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(1599,'claude-haiku-5-5','2026-10-18T03:08:43Z',1,0.97,0,'{"actions_taken": ["Sent two ES-Alert messages to the population of Valencia and Alicante under a red rain alert", "Advised residents to avoid travel, not cross flood-prone areas and respect traffic closures", "Advised avoiding river channels, seeking high ground or upper floors in flood zones, and staying away from seafronts and coastal areas"], "agencies": [{"country": "ES", "name": "Emergencias (Generalitat Valenciana / Spanish emergency services)", "type": "other_national_agency"}, {"country": "ES", "name": "ES-Alert", "type": "other_national_agency"}], "confidence": 0.97, "countries": ["ES"], "dissemination_channels": ["cell_broadcast"], "event_date": "2026-10-17", "event_location": "Valencia and Alicante, Spain", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Emergencias envía dos mensajes Es - Alert a la población en Valencia y Alicante ante la alerta roja por lluvias", "outcome": "not_reported", "outcome_justification": "The snippet describes the warnings and protective advice issued but does not report their effects on the population.", "relevant": true, "review": false, "summary_en": "Spain''s emergency services issued two ES-Alert mobile warning messages to residents of Valencia and Alicante in response to a red alert for rain. The messages urged people to avoid travel, stay out of flood-prone areas and river channels, move to higher ground or upper floors, and keep away from the coast. The snippet does not report the outcome of the warnings.", "summary_original": "Emergencias envió dos mensajes ES-Alert a la población de Valencia y Alicante ante la alerta roja por lluvias, pidiendo evitar desplazamientos, no cruzar zonas inundables, buscar zonas altas y alejarse de la costa.", "title_en": "Emergency services send two ES-Alert messages to the population in Valencia and Alicante over the red rain alert", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(1601,'claude-haiku-5-5','2026-10-18T03:10:13Z',1,0.8,0,'{"actions_taken": ["Livestock being moved from islands to the coast for several days", "Over 120,000 head of cattle in General Obligado department being evacuated, a large part already relocated"], "agencies": [], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "General Obligado, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [2, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "En Santa Fe también esperan la crecida del Paraná y trabajan a contrarreloj para salvar a miles de animales de las islas", "outcome": "not_reported", "outcome_justification": "The article describes ongoing preparedness and evacuation of livestock ahead of an expected Paraná River flood, with no final outcome reported.", "relevant": true, "review": false, "summary_en": "Producers in northern Santa Fe province, Argentina, are moving livestock from the Paraná River islands to the coast as a flood crest is expected, following similar actions in Corrientes and Entre Ríos. An estimated 120,000+ head of cattle are at stake in General Obligado department, with a large part already relocated. The item documents preparedness actions taken in anticipation of the flood rather than formal official warnings.", "summary_original": "En Santa Fe, productores del norte provincial trasladan animales desde las islas hacia la costa ante la crecida esperada del Paraná; en General Obligado hay más de 120.000 cabezas en riesgo y gran parte ya fue puesta a salvo.", "title_en": "In Santa Fe they also await the Paraná flood and work against the clock to save thousands of animals from the islands", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1603,'claude-haiku-5-5','2026-10-18T03:09:45Z',1,0.8,0,'{"actions_taken": ["Evacuation of 206 people and self-evacuation of 266 people in Corrientes province", "Evacuation level declared at eight river ports in the region"], "agencies": [], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Corrientes, Argentina", "event_name": null, "ew4all_pillars": [2], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 472, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del Río Paraná: 472 personas dejaron sus casas en Corrientes y preocupan las inundaciones", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and river levels exceeding evacuation thresholds but gives no information on warning timing, dissemination, or effectiveness.", "relevant": true, "review": false, "summary_en": "The Paraná River exceeded 6.50 metres in Corrientes city, and eight ports in the region reached evacuation level, prompting 206 evacuations and 266 self-evacuations amid rains and El Niño conditions. The snippet does not describe the forecasts or warnings issued or how they were disseminated.", "summary_original": "El Paraná superó los 6,50 metros en Corrientes y ocho puertos alcanzaron el nivel de evacuación; 472 personas dejaron sus casas entre evacuados y autoevacuados por las lluvias y El Niño.", "title_en": "Paraná River flood: 472 people left their homes in Corrientes and floods cause concern", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1605,'claude-haiku-5-5','2026-10-18T03:10:16Z',1,0.8,0,'{"actions_taken": ["Evacuation of families from islands", "Livestock relocation", "Residents seeking refuge"], "agencies": [{"country": "AR", "name": "cadena3.com", "type": "media"}], "confidence": 0.8, "countries": ["AR", "BR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Ituzaingó, Corrientes Province, Argentina", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 40, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Inundaciones en Corrientes: al menos 40 familias evacuadas y temor por nuevas crecidas", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and warnings of possible further rainfall-driven rises from Brazil, but does not state whether warnings were effective or how they were disseminated.", "relevant": true, "review": false, "summary_en": "The Paraná River exceeded its evacuation level at Ituzaingó, Corrientes, prompting evacuation of at least 40 families and relocation of livestock from the islands. Authorities warn that rainfall in Brazil could worsen the situation.", "summary_original": "El río Paraná superó el nivel de evacuación en Ituzaingó, con al menos 40 familias evacuadas y advertencias de que las lluvias en Brasil podrían agravar la situación.", "title_en": "Floods in Corrientes: at least 40 families evacuated and fear of new flooding", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(1606,'claude-haiku-5-5','2026-10-18T03:09:49Z',1,0.8,0,'{"actions_taken": ["Farmer relocated about 250 of roughly 600 livestock from the islands ahead of the upcoming flood crest"], "agencies": [], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Islands between Rosario and Arroyo Seco, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del Paraná: un productor isleño advirtió que faltan medios para evacuar el ganado", "outcome": "negative", "outcome_justification": "The item reports that a producer lacks infrastructure, boats and transport means to evacuate livestock before the next flood crest, indicating preparedness shortcomings in response to the expected rise.", "relevant": true, "review": false, "summary_en": "A livestock producer on the Paraná River islands between Rosario and Arroyo Seco said he had moved about 250 of his roughly 600 animals ahead of an expected flood crest. He criticised the lack of infrastructure, environmental restrictions and shortage of boats needed to evacuate remaining livestock. The report highlights gaps in response capacity following an anticipated flood warning.", "summary_original": "Un productor de las islas entre Rosario y Arroyo Seco retiró unas 250 cabezas de ganado y denunció falta de infraestructura, restricciones ambientales y escasez de barcos ante la próxima creciente del Paraná.", "title_en": "Paraná flood: island farmer warns of insufficient means to evacuate livestock", "wmo_regions": ["III"]}');
