INSERT INTO "classifications" VALUES(1610,'claude-haiku-5-5','2026-10-18T03:10:42Z',1,0.8,0,'{"actions_taken": ["Evacuation of 206 people in six localities of Corrientes Province", "Self-evacuation of 266 people"], "agencies": [{"country": "AR", "name": "Provincial authorities of Corrientes", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-17", "event_location": "Corrientes Province, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 206, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Más de 400 personas dejaron sus casas en Corrientes por la crecida de los ríos Paraná y Uruguay", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and authorities warning that the number of affected families could increase, but does not state whether warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "Flooding of the Paraná and Uruguay rivers led to the evacuation of 206 people and self-evacuation of 266 others across six localities in Corrientes Province, Argentina. Authorities warned that the number of affected families could rise as rains and river swelling continue.", "summary_original": "La crecida de los ríos Paraná y Uruguay obligó a evacuar a 206 personas y a 266 a autoevacuarse en seis localidades de Corrientes. Las autoridades advirtieron que podrían aumentar las familias afectadas.", "title_en": "More than 400 people left their homes in Corrientes due to the flooding of the Paraná and Uruguay rivers", "wmo_regions": ["III"]}');
