INSERT INTO "classifications" VALUES(1621,'claude-haiku-5-5','2026-10-18T03:08:21Z',1,0.95,0,'{"actions_taken": ["Deployment of 180 firefighters from Saturday", "Public recommendation not to cross ravines or flooded areas"], "agencies": [{"country": "ES", "name": "Consorcio de Bomberos de Valencia", "type": "other_national_agency"}, {"country": "ES", "name": "AEMET", "type": "NMHS"}], "confidence": 0.95, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-18", "event_location": "Southern coast of Valencia, Spain", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "from Saturday ahead of Sunday''s alert", "lead_time_hours": null, "original_title": "Valencia activa 180 bomberos ante la alerta roja por lluvias: \"No intentéis cruzar barrancos aunque parezca que se puede pasar", "outcome": "not_reported", "outcome_justification": "The article describes preparedness and warnings issued ahead of the event; no outcome has been reported yet.", "relevant": true, "review": false, "summary_en": "AEMET issued a red alert for heavy rain on Spain''s southern Valencian coast for Sunday, with forecasts of up to 300 litres accumulated. The Valencia firefighters consortium deployed 180 personnel from Saturday and advised the public not to cross ravines or flooded areas.", "summary_original": "El Consorcio de Bomberos de Valencia despliega 180 efectivos desde el sábado ante la alerta roja de AEMET en el litoral sur valenciano para este domingo, con previsiones de hasta 300 litros acumulados. Recomienda no cruzar barrancos ni zonas inundadas.", "title_en": "Valencia activates 180 firefighters ahead of AEMET red alert for rain: \"Do not try to cross ravines even if it seems you can get through\"", "wmo_regions": ["VI"]}');
