INSERT INTO "classifications" VALUES(2331,'claude-haiku-5-5','2026-10-20T03:17:35Z',1,0.8,0,'{"actions_taken": ["Evacuation of 754 people from their homes", "Transfer of 392 people to evacuation centres", "Shelter support for 362 people staying with relatives"], "agencies": [{"country": "AR", "name": "Provincial authorities of Corrientes", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Corrientes Province, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": 2, "economic_losses": null, "evacuated": 754, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Dos personas mueren en Argentina tras la crecida de un río por el impacto de El Niño", "outcome": "not_reported", "outcome_justification": "The snippet reports deaths and evacuations but does not state whether warnings were issued in advance or how they were received.", "relevant": true, "review": false, "summary_en": "A hydrological emergency caused by a river flood in Corrientes Province, Argentina, has led to two deaths and the evacuation of 754 people, of whom 392 were moved to evacuation centres. Provincial authorities are publishing updated figures, but the snippet gives no details on advance warnings or lead time.", "summary_original": "La emergencia hidrológica por la crecida de un río en la provincia de Corrientes, Argentina, ha causado dos muertes y la evacuación de 754 personas, de las cuales 392 fueron trasladadas a centros de evacuación. Las autoridades provinciales difunden datos actualizados, pero el fragmento no detalla las alertas previas ni el tiempo de anticipación.", "title_en": "Two people die in Argentina after river flood linked to El Niño impact", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2333,'claude-haiku-5-5','2026-10-20T03:17:39Z',0,0.85,0,'{"actions_taken": [], "agencies": [], "confidence": 0.85, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Veracruz, Mexico", "event_name": null, "ew4all_pillars": [], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": 4, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Tragedia en Veracruz: Colapso de barda por frente frío 2 deja cuatro mujeres muertas - Almomento | Noticias, información nacional e internacional", "outcome": "not_reported", "outcome_justification": "The snippet reports a fatal wall collapse during rains but mentions no warnings, forecasts or alerts issued or acted upon.", "relevant": false, "review": false, "summary_en": "Four women died when a wall collapsed onto their home during rains associated with cold front 2 in Veracruz, Mexico. The item is a damage report and does not describe any monitoring, forecast, warning or response related to the event.", "summary_original": "Cuatro mujeres murieron al colapsar una barda sobre su vivienda por las lluvias del frente frío 2 en Veracruz.", "title_en": "Tragedy in Veracruz: Wall collapse caused by cold front 2 leaves four women dead", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(2334,'claude-haiku-5-5','2026-10-20T03:16:40Z',1,0.8,0,'{"actions_taken": ["Confinement of 145 municipalities in Valencia and Alicante"], "agencies": [], "confidence": 0.8, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Valencia and Alicante, Spain", "event_name": "DANA Adam", "ew4all_pillars": [], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": 4, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La DANA Adam deja cuatro muertos y causa inundaciones, cortes de carreteras y de luz en Balears", "outcome": "not_reported", "outcome_justification": "The snippet reports deaths, flooding and confinement of municipalities but does not state whether warnings were issued in advance or how they performed.", "relevant": true, "review": false, "summary_en": "Storm DANA Adam caused flooding, road closures and power cuts in the Balearics, leaving four dead. In Valencia and Alicante, 145 municipalities were confined after up to 700 l/m2 of rain fell in 48 hours.", "summary_original": "La DANA Adam dejó cuatro muertos y provocó inundaciones, cortes de carreteras y de luz en Baleares. En Valencia y Alicante, 145 municipios estuvieron confinados tras caer hasta 700 l/m2 en 48 horas.", "title_en": "The DANA Adam leaves four dead and causes floods, road closures and power cuts in the Balearics", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2335,'claude-haiku-5-5','2026-10-20T03:17:42Z',0,0.85,0,'{"actions_taken": ["Port operations suspended to evacuate personnel (Balboa and Cristóbal)"], "agencies": [], "confidence": 0.85, "countries": ["CL", "PA"], "dissemination_channels": [], "event_date": "2026-10-09", "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Puertos estatales tras el sismo: lo que Chile aprendió en 2010", "outcome": "not_reported", "outcome_justification": "Snippet is an opinion piece on port operations after an earthquake; no warning, forecast or dissemination information is described.", "relevant": false, "review": false, "summary_en": "An opinion piece reviews how Panamanian state ports responded to an earthquake on 9 October: Balboa and Cristóbal suspended operations to evacuate staff and resumed on Saturday, while the Canal kept transit running. It draws lessons from Chile''s 2010 earthquake, but the snippet does not describe any early warning monitoring, alerts or their dissemination.", "summary_original": "Opinión sobre el funcionamiento de los puertos estatales tras el terremoto del 9 de octubre en Panamá, con lecciones de Chile en 2010. Balboa y Cristóbal suspendieron operaciones para evacuar personal.", "title_en": "State ports after the earthquake: what Chile learned in 2010", "wmo_regions": ["III", "IV"]}');
INSERT INTO "classifications" VALUES(2336,'claude-haiku-5-5','2026-10-20T03:16:44Z',1,0.8,0,'{"actions_taken": ["Preparation of an evacuation centre at the entrance to the coastal district of Alto Verde", "Planning to install up to 78 housing modules", "Work to guarantee drinking water, lighting and security in case of evacuation of families"], "agencies": [{"country": "AR", "name": "Municipalidad de Santa Fe", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Alto Verde, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del Paraná: Santa Fe prepara un centro de evacuados en Alto Verde con 78 módulos habitacionales", "outcome": "not_reported", "outcome_justification": "The item describes preparations for a possible evacuation; no outcome has been reported yet.", "relevant": true, "review": false, "summary_en": "The municipality of Santa Fe is preparing an evacuation centre in Alto Verde, planning up to 78 housing modules, in anticipation of rising Paraná River waters. Mayor Juan Pablo Poletti confirmed work to ensure drinking water, lighting and security in case families must be evacuated. The item focuses on preparedness rather than on the warnings themselves.", "summary_original": "La Municipalidad de Santa Fe acondiciona un centro de evacuación en Alto Verde y prevé instalar hasta 78 módulos habitacionales ante una eventual evacuación de familias por la crecida del Paraná.", "title_en": "Paraná flood: Santa Fe prepares an evacuee centre in Alto Verde with 78 housing modules", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2338,'claude-haiku-5-5','2026-10-20T03:17:45Z',1,0.85,0,'{"actions_taken": ["Confinement of the population of 145 municipalities in several comarcas during the morning", "Rescue operations (more than a thousand rescues)"], "agencies": [{"country": "ES", "name": "Emergencias (Generalitat Valenciana)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Marina Alta, Valencian Community, Spain", "event_name": "DANA Adam", "ew4all_pillars": [4], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": 3, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La dana Adam deja tres muertes, más de un millar de rescates y 720 litros en municipios de la Marina Alta", "outcome": "mixed", "outcome_justification": "Population was confined in advance and many rescues were carried out, but three deaths were reported and some municipalities were completely flooded.", "relevant": true, "review": false, "summary_en": "The DANA Adam caused three deaths and more than a thousand rescues in the Marina Alta area. Emergency services confined the population of 145 municipalities during the morning, with some towns such as Oliva and Els Poblets completely flooded. The item reports precautionary confinement measures taken in response to the event.", "summary_original": "La DANA Adam dejó tres muertos y más de un millar de rescates en la Marina Alta. Emergencias confinó a la población de 145 municipios durante la mañana, algunos completamente inundados como Oliva o Els Poblets.", "title_en": "The DANA Adam leaves three dead, more than a thousand rescues and 720 litres in municipalities of the Marina Alta", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2339,'claude-haiku-5-5','2026-10-20T03:17:50Z',1,0.8,0,'{"actions_taken": ["Warning issued about flash flooding, water accumulation and possible complications on roads and riverside areas", "Public advised to follow official information channels"], "agencies": [{"country": "AR", "name": "Secretaría de Emergencias y Gestión de Riesgos (Neuquén)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": ["other"], "event_date": "2026-10-19", "event_location": "Neuquén, Argentina", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Una semana de lluvias pone en alerta a distintas zonas de Neuquén | Neuquén Al Instante", "outcome": "not_reported", "outcome_justification": "The snippet describes warnings issued but does not report any outcome of the alert.", "relevant": true, "review": false, "summary_en": "The Emergency and Risk Management Secretariat of Neuquén warned of sudden flooding, water accumulation and possible disruption on roads and riverside zones after a week of rain. Residents were advised to follow official channels for information. No outcome of the warning is reported.", "summary_original": "La Secretaría de Emergencias y Gestión de Riesgos de Neuquén advirtió sobre fenómenos repentinos, acumulación de agua y posibles complicaciones en rutas y zonas ribereñas tras una semana de lluvias, y recomendó seguir los canales oficiales de información.", "title_en": "A week of rain puts various areas of Neuquén on alert", "wmo_regions": ["III"]}');
