INSERT INTO "classifications" VALUES(2881,'claude-haiku-5-5','2026-10-21T03:23:41Z',1,0.7,0,'{"actions_taken": ["Legislative project requesting reports on works executed after a 2009 Supreme Court ruling"], "agencies": [{"country": "AR", "name": "Legislatura de Río Negro", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Alto Valle, Río Negro, Argentina", "event_name": null, "ew4all_pillars": [1], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta por el riesgo de inundaciones en el Alto Valle: piden informes por las obras en Portezuelo Grande", "outcome": "not_reported", "outcome_justification": "The snippet describes a legislative initiative on flood-risk infrastructure and the effects of El Niño; no warning issuance, dissemination or outcome is reported.", "relevant": true, "review": false, "summary_en": "A bill presented in the Río Negro Legislature seeks information on measures taken at Portezuelo Grande following a 2009 Supreme Court ruling, amid concern about flood risk in the Alto Valle. The item also highlights potential El Niño effects and the safety of local communities. It concerns flood risk governance rather than a specific warning event.", "summary_original": "Un proyecto presentado en la Legislatura de Río Negro busca conocer qué medidas se ejecutaron tras un fallo de la Corte Suprema de 2009, en medio de la alerta por riesgo de inundaciones en el Alto Valle y los efectos de El Niño.", "title_en": "Flood risk alert in the Alto Valle: reports requested on works at Portezuelo Grande", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2882,'claude-haiku-5-5','2026-10-21T03:24:48Z',1,0.85,0,'{"actions_taken": ["Port closures", "Evacuations", "Suspension of classes"], "agencies": [{"country": "MX", "name": "Servicio Meteorológico Nacional (SMN)", "type": "NMHS"}, {"country": "MX", "name": "Comisión Nacional del Agua (Conagua)", "type": "NMHS"}], "confidence": 0.85, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Veracruz, Mexico", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Cierran puertos y suspenden clases por frente frío en Veracruz - Entre Líneas", "outcome": "not_reported", "outcome_justification": "The snippet reports warning-driven closures and evacuations in progress but gives no information on whether they were effective or what impacts resulted.", "relevant": true, "review": false, "summary_en": "Mexico maintained port closures, evacuations and class suspensions on Monday due to rain from a second cold front, while Tropical Storm Trudy weakened off the western coast. The National Meteorological Service (SMN) of Conagua issued warnings for the affected areas, and Trudy was expected to stop affecting national territory by Tuesday.", "summary_original": "México mantiene este lunes cierres de puertos, evacuaciones y suspensiones de clases por las lluvias del segundo frente frío, mientras ''Trudy'' se debilita como tormenta tropical frente al occidente del país y podría dejar de afectar el territorio nacional el martes. El SMN de Conagua situó a...", "title_en": "Ports closed and classes suspended due to cold front in Veracruz", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(2883,'claude-haiku-5-5','2026-10-21T03:23:07Z',1,0.8,0,'{"actions_taken": ["Federal emergency operation coordinated by AFE with Gendarmería Nacional and Prefectura Naval to assist affected people", "Surveillance of riverside areas", "Reinforced preventive controls in Corrientes and Misiones", "Evacuation of hundreds of people"], "agencies": [{"country": "AR", "name": "Agencia Federal de Emergencias (AFE)", "type": "other_national_agency"}, {"country": "AR", "name": "Gendarmería Nacional", "type": "other_national_agency"}, {"country": "AR", "name": "Prefectura Naval", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Corrientes and Misiones, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta en el Litoral: crecida histórica de los ríos Paraná y Uruguay deja cientos de evacuados y un amplio despliegue federal", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and a federal response but does not state whether warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "An extraordinary flood of the Paraná and Uruguay rivers in Argentina''s Litoral region has led to hundreds of evacuations. The national Federal Emergency Agency is coordinating a joint operation with the National Gendarmerie and Naval Prefecture to assist those affected, monitor riverside areas, and reinforce preventive controls in Corrientes and Misiones. The snippet does not detail the forecasts or warnings issued beforehand.", "summary_original": "Una crecida extraordinaria de los ríos Paraná y Uruguay mantiene en vilo al Litoral argentino; la AFE coordina un operativo conjunto con Gendarmería y Prefectura para asistir a los afectados y vigilar áreas ribereñas en Corrientes y Misiones.", "title_en": "Alert in the Litoral: historic flood of the Paraná and Uruguay rivers leaves hundreds evacuated and a broad federal deployment", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2884,'claude-haiku-5-5','2026-10-21T03:24:54Z',1,0.7,0,'{"actions_taken": ["rescues"], "agencies": [], "confidence": 0.7, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Els Poblets, Alicante, Valencian Community, Spain", "event_name": null, "ew4all_pillars": [4], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "El crudo testimonio de Silvia en Els Poblets tras la dana: El agua me llegaba entre la rodilla y la cadera", "outcome": "not_reported", "outcome_justification": "The snippet describes widespread destruction and emergency rescues after a DANA (cut-off low) but does not state whether warnings were issued or acted upon.", "relevant": true, "review": false, "summary_en": "A testimony article from Els Poblets (Alicante) describes a DANA leaving destruction and thousands affected across the Valencian Community, with emergency rescues and a fourth confirmed death mentioned in the snippet. The snippet does not describe any monitoring, forecasts or warnings issued before the event, so early warning relevance is indirect.", "summary_original": "Un testimonio de Els Poblets (Alicante) describe una DANA que deja destrucción y miles de afectados en la Comunidad Valenciana, con rescates de emergencia y la confirmación de una cuarta víctima mortal. El fragmento no menciona avisos ni previsiones emitidas previamente.", "title_en": "Silvia''s raw testimony in Els Poblets after the DANA: the water reached my knee and hip", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(2885,'claude-haiku-5-5','2026-10-21T03:24:57Z',0,0.8,0,'{"actions_taken": ["Call for dredgers to fill the San Andrés Little Bank for the navigation season"], "agencies": [{"country": "AR", "name": "Enapro", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Paraná River, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Convocan a areneras para rellenar el Banquito San Andrés ante la crecida", "outcome": "not_reported", "outcome_justification": "The item reports a dredging/navigation decision and a forecast river rise, but no warning dissemination or outcome of warnings.", "relevant": false, "review": false, "summary_en": "Argentina''s Enapro announced a call for dredgers to fill the San Andrés Little Bank to sustain the navigation season amid a possible Paraná River rise above four metres at month''s end linked to a strong El Niño. The item concerns waterway management rather than the monitoring, forecasting or warning of the hazard.", "summary_original": "El Enapro anunció la convocatoria a areneras para rellenar el Banquito San Andrés y sostener la temporada de navegación ante la posible crecida del Paraná, que podría superar los cuatro metros a fin de mes.", "title_en": "Dredgers called to fill the San Andrés Little Bank ahead of the flood", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2886,'claude-haiku-5-5','2026-10-21T03:25:01Z',1,0.8,0,'{"actions_taken": ["Producers launched an operation to move 10,000-15,000 head of livestock from islands and riverbank areas to higher ground"], "agencies": [], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "San Javier, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La creciente del Paraná obliga a evacuar hasta 15.000 cabezas de ganado en el norte santafesino", "outcome": "not_reported", "outcome_justification": "The snippet describes preparedness actions by producers in response to the flood but does not report warning outcomes.", "relevant": true, "review": false, "summary_en": "Rising waters of the Paraná River and its secondary basins are affecting livestock activity in northern Santa Fe, Argentina. In San Javier, producers are relocating 10,000-15,000 head of cattle from island and riverbank areas to higher terrain. The snippet does not mention official forecasts or warnings.", "summary_original": "La creciente del Paraná y sus cuencas secundarias afecta la ganadería en el norte santafesino. En San Javier, productores trasladan entre 10.000 y 15.000 cabezas de ganado a terrenos más elevados.", "title_en": "The Paraná flood forces evacuation of up to 15,000 head of livestock in northern Santa Fe", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2887,'claude-haiku-5-5','2026-10-21T03:23:45Z',1,0.8,0,'{"actions_taken": ["evacuations reported"], "agencies": [], "confidence": 0.8, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Veracruz, Tabasco and Oaxaca, Mexico", "event_name": null, "ew4all_pillars": [2, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": 10, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Frente frío 2 deja 10 muertos, evacuaciones y daños en Veracruz, Tabasco y Oaxaca: Situación y previsiones de lluvia", "outcome": "not_reported", "outcome_justification": "The snippet reports deaths, evacuations and damage and mentions rainfall forecasts, but does not state whether warnings were issued in advance or how well they performed.", "relevant": true, "review": false, "summary_en": "A stalled cold front over the Gulf of Mexico has brought rainfall totals near historical maxima in southern Veracruz, with reported deaths, evacuations and damage in Veracruz, Tabasco and Oaxaca. The article includes rainfall forecasts, but the snippet does not detail the warnings issued or their dissemination.", "summary_original": "Un frente frío estacionado sobre la región del Golfo de México provocó acumulados de lluvia cercanos a los máximos históricos en el sur de Veracruz. El artículo reporta 10 muertos, evacuaciones y daños en Veracruz, Tabasco y Oaxaca, además de previsiones de lluvia.", "title_en": "Cold front 2 leaves 10 dead, evacuations and damage in Veracruz, Tabasco and Oaxaca: situation and rainfall forecasts", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(2890,'claude-haiku-5-5','2026-10-21T03:23:49Z',1,0.8,0,'{"actions_taken": ["Evacuation of nearly 300 people", "Use of boats and launches for transport and delivery of food"], "agencies": [{"country": "AR", "name": "Prefectura Naval Argentina", "type": "other_national_agency"}, {"country": "AR", "name": "Defensa Civil", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Itatí, Corrientes, Argentina", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 300, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Inundación en Itatí: el Paraná superó los 8,24 metros y hay cerca de 300 evacuados", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and high river levels but does not state whether warnings were timely or effective.", "relevant": true, "review": false, "summary_en": "The Paraná River in Itatí, Corrientes, exceeded 8.24 metres, surpassing the 2023 record, with flooded streets and nearly 300 people evacuated. Residents are using boats to move and carry food, and uncertainty remains about how the flood will evolve.", "summary_original": "La crecida del río Paraná en Itatí, Corrientes, superó los 8,24 metros, con calles anegadas y cerca de 300 evacuados. Crece la incertidumbre sobre la evolución del fenómeno.", "title_en": "Flooding in Itatí: the Paraná exceeded 8.24 metres and nearly 300 people evacuated", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2891,'claude-haiku-5-5','2026-10-21T03:23:55Z',1,0.85,0,'{"actions_taken": ["Evacuation of more than 2,000 people"], "agencies": [], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Pego-Oliva, Valencia, Spain", "event_name": "DANA Adam", "ew4all_pillars": [4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": 4, "economic_losses": null, "evacuated": 2000, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La dana Adam deja al menos cuatro muertos, más de 2.000 evacuados y lluvias históricas en el Mediterráneo", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and deaths but does not state whether warnings were issued in time or how they were received; the link of one death to the event is still under investigation.", "relevant": true, "review": false, "summary_en": "A cold-core low (DANA ''Adam'') caused historic rainfall in the Mediterranean region of Spain, with at least four deaths reported and more than 2,000 people evacuated. A farmer''s body was found in the Pego-Oliva marshland, though its connection to the event is still being investigated. The snippet does not detail the warnings issued or their dissemination.", "summary_original": "La DANA Adam ha dejado al menos cuatro muertos y más de 2.000 evacuados, con lluvias históricas en el Mediterráneo. Se investiga si la muerte de un agricultor hallado en la marjal de Pego-Oliva está relacionada con el fenómeno.", "title_en": "The DANA Adam leaves at least four dead, more than 2,000 evacuated and historic rainfall in the Mediterranean", "wmo_regions": ["VI"]}');
