INSERT INTO "classifications" VALUES(2898,'claude-haiku-5-5','2026-10-21T03:25:25Z',1,0.8,0,'{"actions_taken": ["Port closures", "Evacuations", "Suspension of classes"], "agencies": [{"country": "MX", "name": "Servicio Meteorológico Nacional", "type": "NMHS"}], "confidence": 0.8, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": null, "event_name": "Tropical Storm Trudy", "ew4all_pillars": [3, 4], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "México cierra puertos y suspende clases por frente frío mientras Trudy pierde fuerza", "outcome": "not_reported", "outcome_justification": "The snippet reports protective actions taken in response to rains and a weakening tropical storm, but does not state whether they were effective or what impacts occurred.", "relevant": true, "review": false, "summary_en": "Mexico maintains port closures, evacuations and class suspensions this Monday due to rains from a second cold front, while Trudy weakens into a tropical storm off the western coast and could bring further rain. The actions indicate warning-driven preparedness and response, though the snippet does not detail specific warnings or dissemination channels.", "summary_original": "México mantiene este lunes cierres de puertos, evacuaciones y suspensiones de clases por las lluvias del segundo frente frío, mientras Trudy se debilita como tormenta tropical frente al occidente del país y podría dejar lluvias.", "title_en": "Mexico closes ports and suspends classes due to cold front while Trudy loses strength", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(2899,'claude-haiku-5-5','2026-10-21T03:25:28Z',1,0.7,0,'{"actions_taken": ["Closure of the San Sebastián point"], "agencies": [{"country": "AR", "name": "Prefectura Naval Argentina", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-19", "event_location": "Corrientes, Argentina", "event_name": null, "ew4all_pillars": [2, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Crecida del río Paraná en Corrientes: cerraron la punta San Sebastián", "outcome": "not_reported", "outcome_justification": "The snippet reports river level exceeding the evacuation threshold and a closure, but gives no information on warning dissemination effectiveness or outcomes.", "relevant": true, "review": false, "summary_en": "The Paraná River reached 7.17 metres at the Corrientes port, exceeding the evacuation level set by Argentina''s Naval Prefecture. As a result, the San Sebastián point was closed. The snippet does not describe the forecasts or warnings issued to the public.", "summary_original": "El nivel del Paraná alcanzó los 7,17 metros en el puerto de Corrientes, superando la marca de evacuación fijada por Prefectura Naval Argentina, y se cerró la punta San Sebastián.", "title_en": "Paraná River flood in Corrientes: San Sebastián point closed", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2900,'claude-haiku-5-5','2026-10-21T03:22:00Z',1,0.95,0,'{"actions_taken": ["Red Alert declared for the entire Metropolitan Region", "Evacuation of some points due to floods and mass movement"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "confidence": 0.95, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Santiago Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta Roja en toda la Región Metropolitana por evento meteorológico: Intensas lluvias en varios puntos de Santiago", "outcome": "not_reported", "outcome_justification": "The snippet reports the Red Alert declaration and evacuations underway but gives no information on whether warnings were effective or on final impacts.", "relevant": true, "review": false, "summary_en": "Chile''s national emergency service Senapred declared a Red Alert for the entire Santiago Metropolitan Region due to intense rainfall, initially limited to pre-Andean communes. Some locations have already been evacuated in response to river flooding, mass movement and inundation.", "summary_original": "Senapred decretó Alerta Roja para toda la Región Metropolitana por intensas lluvias, inicialmente solo en comunas precordilleranas, y algunos puntos ya fueron evacuados ante crecidas, remoción en masa e inundaciones.", "title_en": "Red Alert across the entire Metropolitan Region for weather event: Intense rain in several points of Santiago", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(2901,'claude-haiku-5-5','2026-10-21T03:22:40Z',1,0.95,0,'{"actions_taken": ["Declaration of Red Alert across the entire Metropolitan Region"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}, {"country": "CL", "name": "Dirección Meteorológica de Chile (DMC)", "type": "NMHS"}], "confidence": 0.95, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Declaran Alerta Roja en toda la región Metropolitana por llegada de intensas lluvias con granizos", "outcome": "not_reported", "outcome_justification": "The item reports only the declaration of the alert; no outcomes of the warning are described.", "relevant": true, "review": false, "summary_en": "Senapred declared a Red Alert across the entire Metropolitan Region of Chile due to intense rain and hail, with high risk of flash floods (aluviones) and mass movements in the foothills, according to the DMC and regional director Miguel Muñoz. The alert level is a high-severity warning issued ahead of the expected hazard.", "summary_original": "Senapred declaró Alerta Roja en toda la región Metropolitana ante intensas lluvias y granizos, con alto riesgo de aluviones y remociones en masa en la precordillera, según la DMC y el director regional Miguel Muñoz.", "title_en": "Red Alert declared across the entire Metropolitan Region due to arrival of intense rain with hail", "wmo_regions": ["III"]}');
