INSERT INTO "classifications" VALUES(3077,'claude-haiku-5-5','2026-10-21T03:23:09Z',1,0.8,0,'{"actions_taken": ["Specialists recommend prevention measures for flooding, water scarcity and forest fires", "Calls for greater preparedness by authorities"], "agencies": [], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-10-20", "event_location": "Peru", "event_name": "El Niño", "ew4all_pillars": [1, 4], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "El fenómeno de El Niño amenaza de forma distinta al Perú: qué hacer ante lluvias, sequías e incendios", "outcome": "not_reported", "outcome_justification": "The snippet describes forecast risks and recommendations but reports no realised outcomes of warnings.", "relevant": true, "review": false, "summary_en": "Specialists warn that El Niño poses differentiated risks in Peru: flooding on the northern coast and water shortages and forest fires in the highlands and jungle. They recommend prevention measures and urge authorities to strengthen preparedness.", "summary_original": "Especialistas advierten que El Niño amenaza de forma distinta al Perú: riesgo de inundaciones en la costa norte y escasez de agua e incendios forestales en la sierra y selva, y recomiendan medidas de prevención y mayor preparación de las autoridades.", "title_en": "El Niño threatens Peru in different ways: what to do about rains, droughts and fires", "wmo_regions": ["III"]}');
