INSERT INTO "classifications" VALUES(3946,'claude-haiku-5-5','2026-10-23T03:21:31Z',1,0.9,0,'{"actions_taken": ["Declaration of yellow alert in six communes"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-10-21", "event_location": "Maipú, Padre Hurtado, Talagante, Peñaflor, El Monte and Melipilla, Metropolitan Region, Chile", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Senapred decreta alerta amarilla en 6 comunas de la Región Metropolitana por crecida del río Mapocho", "outcome": "not_reported", "outcome_justification": "The snippet reports the alert declaration only; no outcomes are given.", "relevant": true, "review": false, "summary_en": "Chile''s national emergency service Senapred declared a yellow alert for six communes in the Metropolitan Region due to the rise of the Mapocho River linked to a frontal system. The alert covers Maipú, Padre Hurtado, Talagante, Peñaflor, El Monte and Melipilla. The snippet does not report dissemination channels or impacts.", "summary_original": "Senapred decretó alerta amarilla para las comunas de Maipú, Padre Hurtado, Talagante, Peñaflor, El Monte y Melipilla por la crecida del río Mapocho debido al sistema frontal.", "title_en": "Senapred declares yellow alert in 6 communes of the Metropolitan Region due to Mapocho River rise", "wmo_regions": ["III"]}');
