INSERT INTO "classifications" VALUES(3960,'claude-haiku-5-5','2026-10-23T03:23:20Z',1,0.85,0,'{"actions_taken": ["INDECI recommends adopting preparedness measures in response to SENAMHI Aviso N.° 433"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Selva (jungle region), Peru", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heatwave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "from Saturday 24 to Monday 26 October", "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante el incremento de la temperatura diurna en la selva", "outcome": "not_reported", "outcome_justification": "The snippet reports a warning and recommended preparedness measures but no outcomes are given.", "relevant": true, "review": false, "summary_en": "INDECI recommends preparedness measures following SENAMHI Aviso N.° 433, which warns of moderate to extreme increases in daytime temperature in the jungle region from 24 to 26 October. The item relays a SENAMHI warning and the civil protection response to it. No outcomes are reported.", "summary_original": "El INDECI recomienda adoptar medidas de preparación ante el Aviso N.° 433 del SENAMHI, que informa sobre el incremento de la temperatura diurna, de moderada a extrema intensidad en la selva, desde el sábado 24 hasta el lunes 26 de octubre.", "title_en": "INDECI recommends preparedness measures ahead of rising daytime temperatures in the jungle", "wmo_regions": ["III"]}');
