INSERT INTO "classifications" VALUES(4350,'claude-haiku-5-5','2026-10-24T03:15:02Z',1,0.9,0,'{"actions_taken": ["Residents urged to remain on strong alert for gales, high waves, landslides, inundation of low-lying areas and river flooding"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["tv", "website"], "event_date": "2026-10-24", "event_location": "Sakishima Islands, Okinawa Prefecture, Japan", "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "【最新情報】台風30号 先島諸島が暴風域に 厳重警戒を", "outcome": "not_reported", "outcome_justification": "The snippet describes an ongoing warning and advisory update with no reported outcomes yet.", "relevant": true, "review": false, "summary_en": "NHK reports that the large Typhoon No. 30 is moving east while part of the Sakishima Islands in Okinawa Prefecture falls within its storm area. Residents are urged to maintain strong vigilance against gales, high waves, landslides, low-lying inundation and river flooding. Areas farther from the typhoon in western Japan are also mentioned.", "summary_original": "大型の台風30号は沖縄県の先島諸島の一部を暴風域に巻き込みながら東寄りに進んでいて、沖縄県では引き続き、暴風や高波、土砂災害や低い土地の浸水、川の増水に厳重に警戒するよう呼びかけています。", "title_en": "[Latest update] Typhoon No. 30 enters storm area over Sakishima Islands; strong alert urged", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4351,'claude-haiku-5-5','2026-10-24T03:15:31Z',1,0.8,0,'{"actions_taken": ["School closures in northern and central Taiwan", "Continued alert and warning status"], "agencies": [], "confidence": 0.8, "countries": ["TW"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Taiwan", "event_name": "Typhoon No. 30", "ew4all_pillars": [4], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": 1, "economic_losses": null, "evacuated": null, "injured": 500, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "台風30号 台湾で1人死亡 500人以上けが 警戒続く", "outcome": "mixed", "outcome_justification": "Warnings led to school closures and sustained alert, but at least one death and over 500 injuries were reported from fallen trees and other damage; the snippet does not state whether warnings were issued in advance or how they were disseminated.", "relevant": true, "review": false, "summary_en": "Typhoon No. 30 made closest approach to Taiwan early on 24 October, causing fallen trees and other damage that killed one person and injured more than 500. Schools were closed in northern and central regions, and alert continues. The item indicates preparedness actions were taken, though details on forecast lead time and warning dissemination are not given.", "summary_original": "台風30号は24日明け方にかけて台湾に最も接近し、倒木などの被害が相次ぎ、これまでに1人が死亡し、500人以上がけがをしました。北部や中部では休校などの措置がとられ、警戒が続いています。", "title_en": "Typhoon No. 30 kills 1 in Taiwan, injures over 500; alert continues", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4353,'claude-haiku-5-5','2026-10-24T03:14:50Z',1,0.95,0,'{"actions_taken": ["JMA issued a Kishō Bōsai Sokuhō (weather disaster bulletin) announcing an imminent linear precipitation band forecast at 10:28 JST for the Ishigaki Island area"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "NHK", "type": "media"}], "confidence": 0.95, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-10-24", "event_location": "Ishigaki Island, Okinawa, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "within the next 3 hours", "lead_time_hours": 3, "original_title": "沖縄 石垣島地方に「線状降水帯直前予測」 気象庁発表", "outcome": "not_reported", "outcome_justification": "The snippet reports only the issuance of the advisory; no information on impacts or public response is given.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency issued a ''linear rainband imminent forecast'' bulletin at 10:28 JST for the Ishigaki Island area of Okinawa, indicating a high likelihood of a linear precipitation band forming within the next three hours. Such bulletins are intended to alert residents to rapidly developing heavy rain from cumulonimbus clouds. The snippet does not report on dissemination details or outcomes.", "summary_original": "気象庁は沖縄県の石垣島地方で今後3時間以内に線状降水帯が発生する可能性が高まったとして、午前10時28分に「線状降水帯直前予測」の気象防災速報を発表した。", "title_en": "Okinawa: JMA issues ''Senjo Kosui-tai Chokuzen Yosoku'' (imminent linear rainband forecast) for Ishigaki Island area", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4382,'claude-haiku-5-5','2026-10-24T03:14:55Z',1,0.8,0,'{"actions_taken": ["Suspended delivery of earthquake early warnings to SoftBank mobile users until the 26th of this month due to a serious PHP vulnerability"], "agencies": [{"country": "JP", "name": "SoftBank", "type": "other"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": ["cell_broadcast"], "event_date": "2026-10-23", "event_location": null, "event_name": null, "ew4all_pillars": [3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "ソフトバンク 緊急地震速報の配信を一時停止 PHP影響で", "outcome": "negative", "outcome_justification": "Disruption of earthquake early warning dissemination to SoftBank customers because of a serious security vulnerability; warnings were not delivered during the suspension period.", "relevant": true, "review": false, "summary_en": "SoftBank announced it will halt delivery of earthquake early warnings and related alerts to its mobile customers until the 26th of this month after a serious vulnerability was found in the PHP programming language. The suspension interrupts a key warning dissemination channel for Japanese mobile users during the period.", "summary_original": "ソフトバンクは自社の携帯電話利用者への緊急地震速報などの配信を今月26日まで停止すると発表した。PHPの重大な脆弱性が原因とされる。", "title_en": "SoftBank suspends earthquake early warning delivery due to PHP vulnerability", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4446,'claude-haiku-5-5','2026-10-24T03:14:58Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Weather Association (tenki.jp)", "type": "other"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-10-24", "event_location": "Sakishima Islands, Okinawa, Japan", "event_name": "Typhoon No. 30", "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "台風30号 24日にかけ先島諸島に接近 線状降水帯発生の恐れ その後は本州付近へ(気象予報士 小野 聡子 2026年10月23日) - 日本気象協会 tenki.jp", "outcome": "not_reported", "outcome_justification": "Article is a forecast advisory about an approaching typhoon and possible linear precipitation bands; no outcomes or actual impacts are reported.", "relevant": true, "review": false, "summary_en": "A forecaster''s report warns that the large, very strong Typhoon No. 30 is expected to approach the Sakishima Islands by 24 October, with a possible linear precipitation band over Okinawa that could rapidly raise the risk of heavy-rain disasters. The typhoon is then expected to move toward the area near mainland Japan.", "summary_original": "大型で非常に強い台風30号が24日にかけて先島諸島に接近する見込みで、沖縄地方では線状降水帯が発生し大雨災害の危険度が急激に高まる可能性があると伝えています。", "title_en": "Typhoon No. 30 approaching the Sakishima Islands by the 24th; risk of linear precipitation band; later moving toward near mainland Japan (forecaster Satoko Ono, 23 Oct 2026) - Japan Weather Association tenki.jp", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4447,'claude-haiku-5-5','2026-10-24T03:14:46Z',1,0.97,0,'{"actions_taken": ["Level 5 flood emergency special warning issued for Kohoku River", "Advice to avoid moving in the dark and not to evacuate recklessly; move to upper floors instead", "Advice to avoid using cars in flood-risk areas"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "TBS NEWS DIG", "type": "media"}], "confidence": 0.97, "countries": ["JP"], "dissemination_channels": ["tv"], "event_date": "2026-10-22", "event_location": "Kohoku River, Akita Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "「暗い中の移動は危険 無理な避難せず上の階へ」気象庁 浸水リスク地域で車を利用しないよう呼びかけ 秋田県・子吉川に「レベル5氾濫特別警報」（TBS NEWS DIG Powered by JNN） - Yahoo!ニュース", "outcome": "not_reported", "outcome_justification": "The snippet states there are no reports of injured people, but does not report on the effectiveness of the warning or evacuation outcomes.", "relevant": true, "review": false, "summary_en": "JMA issued a Level 5 flood emergency special warning for the Kohoku River in Akita Prefecture, the highest flood alert level. It advised residents not to move in the dark or evacuate recklessly, to move to upper floors if needed, and to avoid using cars in flood-risk areas. The report states no injuries had been reported.", "summary_original": "秋田県の子吉川でレベル5の氾濫特別警報が出されたと報じられ、気象庁は暗い中の移動を避け、無理な避難をせず上の階へ移るよう呼びかけ、浸水リスク地域で車を利用しないよう求めています。けが人の情報はないとされています。", "title_en": "\"Dangerous to move in the dark; do not evacuate recklessly, move to upper floors\" JMA calls for avoiding car use in flood-risk areas; Level 5 Flood Emergency Special Warning issued for Kohoku River, Akita Prefecture (TBS NEWS DIG)", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4448,'claude-haiku-5-5','2026-10-24T03:16:08Z',0,0.8,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Cabinet Office (内閣府)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": [], "event_date": null, "event_location": "Chiba Prefecture, Japan", "event_name": null, "ew4all_pillars": [], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "令和８年８月千葉豪雨から台風第２５号までの一連の災害に係る被災者生活再建支援法の適用について（千葉県）", "outcome": "not_reported", "outcome_justification": "The item is a government press release about applying a disaster livelihood support law to a series of disasters; it does not describe monitoring, forecasts, warnings, or their outcomes.", "relevant": false, "review": false, "summary_en": "A Cabinet Office press release announces the application of the Disaster Victims'' Livelihood Reconstruction Support Act to a series of disasters in Chiba Prefecture, beginning with heavy rain in August 2026 and extending to Typhoon No. 25. The item concerns post-disaster recovery support rather than early warning services, and no warning or forecast content is described.", "summary_original": "内閣府による記者発表で、令和8年8月の千葉豪雨から台風第25号までの一連の災害について、被災者生活再建支援法を適用することを発表したもの。警報や予報に関する内容は含まれていない。", "title_en": "Application of the Act on Support for Reconstruction of Disaster Victims'' Livelihoods to the series of disasters from the August 2026 Chiba heavy rain to Typhoon No. 25 (Chiba Prefecture)", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4451,'claude-haiku-5-5','2026-10-24T03:16:12Z',0,0.8,0,'{"actions_taken": ["Assistance provided to 15 families (44 adults and 17 minors) in Los Pescadores neighbourhood"], "agencies": [{"country": "AR", "name": "Prefectura Naval Argentina", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-23", "event_location": "Corrientes, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": 61, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Prefectura asiste a pobladores afectados por la crecida de los ríos Paraná y Paraguay", "outcome": "not_reported", "outcome_justification": "The snippet describes rescue/assistance to flood-affected residents but does not mention any forecast, warning, or early warning dissemination.", "relevant": false, "review": false, "summary_en": "The Coast Guard assisted 15 families (44 adults and 17 minors) in the Los Pescadores neighbourhood affected by the rising Paraná and Paraguay rivers. The snippet reports assistance only, with no mention of monitoring, forecasts, warnings or their dissemination.", "summary_original": "Prefectura asistió a 15 familias del barrio Los Pescadores, integradas por 44 adultos y 17 menores, afectadas por la crecida de los ríos Paraná y Paraguay.", "title_en": "Coast Guard assists residents affected by flooding of the Paraná and Paraguay rivers", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(4453,'claude-haiku-5-5','2026-10-24T03:15:35Z',1,0.85,0,'{"actions_taken": ["Evacuation of residents (913 evacuated, 281 self-evacuated)"], "agencies": [{"country": "AR", "name": "Defensa Civil (Chaco)", "type": "other_national_agency"}, {"country": "AR", "name": "Servicio Meteorológico Nacional", "type": "NMHS"}], "confidence": 0.85, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Chaco Province, Argentina", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 1194, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La crecida del Paraná complica al Chaco: hay más de 1.100 evacuados y rutas cortadas", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and flooded roads but does not state whether warnings were timely or how they were disseminated.", "relevant": true, "review": false, "summary_en": "Civil Defence in Chaco Province recorded 913 evacuees and 281 self-evacuees as the Paraná river flood covered parts of provincial route 63 and hampered access to riverside towns. The National Meteorological Service maintains a yellow alert for storms over the coming weekend.", "summary_original": "Defensa Civil contabilizó 913 evacuados y 281 autoevacuados por la crecida del Paraná en Chaco, que cubrió parte de la ruta provincial 63. El Servicio Meteorológico Nacional mantiene una alerta amarilla por tormentas para el fin de semana.", "title_en": "The Paraná flood complicates the Chaco: more than 1,100 evacuated and roads cut", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(4454,'claude-haiku-5-5','2026-10-24T03:16:16Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "AR", "name": "INA (Instituto Nacional del Agua)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["AR"], "dissemination_channels": ["website"], "event_date": "2026-10-23", "event_location": "Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "about 11 days (forecast for 3 November)", "lead_time_hours": 264, "original_title": "El Paraná sigue subiendo en Santa Fe: el INA proyecta casi cinco metros para principios de noviembre y advierte que la crecida podría prolongarse", "outcome": "not_reported", "outcome_justification": "The item reports a river-level forecast and alert-level exceedance in Reconquista and Goya, but no outcome of the warning is described.", "relevant": true, "review": false, "summary_en": "The national water institute INA recorded 3.92 m on the Paraná at Santa Fe and projects a rise to 4.92 m by 3 November. The flood already exceeds the alert level at Reconquista and Goya, and forecast rainfall could prolong the rise.", "summary_original": "El INA registró 3,92 metros en Santa Fe y proyecta que el Paraná alcance los 4,92 metros el 3 de noviembre. La crecida ya supera el nivel de alerta en Reconquista y Goya, mientras que las lluvias previstas podrían prolongar el ascenso del río.", "title_en": "The Paraná keeps rising in Santa Fe: INA projects nearly five metres by early November and warns the flood could last longer", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(4455,'claude-haiku-5-5','2026-10-24T03:15:39Z',1,0.9,0,'{"actions_taken": ["Reconquista declared a water emergency"], "agencies": [{"country": "AR", "name": "INA (Instituto Nacional del Agua)", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-23", "event_location": "Puerto Reconquista, Argentina", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "from Saturday onward (forecast of reaching the evacuation threshold)", "lead_time_hours": null, "original_title": "Crecida del Paraná: Reconquista declaró la emergencia hídrica y el río quedó al borde del nivel de evacuación", "outcome": "not_reported", "outcome_justification": "The item reports the river at 5.22 m, 8 cm below the evacuation mark, with INA forecasting a rise to that threshold; no outcome of the warning is yet reported.", "relevant": true, "review": false, "summary_en": "The Paraná river reached 5.22 m at Puerto Reconquista, 8 cm below the evacuation mark. INA forecasts that the river could reach the evacuation threshold from Saturday and continue rising in the following days. Reconquista has declared a water emergency in response.", "summary_original": "El río llegó a los 5,22 metros en Puerto Reconquista y quedó a ocho centímetros de la marca de evacuación. El INA prevé que podría alcanzar ese umbral desde este sábado y proyecta que la altura continúe en ascenso.", "title_en": "Paraná flood: Reconquista declares water emergency and river is at the edge of evacuation level", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(4460,'claude-haiku-5-5','2026-10-24T03:15:15Z',1,0.97,0,'{"actions_taken": ["Red alert issued for heavy rain and winds in six coastal regions"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.97, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": "2026-10-22", "event_location": "Coastal regions, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "Warning valid from 17:00 on Thursday 22 October to midday Saturday 24 October", "lead_time_hours": null, "original_title": "Senamhi activa ALERTA ROJA por FUERTES LLUVIAS en SEIS REGIONES desde mañana", "outcome": "not_reported", "outcome_justification": "The snippet reports the issuance of a red alert but gives no information on outcomes or impacts.", "relevant": true, "review": false, "summary_en": "Peru''s national meteorological service, Senamhi, issued a red alert for heavy rain and winds across six coastal regions, valid from 17:00 on 22 October to midday on 24 October 2026. This is an official warning issued by an NMHS ahead of a hazardous event.", "summary_original": "El Senamhi emitió una alerta roja por lluvias y vientos en seis regiones costeras de Perú, con vigencia desde las 5:00 p.m. del jueves 22 hasta el mediodía del sábado 24 de octubre.", "title_en": "Senamhi activates RED ALERT for heavy rain in six regions from tomorrow", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(4465,'claude-haiku-5-5','2026-10-24T03:16:45Z',1,0.85,0,'{"actions_taken": ["Installation of new observation stations to monitor intense rainfall in Ica and Palpa"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": [], "event_date": null, "event_location": "Ica and Palpa, Peru", "event_name": null, "ew4all_pillars": [2], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "MINAM: SENAMHI instalará nuevas estaciones para monitorear lluvias intensas en Ica y Palpa", "outcome": "not_reported", "outcome_justification": "The item announces planned installation of monitoring stations; no outcome of warnings is reported.", "relevant": true, "review": false, "summary_en": "SENAMHI, through its Zonal Directorate 05 and the Observation Networks Management Subdirectorate, is installing new stations to monitor intense rainfall in Ica and Palpa, Peru. The initiative strengthens detection and monitoring capacity for heavy rain hazards in these regions.", "summary_original": "SENAMHI, a través de la Dirección Zonal 05 y la Subdirección de Gestión de Redes de Observación, instalará nuevas estaciones para monitorear lluvias intensas en Ica y Palpa, fortaleciendo la vigilancia de precipitaciones en la zona.", "title_en": "MINAM: SENAMHI will install new stations to monitor intense rains in Ica and Palpa", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(4466,'claude-haiku-5-5','2026-10-24T03:16:48Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "wildfire", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "SENAMHI: Lluvias reducen temporalmente condiciones para la propagación de incendios forestales en la sierra y selva", "outcome": "not_reported", "outcome_justification": "The snippet reports SENAMHI''s assessment that rainfall temporarily reduced atmospheric conditions favourable to wildfire spread, but gives no information on warnings received or actions taken.", "relevant": true, "review": false, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, reports that rainfall in several areas temporarily reduced the atmospheric conditions favourable to wildfire spread in the highlands and jungle regions. The item is a monitoring and assessment update from the NMHS published on its news portal, but the snippet does not describe specific warnings, forecasts or dissemination.", "summary_original": "El SENAMHI informa que las lluvias en diversos sectores del país redujeron temporalmente las condiciones atmosféricas favorables para la propagación de incendios forestales en la sierra y selva.", "title_en": "SENAMHI: Rains temporarily reduce conditions for wildfire spread in the highlands and jungle", "wmo_regions": ["III"]}');
