INSERT INTO "classifications" VALUES(5363,'claude-haiku-5-5','2026-10-26T04:16:38Z',0,0.7,0,'{"actions_taken": ["Evacuations", "Assistance operations deployed by authorities"], "agencies": [], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Neuquén, Chaco and Corrientes provinces, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 1700, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Tormentas, crecidas y más de 1.700 evacuados: cómo impacta El Niño en Neuquén, Chaco y Corrientes", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations and flooding but does not state whether warnings were issued, disseminated, or how they performed.", "relevant": false, "review": false, "summary_en": "Intense rains in Neuquén, Chaco and Corrientes provinces of Argentina led to evacuations of more than 1,700 people, road cuts and serious flooding linked to El Niño. Authorities deployed assistance operations as water advanced over homes and productive areas. The snippet does not describe monitoring, forecasts or warnings issued before the event.", "summary_original": "Intensas lluvias en Neuquén, Chaco y Corrientes provocaron evacuaciones de más de 1.700 personas, cortes de caminos e inundaciones graves vinculadas a El Niño. Las autoridades desplegaron operativos de asistencia mientras el agua avanzaba sobre viviendas y zonas productivas.", "title_en": "Storms, floods and more than 1,700 evacuated: how El Niño impacts Neuquén, Chaco and Corrientes", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5366,'claude-haiku-5-5','2026-10-26T04:16:12Z',0,0.35,1,'{"actions_taken": ["Provincial governments deployed assistance and prevention operations"], "agencies": [{"country": "AR", "name": "Radio Mitre", "type": "media"}], "confidence": 0.35, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Neuquén, Chaco and Corrientes provinces, Argentina", "event_name": null, "ew4all_pillars": [], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Fuertes inundaciones en Neuquén, Chaco y Corrientes por El Niño: evacuados, parajes aislados y rutas afectadas", "outcome": "not_reported", "outcome_justification": "The snippet reports flooding and evacuations but does not mention any warnings, forecasts or early warning dissemination; the only warning-adjacent element is a general reference to an El Niño scenario.", "relevant": false, "review": true, "summary_en": "Flooding linked to intense rains and rising rivers has put parts of Neuquén, Chaco and Corrientes in emergency, with families isolated, roads cut and residents evacuated. Provincial governments deployed assistance and prevention operations amid a scenario associated with El Niño. The snippet does not describe any monitoring, forecasts or warnings issued in advance.", "summary_original": "Las inundaciones por lluvias intensas y el aumento de los ríos mantienen en emergencia zonas de Neuquén, Chaco y Corrientes, con familias aisladas, caminos cortados y vecinos evacuados. Los gobiernos provinciales desplegaron operativos de asistencia y prevención ante un escenario asociado a El Niño.", "title_en": "Heavy floods in Neuquén, Chaco and Corrientes due to El Niño: evacuees, isolated settlements and affected roads", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5367,'claude-haiku-5-5','2026-10-26T04:15:46Z',1,0.85,0,'{"actions_taken": ["Tsunami alert issued and later withdrawn by authorities"], "agencies": [], "confidence": 0.85, "countries": ["VU"], "dissemination_channels": [], "event_date": "2026-10-24", "event_location": "Vanuatu", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Un terremoto de 6,9 sacude Vanuatu y desata una alerta por tsunami", "outcome": "not_reported", "outcome_justification": "The snippet reports a tsunami alert being issued and then lifted while damage was assessed, but gives no information on impacts or whether the warning was received or acted upon.", "relevant": true, "review": false, "summary_en": "A magnitude 6.9 earthquake struck the South Pacific near Vanuatu, followed by a magnitude 6.3 aftershock. Authorities issued a tsunami alert, which was withdrawn while they assessed possible effects. The snippet does not describe impacts or how the warning was disseminated.", "summary_original": "Un potente seísmo golpea el Pacífico Sur, seguido de una réplica de magnitud 6,3. Las autoridades retiran la alerta de tsunami mientras evalúan los posibles efectos.", "title_en": "A magnitude 6.9 earthquake shakes Vanuatu and triggers a tsunami alert", "wmo_regions": ["V"]}');
INSERT INTO "classifications" VALUES(5373,'claude-haiku-5-5','2026-10-26T04:16:43Z',1,0.8,0,'{"actions_taken": ["Held national workshop to update procedures for elaborating meteorological warnings"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": [], "event_date": null, "event_location": "Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "SENAMHI reunió a especialistas de todo el país para actualizar procedimientos de elaboración de avisos meteorológicos", "outcome": "not_reported", "outcome_justification": "The item describes an internal procedural update workshop; no hazard event or warning outcome is reported.", "relevant": true, "review": false, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, held a national workshop with specialists from across the country to update its procedures for issuing meteorological warnings. The item concerns the institutional process for warning production rather than a specific hazard event. It is relevant to the forecasting and warning pillars of Early Warnings for All.", "summary_original": "El SENAMHI de Perú desarrolló un taller nacional con especialistas de todo el país para actualizar los procedimientos de elaboración de avisos meteorológicos.", "title_en": "SENAMHI gathered specialists from across the country to update procedures for issuing meteorological warnings", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(5374,'claude-haiku-5-5','2026-10-26T04:16:46Z',1,0.9,0,'{"actions_taken": ["INDECI recommends preparedness measures in response to SENAMHI Aviso N.° 435 (red level)"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "North coast and highlands, Peru", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante la continuidad de las precipitaciones en la costa norte y sierra.", "outcome": "not_reported", "outcome_justification": "The snippet describes a recommendation issued in response to a SENAMHI red-level warning but reports no outcome.", "relevant": true, "review": false, "summary_en": "INDECI issued a press release recommending preparedness measures in response to SENAMHI Aviso N.° 435 (red level), which warns of continued light to moderate rainfall in the highlands and north coast of Peru. The notice shows a national agency relaying an NMHS red-level warning to the public and response actors. No outcome is reported in the snippet.", "summary_original": "INDECI recomienda adoptar medidas de preparación ante el Aviso N.° 435 (nivel rojo) del SENAMHI, que informa sobre la continuidad de las precipitaciones de ligera a moderada intensidad en la sierra y costa norte del Perú.", "title_en": "INDECI recommends preparedness measures ahead of continued rainfall on the north coast and highlands", "wmo_regions": ["III"]}');
