INSERT INTO "classifications" VALUES(6664,'claude-haiku-5-5','2026-10-29T04:17:19Z',1,0.85,0,'{"actions_taken": ["Heavy rain and linear rainband (senjō kōsuitai) warning/alert issued for Wakayama Prefecture; strict vigilance against landslides urged"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["tv"], "event_date": "2026-10-27", "event_location": "Wakayama Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "within the next 3 hours", "lead_time_hours": 3, "original_title": "台風と秋雨前線で大雨に 和歌山県 線状降水帯の恐れ（テレビ朝日系（ANN）） - Yahoo!ニュース - News", "outcome": "not_reported", "outcome_justification": "The snippet reports an alert of a possible linear rainband within 3 hours but gives no information on actual rainfall, impacts or public response.", "relevant": true, "review": false, "summary_en": "Japanese broadcaster TV Asahi (ANN) reports that Wakayama Prefecture may see a linear rainband develop within the next 3 hours, caused by a typhoon interacting with an autumn rain front. Authorities advise strict vigilance against landslides and other sediment disasters. The item conveys a short-range heavy rain warning but no outcome information.", "summary_original": "和歌山県では今後3時間以内に線状降水帯が発生する恐れがあり、土砂災害などに厳重な警戒が必要とされている。台風と秋雨前線の影響による大雨の予測・警戒情報。", "title_en": "Typhoon and autumn rain front bring heavy rain; Wakayama Prefecture at risk of linear rainband (TV Asahi/ANN, via Yahoo! News)", "wmo_regions": ["II"]}');
