INSERT INTO "classifications" VALUES(6926,'claude-haiku-5-5','2026-10-30T04:19:19Z',1,0.8,0,'{"actions_taken": ["Anticipatory action framework prepared for tropical storms and hurricanes ahead of the Atlantic hurricane season"], "agencies": [{"country": null, "name": "UN Office for the Coordination of Humanitarian Affairs", "type": "international"}, {"country": null, "name": "United Nations Development Programme", "type": "international"}], "confidence": 0.8, "countries": ["HT"], "dissemination_channels": [], "event_date": null, "event_location": "Haiti", "event_name": null, "ew4all_pillars": [1, 2, 4], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "en", "lead_time": null, "lead_time_hours": null, "original_title": "Haiti: Haïti: Cadre d’Action Anticipatoire Tempêtes/Ouragans", "outcome": "not_reported", "outcome_justification": "The item describes a planning framework for anticipatory action; no hazard event outcome is reported.", "relevant": true, "review": false, "summary_en": "An OCHA document presents an anticipatory action framework for storms and hurricanes in Haiti, noting that about 96 per cent of the population is exposed to climate-related hazards. The framework aims to ensure preparedness before the 1 June to 30 November Atlantic hurricane season. It concerns early action planning rather than a specific event.", "summary_original": null, "title_en": "Haiti: Anticipatory Action Framework for Storms/Hurricanes", "wmo_regions": ["IV"]}');
