INSERT INTO "classifications" VALUES(7981,'claude-haiku-5-5','2026-11-01T04:18:28Z',1,0.9,0,'{"actions_taken": ["Sinaproc extended the prevention notice for rain and storms until 3 November"], "agencies": [{"country": "PA", "name": "Sinaproc", "type": "other_national_agency"}, {"country": "PA", "name": "Imhpa", "type": "NMHS"}], "confidence": 0.9, "countries": ["PA"], "dissemination_channels": [], "event_date": "2026-10-30", "event_location": "Panama", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Nueva alerta meteorológica en Panamá agrava la preocupación por las zonas devastadas por el terremoto - Infobae", "outcome": "not_reported", "outcome_justification": "The item reports a warning issued and extended but does not describe its impacts or how it was received.", "relevant": true, "review": false, "summary_en": "Panama''s civil protection agency Sinaproc extended until 3 November a prevention notice for rain and storms covering much of the country, including areas hit by the 9 October earthquake. The national meteorological service Imhpa warns of possible flooding, flash floods in rivers, landslides and strong gusts of wind.", "summary_original": "El Sinaproc extendió hasta el 3 de noviembre el aviso de prevención por lluvias y tormentas en gran parte de Panamá, coincidiendo con zonas afectadas por el terremoto del 9 de octubre. El Imhpa advierte sobre posibles inundaciones, crecidas repentinas de ríos, deslizamientos y ráfagas de viento.", "title_en": "New weather alert in Panama heightens concern for areas devastated by earthquake", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(7982,'claude-haiku-5-5','2026-11-01T04:18:30Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "MX", "name": "Coordinación Estatal de Protección Civil de Baja California", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["MX"], "dissemination_channels": ["other"], "event_date": "2026-10-31", "event_location": "Baja California, Mexico", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "until Sunday 1 November 2026", "lead_time_hours": null, "original_title": "Advierte Protección Civil por aumento en el pronóstico de lluvias muy fuertes y alerta por riesgo de inundaciones", "outcome": "not_reported", "outcome_justification": "The item reports a warning and forecast of heavy rain, strong winds and cooling but gives no information on outcomes or impacts.", "relevant": true, "review": false, "summary_en": "The Baja California State Civil Protection Coordination warned that the potential for heavy rains, locally very heavy, strong winds and falling temperatures is increasing until Sunday 1 November 2026. Accumulations above 50 mm are expected across the state''s seven municipalities, raising flood risk.", "summary_original": "La Coordinación Estatal de Protección Civil de Baja California advirtió un aumento del potencial de lluvias fuertes, puntualmente muy fuertes, con vientos intensos y descenso de temperaturas hasta el domingo 1 de noviembre, con acumulados mayores a 50 mm en los siete municipios.", "title_en": "State Civil Protection warns of increased forecast for very heavy rains and flood risk", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(7983,'claude-haiku-5-5','2026-11-01T04:18:34Z',1,0.9,0,'{"actions_taken": ["Ideam issued a preventive hydrological alert for the Gulf of Urabá and other Antioquia basins", "Río León basin declared in red hydrological alert", "Dimar warned of strong swell and high tides on the Caribbean Coast until 1 November"], "agencies": [{"country": "CO", "name": "Ideam", "type": "NMHS"}, {"country": "CO", "name": "Dimar", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["CO"], "dissemination_channels": [], "event_date": "2026-11-01", "event_location": "Golfo de Urabá, Antioquia, Colombia", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "¡Alerta en el Golfo de Urabá! Ideam advierte inundaciones y fuerte oleaje en la Costa Caribe", "outcome": "not_reported", "outcome_justification": "The snippet reports warnings issued but no outcomes, impacts or responses are described.", "relevant": true, "review": false, "summary_en": "Colombia''s meteorological service Ideam issued a preventive hydrological alert for the Gulf of Urabá and other Antioquia basins over the probability of flooding and overflows, and declared the León river basin in red hydrological alert. The maritime agency Dimar warned of strong swell and high tides on the Caribbean Coast until 1 November.", "summary_original": "El Ideam emitió una alerta hidrológica preventiva para el Golfo de Urabá y otras cuencas de Antioquia por probabilidad de inundaciones y desbordamientos, y la cuenca del río León fue declarada en alerta roja hidrológica. La Dimar advierte fuerte oleaje en la Costa Caribe y mareas altas hasta el 1 de noviembre.", "title_en": "Alert in the Gulf of Urabá! Ideam warns of floods and strong swell on the Caribbean Coast", "wmo_regions": ["III", "IV"]}');
INSERT INTO "classifications" VALUES(7984,'claude-haiku-5-5','2026-11-01T04:18:37Z',1,0.9,0,'{"actions_taken": ["Senamhi activated a new red alert for strong to extreme rainfall in Tumbes and Piura", "EMAPE completed cleanup work after the 29/10 flood in Villa María del Triunfo"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "COEN-Indeci", "type": "other_national_agency"}, {"country": "PE", "name": "EMAPE", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": "2026-11-01", "event_location": "Tumbes and Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Lluvias en el norte del Perú hoy EN VIVO: Piura, Tumbes y Lambayeque en alerta por precipitaciones", "outcome": "not_reported", "outcome_justification": "The snippet reports an issued red alert and a completed cleanup after a prior flood but gives no information on whether warnings were received or acted upon.", "relevant": true, "review": false, "summary_en": "Senamhi activated a new red alert for strong to extreme rainfall in the Peruvian regions of Tumbes and Piura, while Lambayeque is also listed on alert. COEN-Indeci reported that EMAPE finished cleanup after a flood on 29 October in Villa María del Triunfo.", "summary_original": "Senamhi activó una nueva alerta roja por precipitaciones de fuerte a extrema intensidad en Tumbes y Piura, y el COEN-Indeci informó que EMAPE culminó la limpieza tras la inundación del 29/10 en Villa María del Triunfo.", "title_en": "Rain in northern Peru LIVE: Piura, Tumbes and Lambayeque on alert for rainfall", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(7985,'claude-haiku-5-5','2026-11-01T04:18:55Z',1,0.8,0,'{"actions_taken": ["Participation in the II Regional Forum on El Niño and Piura agriculture on prevention, mitigation and preparedness for climate events"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": null, "event_location": "Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "SENAMHI presenta perspectivas climáticas y escenarios de El Niño para fortalecer la preparación del agro piurano", "outcome": "not_reported", "outcome_justification": "The snippet describes a forum presenting climate outlooks and El Niño scenarios but reports no outcomes of warnings.", "relevant": true, "review": false, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, took part in the second regional forum on El Niño and Piura agriculture, presenting climate outlooks and El Niño scenarios. The aim is to strengthen agricultural preparedness for climate events through prevention and mitigation actions. The item concerns forecasting and preparedness rather than a specific warning outcome.", "summary_original": "El SENAMHI participó en el II Foro Regional Fenómeno El Niño y Agro Piurano, presentando perspectivas climáticas y escenarios de El Niño para fortalecer la preparación frente a eventos climáticos.", "title_en": "SENAMHI presents climate outlooks and El Niño scenarios to strengthen Piura agriculture preparedness", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(7986,'claude-haiku-5-5','2026-11-01T04:18:58Z',1,0.6,0,'{"actions_taken": ["Second technical visit by SENAMHI and Consorcio S&F to exchange information on the operation of a meteorological radar supporting the Quebrada Cansas integral solution project"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}, {"country": "PE", "name": "Consorcio S&F", "type": "other"}], "confidence": 0.6, "countries": ["PE"], "dissemination_channels": [], "event_date": null, "event_location": "Quebrada Cansas, Peru", "event_name": null, "ew4all_pillars": [2], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "SENAMHI y Consorcio S&F realizan visita técnica para intercambiar información sobre el funcionamiento del radar meteorológico", "outcome": "not_reported", "outcome_justification": "The snippet describes a technical coordination visit about radar operation; no warning outcome is reported.", "relevant": true, "review": false, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, held a second technical visit with Consorcio S&F, the contractor for the Quebrada Cansas integral solution project, to exchange information on how the meteorological radar operates. The item concerns monitoring infrastructure supporting hazard detection, but reports no warning issued or outcome.", "summary_original": "El SENAMHI realizó una segunda visita técnica junto al Consorcio S&F, a cargo del proyecto \"Solución Integral de la Quebrada Cansas\", para intercambiar información sobre el funcionamiento del radar meteorológico.", "title_en": "SENAMHI and Consorcio S&F carry out technical visit to exchange information on the operation of the meteorological radar", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(7990,'claude-haiku-5-5','2026-11-01T04:19:01Z',1,0.93,0,'{"actions_taken": ["INDECI recommends preparedness measures in response to SENAMHI meteorological warning No. 450 (orange level)"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.93, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": null, "event_location": "Central and southern coast, Peru", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante precipitaciones en la costa centro y sur", "outcome": "not_reported", "outcome_justification": "The snippet describes the issuance of a warning and recommended preparedness measures but reports no outcome.", "relevant": true, "review": false, "summary_en": "INDECI, Peru''s national civil defence institute, issued preparedness recommendations following SENAMHI meteorological warning No. 450 at orange level, which forecasts moderate to heavy rain and/or drizzle on the central and southern coast. The warning concerns the communication of an impending precipitation event and the measures recommended in response.", "summary_original": "INDECI recomienda medidas de preparación ante el aviso meteorológico N.° 450 (nivel naranja) del SENAMHI, que informa sobre precipitaciones (lluvia y/o lloviznas) de moderada a fuerte intensidad en la costa centro y sur.", "title_en": "INDECI recommends preparedness measures for rainfall on the central and southern coast", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8134,'claude-haiku-5-5','2026-11-01T04:18:48Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "ENFEN", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-10-31", "event_location": "Coast of Peru, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heatwave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "months ahead (seasonal outlook)", "lead_time_hours": null, "original_title": "Calor extremo en Perú: ENFEN prevé nuevos récords de temperatura en toda la costa durante los próximos meses", "outcome": "not_reported", "outcome_justification": "The item reports a forecast/communiqué of expected heat and rainfall but no reported outcomes or actions taken yet.", "relevant": true, "review": false, "summary_en": "ENFEN''s latest communiqué warns that sea warming will keep air temperatures well above normal along Peru''s coast in the coming months, with new temperature records possible. It also forecasts above-normal rainfall in the northern and central coast.", "summary_original": "El último comunicado del ENFEN advierte que el calentamiento del mar mantendrá las temperaturas del aire muy por encima de sus valores habituales, y pronostica lluvias superiores a lo normal en la costa norte y central.", "title_en": "Extreme heat in Peru: ENFEN forecasts new temperature records across the coast in the coming months", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8192,'claude-haiku-5-5','2026-11-02T04:15:33Z',0,0.9,0,'{"actions_taken": [], "agencies": [{"country": null, "name": "Famine Early Warning System Network", "type": "international"}], "confidence": 0.9, "countries": ["CM"], "dissemination_channels": [], "event_date": "2026-11-02", "event_location": "Northwest and Southwest regions, Cameroon", "event_name": null, "ew4all_pillars": [], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "en", "lead_time": null, "lead_time_hours": null, "original_title": "Cameroon Food Security Outlook Update, October 2026 - May 2027: Conflict compounded by rainfall deficits to sustain elevated assistance needs through May", "outcome": "not_reported", "outcome_justification": "Food security outlook driven mainly by conflict and humanitarian assistance gaps; no hazard warning, forecast-based action, or dissemination of a hydrometeorological warning is described in the snippet.", "relevant": false, "review": false, "summary_en": "A FEWS NET food security outlook for Cameroon projects IPC Phase 3 (Crisis) outcomes across the Northwest and Southwest regions through May 2027, with some households facing IPC Phase 4 (Emergency), driven by insecurity and rainfall deficits. The item concerns food insecurity rather than early warning services for a natural hazard event.", "summary_original": null, "title_en": "Cameroon Food Security Outlook Update, October 2026 - May 2027: Conflict compounded by rainfall deficits to sustain elevated assistance needs through May", "wmo_regions": ["I"]}');
INSERT INTO "classifications" VALUES(8193,'claude-haiku-5-5','2026-11-02T04:15:53Z',1,0.6,0,'{"actions_taken": ["Urged countries to strengthen surveillance and preparedness for Rift Valley fever risk linked to heavy rainfall and flooding"], "agencies": [{"country": null, "name": "Food and Agriculture Organization of the United Nations (FAO)", "type": "international"}, {"country": null, "name": "Intergovernmental Authority on Development (IGAD)", "type": "international"}], "confidence": 0.6, "countries": ["BI", "ET", "KE", "KM", "MG", "RW", "SA", "SD", "SO", "SS", "TZ", "UG", "YE"], "dissemination_channels": [], "event_date": "2026-10-30", "event_location": null, "event_name": null, "ew4all_pillars": [2, 3], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "en", "lead_time": null, "lead_time_hours": null, "original_title": "Ethiopia: El Niño heightens risk of Rift Valley fever outbreaks in Eastern Africa, FAO and IGAD warn", "outcome": "not_reported", "outcome_justification": "The item is an advisory alert; no outcomes of warnings are reported.", "relevant": true, "review": false, "summary_en": "FAO and IGAD issued an alert warning that El Niño-linked heavy rainfall and flooding increase the risk of Rift Valley fever outbreaks across Eastern Africa and the Arabian Peninsula. They urge countries to strengthen surveillance and preparedness measures. The item concerns an advisory for a health-related hazard driven by a climate event, which is treated as relevant given its early-warning framing.", "summary_original": null, "title_en": "Ethiopia: El Niño heightens risk of Rift Valley fever outbreaks in Eastern Africa, FAO and IGAD warn", "wmo_regions": ["I", "II"]}');
