INSERT INTO "classifications" VALUES(8283,'claude-haiku-5-5','2026-11-02T04:15:36Z',1,0.85,0,'{"actions_taken": ["Lowering of the Tokachidake volcanic alert level to level 2 (restriction of access around the crater)", "Accommodation facilities in the Fukiage hot spring area of Kamikawa town resumed operations"], "agencies": [{"country": "JP", "name": "NHK", "type": "media"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-11-01", "event_location": "Kamikawa, Hokkaido, Japan", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "十勝岳噴火警戒レベルの引き下げ受け宿泊施設が営業再開", "outcome": "positive", "outcome_justification": "Lowering of the alert level allowed local businesses to reopen, indicating the warning system''s level changes were acted upon and reflected in community response.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency lowered the Tokachidake volcano alert level to level 2, which restricts access around the crater. Following this change, accommodation facilities in the Fukiage hot spring area of Kamikawa town, Hokkaido, resumed operations. The item illustrates how volcanic alert level changes feed into local response decisions.", "summary_original": "大雪山系の十勝岳の噴火警戒レベルが火口周辺規制を示す「2」に引き下げられたことを受けて、北海道上富良野町の吹上温泉地区で宿泊施設が営業を再開しました。", "title_en": "Accommodation facilities resume operations after Tokachidake eruption warning level lowered", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(8340,'claude-haiku-5-5','2026-11-02T04:15:19Z',1,0.97,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "INDECI (COEN)", "type": "other_national_agency"}], "confidence": 0.97, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": "2026-11-02", "event_location": "Piura and Tumbes, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Tumbes y Piura bajo alerta roja por lluvias intensas para esta noche: estas son las provincias que podrían registrar precipitaciones extremas - Infobae", "outcome": "not_reported", "outcome_justification": "The snippet reports a red alert issued for intense rain in eight Piura provinces and three Tumbes provinces, valid until 2 November, but no impacts or outcomes are described.", "relevant": true, "review": false, "summary_en": "Peru''s National Service of Meteorology and Hydrology (Senamhi) issued a red alert for intense rainfall affecting eight provinces in Piura and three in Tumbes, valid until Monday 2 November. The alert is documented in official bulletin No. 304-2026-INDECI/COEN. The article covers the warning itself; no impacts or outcomes are reported in the snippet.", "summary_original": "El Senamhi emitió alerta roja por lluvias intensas en ocho provincias de Piura y tres de Tumbes, vigente hasta el lunes 2 de noviembre. El boletín oficial es el N.° 304-2026-INDECI/COEN.", "title_en": "Tumbes and Piura under red alert for intense rain tonight: these are the provinces that could record extreme precipitation", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8341,'claude-haiku-5-5','2026-11-02T04:15:47Z',1,0.93,0,'{"actions_taken": ["Government mobilized resources toward northern Peru"], "agencies": [{"country": "PE", "name": "Government of Peru", "type": "other_national_agency"}], "confidence": 0.93, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-11-02", "event_location": "Tumbes and Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Tumbes y Piura en alerta roja por lluvias extremas: por qué las precipitaciones podrían superar los 100 mm apuesplan", "outcome": "not_reported", "outcome_justification": "The snippet reports red alert warnings and resource mobilization but gives no information on the results of the warnings.", "relevant": true, "review": false, "summary_en": "Tumbes and Piura provinces in northern Peru are under a red alert until Monday 2 November due to heavy to extreme rainfall, with totals in Tumbes that could exceed 100 mm. The government has mobilized resources toward the north of the country in response.", "summary_original": "Las provincias de Tumbes y Piura están en alerta roja hasta el lunes 2 de noviembre por lluvias de fuerte a extrema intensidad, que podrían superar los 100 mm en Tumbes. El Gobierno movilizó recursos hacia el norte del país.", "title_en": "Tumbes and Piura on red alert due to extreme rainfall: why precipitation could exceed 100 mm", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8342,'claude-haiku-5-5','2026-11-02T04:15:22Z',1,0.93,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "COEN", "type": "other_national_agency"}, {"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.93, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-02", "event_location": "Tumbes and Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "Senamhi issued a prior warning on 27 October, several days before the event", "lead_time_hours": null, "original_title": "Tumbes y Piura bajo alerta por lluvias extremas: COEN reporta nivel rojo en tres provincias", "outcome": "not_reported", "outcome_justification": "The snippet reports red-level warnings and an earlier Senamhi advisory but does not describe the impacts or how the warnings were acted upon.", "relevant": true, "review": false, "summary_en": "COEN reported a red-level alert for intense rain in Tumbes and eight provinces of Piura until 2 November, with possible electrical discharges and gusts near 40 km/h. Senamhi had issued an earlier warning on 27 October.", "summary_original": "El COEN reporta nivel rojo de lluvias intensas hasta el 2 de noviembre en Tumbes y ocho provincias de Piura, con posibles descargas eléctricas y ráfagas cercanas a 40 km/h. El Senamhi había emitido un aviso previo el 27 de octubre.", "title_en": "Tumbes and Piura under extreme rain alert: COEN reports red level in three provinces", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8343,'claude-haiku-5-5','2026-11-02T04:15:39Z',1,0.93,0,'{"actions_taken": ["COEN issued a bulletin establishing a red alert across all of Tumbes territory"], "agencies": [{"country": "PE", "name": "COEN (Centro de Operaciones de Emergencia Nacional)", "type": "other_national_agency"}, {"country": "PE", "name": "Midagri (Ministerio de Desarrollo Agrario y Riego)", "type": "other_national_agency"}], "confidence": 0.93, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-01", "event_location": "Tumbes, Peru", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "1 to 2 days before expected rainfall (1-2 November)", "lead_time_hours": null, "original_title": "Alerta roja en Tumbes: COEN y Midagri prevén lluvias extremas del 1 al 2 de noviembre", "outcome": "not_reported", "outcome_justification": "The snippet reports the red alert and rainfall forecast but gives no information on the outcome of the warning.", "relevant": true, "review": false, "summary_en": "Peru''s National Emergency Operations Centre (COEN) issued a bulletin placing all of Tumbes under red alert for extreme rainfall that could exceed 100 mm between 1 and 2 November. The alert was issued jointly with Midagri''s forecast of extreme rain in the region.", "summary_original": "El COEN estableció mediante un boletín alerta roja en todo el territorio de Tumbes por lluvias extremas que podrían superar los 100 mm entre el 1 y el 2 de noviembre, junto con la previsión de Midagri.", "title_en": "Red alert in Tumbes: COEN and Midagri forecast extreme rainfall from 1 to 2 November", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8344,'claude-haiku-5-5','2026-11-02T04:15:49Z',1,0.85,0,'{"actions_taken": ["Preventive opening of five temporary shelters in Mexicali", "Alert issued by the state governor about very heavy rains from 31 October"], "agencies": [{"country": "MX", "name": "Gobierno de Baja California", "type": "other_national_agency"}, {"country": "MX", "name": "Gobierno de Mexicali", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["MX"], "dissemination_channels": ["other"], "event_date": "2026-10-31", "event_location": "Baja California, Mexico", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta por fuertes lluvias en Baja California; abren albergues en Mexicali y Ensenada", "outcome": "not_reported", "outcome_justification": "The snippet reports the warning and preventive shelter opening but gives no information on actual impacts or how the warning was received.", "relevant": true, "review": false, "summary_en": "The governor of Baja California warned of very heavy rains starting 31 October 2026. The Mexicali municipal government preventively enabled five temporary shelters in response. The snippet does not report outcomes or impacts.", "summary_original": "La gobernadora de Baja California alertó sobre lluvias muy fuertes desde el 31 de octubre, y el Gobierno de Mexicali habilitó de forma preventiva cinco albergues temporales.", "title_en": "Alert for heavy rains in Baja California; shelters opened in Mexicali and Ensenada", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(8345,'claude-haiku-5-5','2026-11-02T04:15:11Z',1,0.85,0,'{"actions_taken": ["Mandatory evacuation orders issued for affected areas", "Flood alerts issued for much of Arizona and other states"], "agencies": [{"country": "US", "name": "National Weather Service", "type": "NMHS"}], "confidence": 0.85, "countries": ["US"], "dissemination_channels": [], "event_date": "2026-11-02", "event_location": "Arizona, United States", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Las inundaciones repentinas provocan evacuaciones en el suroeste y una grave advertencia para una localidad termal de Colorado.", "outcome": "not_reported", "outcome_justification": "The snippet reports warnings and evacuation orders but does not state whether they were effective or what the outcome was.", "relevant": true, "review": false, "summary_en": "Heavy rain caused flash floods and mandatory evacuation orders in the southwestern United States, with the weather service issuing flood alerts for much of Arizona and other states. At least 100 homes were within the evacuation zone. The item concerns a warning for a Colorado hot-springs town as well.", "summary_original": "Lluvias fuertes provocaron inundaciones repentinas y órdenes de evacuación obligatoria en el suroeste de Estados Unidos, y el servicio meteorológico emitió alertas de inundación para gran parte de Arizona y otros estados. Al menos 100 viviendas estaban dentro de la zona de evacuación.", "title_en": "Flash floods trigger evacuations in the southwest and a serious warning for a Colorado hot-springs town", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(8456,'claude-haiku-5-5','2026-11-02T04:16:00Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": "AR", "name": "Servicio Meteorológico Nacional (SMN)", "type": "NMHS"}, {"country": "AR", "name": "Clarín", "type": "media"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": ["website"], "event_date": "2026-11-01", "event_location": "Buenos Aires Metropolitan Area, Argentina", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Súper Niño 2026 en Argentina, EN VIVO: llegan las tormentas al AMBA y rige alerta amarilla hasta la noche", "outcome": "not_reported", "outcome_justification": "The snippet reports SMN forecasts and yellow alerts for strong gusts and hail in Buenos Aires and nine other provinces, but no outcomes are given.", "relevant": true, "review": false, "summary_en": "Argentina''s National Meteorological Service anticipates wind gusts and occasional hail in the Buenos Aires metropolitan area, with yellow alerts in force and nine other provinces also under alert. The live coverage links these warnings to a potentially strong or very strong El Niño in central-eastern Argentina. No impacts or responses are reported in the snippet.", "summary_original": "El Servicio Meteorológico Nacional anticipa ráfagas de viento y ocasional caída de granizo en el AMBA, con alerta amarilla vigente y otras 9 provincias en alerta, en el marco de un El Niño que podría ser fuerte o muy fuerte en el centro-este del país.", "title_en": "Super El Niño 2026 in Argentina, LIVE: storms reach Buenos Aires metropolitan area and yellow alert in force until night", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8507,'claude-haiku-5-5','2026-11-02T04:15:57Z',1,0.9,0,'{"actions_taken": ["Declaration of a national Preventive Early Alert for heat from Arica y Parinacota to Magallanes and Chilean Antarctica"], "agencies": [{"country": "CL", "name": "Senapred (Servicio Nacional de Prevención y Respuesta ante Desastres)", "type": "other_national_agency"}, {"country": "CL", "name": "BioBioChile", "type": "media"}], "confidence": 0.9, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-11-01", "event_location": "Chile (national)", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heatwave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "Covers the summer period through March 2027", "lead_time_hours": null, "original_title": "Senapred declara Alerta Temprana Preventiva por calor en todo Chile hasta marzo de 2027", "outcome": "not_reported", "outcome_justification": "The snippet reports the declaration of the alert only; no outcomes are described.", "relevant": true, "review": false, "summary_en": "Senapred declared a national Preventive Early Alert for heat covering all of Chile, from Arica y Parinacota to Magallanes and Chilean Antarctica, in anticipation of high temperature events during the summer season and their potential risks to the population. The alert remains in effect until March 2027.", "summary_original": "Senapred declaró Alerta Temprana Preventiva Nacional por calor, ante los eventos de altas temperaturas previstos para el periodo estival y los riesgos que podrían representar para la población. La medida abarca desde Arica y Parinacota hasta Magallanes y la Antártica Chilena.", "title_en": "Senapred declares Preventive Early Alert for heat across all of Chile until March 2027", "wmo_regions": ["III"]}');
