INSERT INTO "classifications" VALUES(8928,'claude-haiku-5-5','2026-11-03T04:20:52Z',1,0.7,0,'{"actions_taken": ["Army evacuated families to safe zones"], "agencies": [{"country": "PE", "name": "Peruvian Army", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-11-02", "event_location": "Aguas Verdes, Zarumilla, Tumbes, Peru", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": 300, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Emergencia en Tumbes: desborde del río Zarumilla inunda Puerto Perú y obliga a evacuar a familias", "outcome": "not_reported", "outcome_justification": "The snippet reports evacuations after flooding but does not state whether warnings were issued in advance or how they were disseminated.", "relevant": true, "review": false, "summary_en": "Intense rains caused the Zarumilla River to overflow, flooding homes and streets in Aguas Verdes district, Tumbes. The Army evacuated families to safe areas, and more than 300 families were reportedly affected. The snippet does not describe any prior warnings or forecasts.", "summary_original": "Las lluvias intensas inundaron viviendas y calles en Aguas Verdes, provincia de Zarumilla. El Ejército evacuó a familias hacia zonas seguras y más de 300 familias resultaron perjudicadas.", "title_en": "Emergency in Tumbes: Zarumilla River overflow floods Puerto Peru and forces families to evacuate", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8935,'claude-haiku-5-5','2026-11-03T04:20:41Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-02", "event_location": "Lima, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heatwave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta roja del Senamhi en Lima: anuncian lluvias y lloviznas nocturnas en medio de feroz ola de calor", "outcome": "not_reported", "outcome_justification": "The snippet reports Senamhi forecasts and a red alert for Lima and 16 regions through Wednesday, but gives no information on actions taken or results.", "relevant": true, "review": false, "summary_en": "Peru''s national meteorological service Senamhi has activated a red alert for Lima and 16 regions through Wednesday, forecasting maximum temperatures up to 32°C, night drizzle and gusts of up to 45 km/h in the afternoons. The item covers a forecast and alert issued by the NMHS during a heatwave.", "summary_original": "Senamhi activó alerta roja para Lima y 16 regiones hasta el miércoles por una ola de calor, con temperaturas de hasta 32°C de día, llovizna nocturna y ráfagas de viento de hasta 45 km/h por las tardes.", "title_en": "Senamhi red alert in Lima: rain and night drizzle announced amid fierce heatwave", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8936,'claude-haiku-5-5','2026-11-03T04:20:57Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-11-02", "event_location": "Tumbes, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Lluvias extremas en Tumbes inundan calles y activan quebradas: Senamhi reporta máximo de 104,1 mm en 24 horas", "outcome": "not_reported", "outcome_justification": "The snippet reports flooding, isolated residents and river levels above the red alert threshold, and Senamhi warns rain may continue, but does not describe how warnings were disseminated or acted upon.", "relevant": true, "review": false, "summary_en": "Extreme rainfall in Tumbes and Zarumilla flooded roads, isolated residents and pushed the Tumbes river above its red alert threshold. Senamhi reported a 24-hour maximum of 104.1 mm and warned that rains could continue in northern Peru.", "summary_original": "Las precipitaciones afectaron vías de Tumbes y Zarumilla, dejaron pobladores aislados y elevaron el caudal del río Tumbes por encima del umbral de alerta roja. Senamhi advierte que las lluvias podrían continuar en el norte.", "title_en": "Extreme rains in Tumbes flood streets and activate ravines: Senamhi reports maximum of 104.1 mm in 24 hours", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(8939,'claude-haiku-5-5','2026-11-03T04:20:59Z',1,0.9,0,'{"actions_taken": [], "agencies": [], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-11-02", "event_location": "Tumbes, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Río Tumbes supera umbral de alerta roja y advierten riesgo de desbordes tras intensas lluvias", "outcome": "not_reported", "outcome_justification": "The item reports a red-level river alert and overflow warnings but does not describe the outcome of the warnings or any response actions.", "relevant": true, "review": false, "summary_en": "The Tumbes River reached 1,021.33 cubic metres per second in the early hours of Monday, surpassing its red alert threshold, and authorities warned of overflow risk. Intense rainfall flooded streets and activated ravines across several sectors of Tumbes. The item reports the river-level alert and warning but not the dissemination channels or outcomes.", "summary_original": "El caudal del río Tumbes alcanzó los 1.021,33 m³/s, superando el umbral de alerta roja, y se advierte riesgo de desbordes tras intensas lluvias que inundaron calles y activaron quebradas.", "title_en": "Tumbes River exceeds red alert threshold and warnings of overflow risk after intense rains", "wmo_regions": ["III"]}');
