INSERT INTO "classifications" VALUES(9112,'claude-haiku-5-5','2026-11-04T04:22:05Z',1,0.95,0,'{"actions_taken": ["JMA lowered the volcanic alert level (eruption warning level) for Mt. Meakan to Level 1"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.95, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-11-04", "event_location": "Mt. Meakan, Hokkaido, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "雌阿寒岳の噴火警戒レベルを１へ引下げ", "outcome": "not_reported", "outcome_justification": "The item is an official JMA press release on a volcanic alert level change; it does not report any impacts or outcomes of the warning.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency announced that the volcanic alert level for Mt. Meakan in Hokkaido has been lowered to Level 1, indicating reduced volcanic activity. The press release is an official alert-level update published on the JMA website. No impacts or public response details are given in the snippet.", "summary_original": "気象庁は、雌阿寒岳の噴火警戒レベルを1へ引き下げたと発表した。公式サイトで公表された噴火警戒レベルの変更に関する報道発表である。", "title_en": "Alert level for Mt. Meakan lowered to 1", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(9117,'claude-haiku-5-5','2026-11-04T04:21:59Z',1,0.85,0,'{"actions_taken": ["JMA called for caution against landslides and flooding of low-lying areas"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-11-04", "event_location": "Kanto region and Izu Islands, Japan", "event_name": "Typhoon No. 31", "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": "from late on 4 November to around midday on 5 November", "lead_time_hours": null, "original_title": "台風31号 暖湿気流入で関東や伊豆諸島 今夜遅くから大雨おそれ", "outcome": "not_reported", "outcome_justification": "The item reports forecast heavy rain and JMA''s advisory, but no outcomes of the warnings are given.", "relevant": true, "review": false, "summary_en": "JMA forecast that warm, moist air around Typhoon No. 31 would bring heavy rain to the Kanto region and Izu Islands from late on 4 November to around midday on 5 November. The agency urged residents to take sufficient precautions against landslides and flooding in low-lying areas.", "summary_original": "台風周辺の暖かく湿った空気の流入により、関東と伊豆諸島では4日遅くから5日昼ごろにかけて激しい雨が降り、大雨となるおそれがある。気象庁は土砂災害や低地の浸水に十分注意するよう呼びかけている。", "title_en": "Typhoon No. 31: warm moist air inflow raises risk of heavy rain in Kanto and Izu Islands from tonight", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(9129,'claude-haiku-5-5','2026-11-04T04:22:19Z',1,0.7,0,'{"actions_taken": ["Disaster preparedness drill simulating a Nankai Trough megaquake and tsunami"], "agencies": [{"country": "JP", "name": "Kushimoto Town", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-11-03", "event_location": "Kushimoto, Wakayama, Japan", "event_name": null, "ew4all_pillars": [4], "hazard": "tsunami", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "「世界津波の日」前に南海トラフ巨大地震想定し訓練 和歌山", "outcome": "not_reported", "outcome_justification": "Item describes a preparedness drill only; no real warning outcome is reported.", "relevant": true, "review": false, "summary_en": "Kushimoto Town in Wakayama Prefecture held a disaster drill on 3 November assuming a Nankai Trough megaquake, ahead of World Tsunami Awareness Day on 5 November. The exercise is a preparedness activity focused on tsunami response. The snippet does not describe warning dissemination or monitoring details.", "summary_original": "国連が定めた「世界津波の日」の11月5日を前に、3日、和歌山県串本町で、南海トラフ巨大地震が発生したという想定の防災訓練が行われました。", "title_en": "Disaster drill in Wakayama assuming Nankai Trough megaquake ahead of World Tsunami Awareness Day", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(9177,'claude-haiku-5-5','2026-11-04T04:22:49Z',1,0.9,0,'{"actions_taken": ["Mandatory evacuations", "Rescue operations"], "agencies": [{"country": "US", "name": "National Weather Service (NWS)", "type": "NMHS"}], "confidence": 0.9, "countries": ["US"], "dissemination_channels": [], "event_date": "2026-11-03", "event_location": "Arizona, Colorado and New Mexico, USA", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Efecto cambio climático: fuertes lluvias y ríos desbordados en Estados Unidos", "outcome": "not_reported", "outcome_justification": "The snippet reports warnings, evacuations and rescue operations but does not state whether warnings led to lives saved or shortcomings.", "relevant": true, "review": false, "summary_en": "Intense rains in the southwestern United States caused flash floods, mandatory evacuations and rescue operations in Arizona, Colorado and New Mexico. The US National Weather Service warned that rainfall could accumulate up to 100 millimetres.", "summary_original": "Las intensas lluvias que afectan al suroeste de Estados Unidos provocaron inundaciones repentinas, evacuaciones obligatorias y operativos de rescate en Arizona, Colorado y Nuevo México. El Servicio Meteorológico Nacional (NWS) advirtió que las precipitaciones podrían acumular hasta 100 milímetros.", "title_en": "Climate change effect: heavy rains and overflowing rivers in the United States", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(9178,'claude-haiku-5-5','2026-11-04T04:22:11Z',1,0.97,0,'{"actions_taken": ["Issued red alert via aviso N.° 306-2026 for activation of ravines in Piura and Tumbes"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "Dirección Zonal 1 of Senamhi", "type": "NMHS"}], "confidence": 0.97, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-11-03", "event_location": "Piura and Tumbes, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "precipitation expected between 4 and 5 November; 24-hour warning", "lead_time_hours": null, "original_title": "Senamhi declara alerta roja por activación de quebradas en Piura y Tumbes: riesgo alcanza a 104 mil personas -", "outcome": "not_reported", "outcome_justification": "The snippet reports the warning and forecast only; no outcomes are described.", "relevant": true, "review": false, "summary_en": "Peru''s national meteorological service Senamhi declared a red alert for ravine activation in the regions of Piura and Tumbes via warning No. 306-2026, valid for 24 hours. Its Zonal Directorate 1 forecasts the most intense rainfall between 4 and 5 November. The risk is reported to reach about 104,000 people.", "summary_original": "El Senamhi declaró alerta roja por activación de quebradas en Piura y Tumbes mediante el aviso N.° 306-2026, de 24 horas. La Dirección Zonal 1 prevé que las precipitaciones más intensas ocurran entre el 4 y el 5 de noviembre.", "title_en": "Senamhi declares red alert for activation of ravines in Piura and Tumbes: risk reaches 104,000 people", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9179,'claude-haiku-5-5','2026-11-04T04:21:56Z',1,0.95,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.95, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-11-02", "event_location": "Piura and Tumbes, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta roja por intensas lluvias y deslizamientos en Piura…", "outcome": "not_reported", "outcome_justification": "The item reports only that Senamhi activated a red alert (aviso N° 306-2026) valid for 24 hours from 2 November 2026 at 13:00 for possible activation of ravines in Piura and Tumbes; no outcomes are described.", "relevant": true, "review": false, "summary_en": "Peru''s National Meteorological and Hydrological Service (Senamhi) activated a red alert in Piura and Tumbes for the probable activation of ravines (quebradas) linked to intense rainfall and landslide risk. The warning, numbered 306-2026, took effect on Monday 2 November at 13:00 and lasts 24 hours. The item does not describe dissemination channels or subsequent actions.", "summary_original": "El Senamhi activó una alerta roja en Piura y Tumbes por la probabilidad de activación de quebradas, identificada como aviso N° 306-2026. El aviso entró en vigor el lunes 2 de noviembre a las 13:00 horas con duración de 24 horas.", "title_en": "Red alert for intense rains and landslides in Piura and Tumbes", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9180,'claude-haiku-5-5','2026-11-04T04:22:14Z',1,0.85,0,'{"actions_taken": ["Mandatory evacuation orders issued for low-lying areas near several rivers"], "agencies": [], "confidence": 0.85, "countries": ["US"], "dissemination_channels": [], "event_date": "2026-11-02", "event_location": "Pagosa Springs, Colorado, USA", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Una casa fue arrastrada por las inundaciones en Colorado y chocó contra un puente: el video del momento - Infobae", "outcome": "not_reported", "outcome_justification": "The snippet mentions mandatory evacuation orders remaining in effect but does not state whether they were followed or what their effect was.", "relevant": true, "review": false, "summary_en": "Floodwaters from the San Juan River swept a house into a bridge in Pagosa Springs, Colorado, on 2 November. Mandatory evacuation orders covering low-lying areas near several rivers were issued and remained in effect, according to The Denver Post. The snippet does not describe the monitoring, forecasts or dissemination channels used.", "summary_original": "Las inundaciones en Pagosa Springs, Colorado, arrastraron una vivienda por la crecida del río San Juan el lunes 2 de noviembre. Las órdenes obligatorias de evacuación abarcaron zonas bajas cercanas a varios ríos y continuaban vigentes.", "title_en": "A house was swept away by floods in Colorado and crashed into a bridge: the video of the moment", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(9181,'claude-haiku-5-5','2026-11-04T04:22:59Z',1,0.6,0,'{"actions_taken": ["Launched a dedicated section on its website for weather forecasts for the papal visit activities"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.6, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Peru", "event_name": null, "ew4all_pillars": [3], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Visita del papa León XIV: SENAMHI presenta herramienta digital para consultar el pronóstico del tiempo", "outcome": "not_reported", "outcome_justification": "The snippet describes a forecast information tool for event planning; no hazard warning outcome is reported.", "relevant": true, "review": false, "summary_en": "Peru''s national meteorological and hydrological service, SENAMHI, launched a special digital section on its website so citizens can consult weather forecasts for activities during Pope Leo XIV''s apostolic visit to Peru. The item concerns forecast dissemination for a mass event rather than a hazard warning.", "summary_original": "El SENAMHI puso a disposición de la ciudadanía una sección especial en su web para consultar el pronóstico del tiempo durante la visita apostólica del papa León XIV al Perú.", "title_en": "Visit of Pope Leo XIV: SENAMHI presents digital tool to check weather forecast", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9183,'claude-haiku-5-5','2026-11-04T04:23:02Z',1,0.8,0,'{"actions_taken": ["Installation of automatic meteorological station Punta Ático", "Installation of automatic meteorological station Caravelí"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": [], "event_date": null, "event_location": "Arequipa, Peru", "event_name": null, "ew4all_pillars": [2], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "SENAMHI fortalece el monitoreo meteorológico en Arequipa con la instalación de nuevas estaciones automáticas en Ático y Caravelí", "outcome": "not_reported", "outcome_justification": "The item reports new monitoring infrastructure being installed but no hazard event outcomes are described.", "relevant": true, "review": false, "summary_en": "SENAMHI completed installation of the Punta Ático automatic meteorological station and installed the Caravelí station in Arequipa, Peru, strengthening local meteorological monitoring capacity. The item concerns detection and monitoring infrastructure rather than a specific hazard event.", "summary_original": "El SENAMHI culminó la instalación de la estación meteorológica automática Punta Ático y realizó la instalación de la EMA Caravelí en Arequipa, fortaleciendo el monitoreo meteorológico en la región.", "title_en": "SENAMHI strengthens meteorological monitoring in Arequipa with the installation of new automatic stations in Ático and Caravelí", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9186,'claude-haiku-5-5','2026-11-04T04:23:05Z',1,0.6,0,'{"actions_taken": ["Ongoing emergency response actions for affected and displaced population by competent institutions"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "COEN", "type": "other_national_agency"}], "confidence": 0.6, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": null, "event_location": "Tumbes, Peru", "event_name": null, "ew4all_pillars": [4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Instituciones competentes continúan atendiendo a población afectada y damnificada ante lluvias intensas en Tumbes", "outcome": "not_reported", "outcome_justification": "The snippet describes ongoing response to an emergency from heavy rains but does not report whether warnings preceded it or how they performed.", "relevant": true, "review": false, "summary_en": "INDECI, through the COEN, reports that competent institutions continue response actions for the emergency caused by intense rains in Tumbes, Peru, including assistance to affected and displaced people. The snippet focuses on post-event response rather than on forecasts or warnings issued beforehand.", "summary_original": "INDECI, a través del COEN, informa que las instituciones competentes continúan ejecutando acciones de respuesta para atender la emergencia por lluvias intensas en Tumbes, incluyendo la atención a la población afectada y damnificada.", "title_en": "Competent institutions continue assisting population affected and displaced by heavy rains in Tumbes", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9187,'copied','2026-11-04T04:23:12Z',1,0.85,0,'{"actions_taken": ["INDECI recommends adopting preparedness measures in response to SENAMHI Aviso N.° 433"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Selva (jungle region), Peru", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heatwave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "from Saturday 24 to Monday 26 October", "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante el incremento de la temperatura diurna en la selva", "outcome": "not_reported", "outcome_justification": "The snippet reports a warning and recommended preparedness measures but no outcomes are given.", "relevant": true, "review": false, "summary_en": "INDECI recommends preparedness measures following SENAMHI Aviso N.° 433, which warns of moderate to extreme increases in daytime temperature in the jungle region from 24 to 26 October. The item relays a SENAMHI warning and the civil protection response to it. No outcomes are reported.", "summary_original": "El INDECI recomienda adoptar medidas de preparación ante el Aviso N.° 433 del SENAMHI, que informa sobre el incremento de la temperatura diurna, de moderada a extrema intensidad en la selva, desde el sábado 24 hasta el lunes 26 de octubre.", "title_en": "INDECI recommends preparedness measures ahead of rising daytime temperatures in the jungle", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9188,'claude-haiku-5-5','2026-11-04T04:23:09Z',0,0.8,0,'{"actions_taken": ["Extinguishing of forest fires reported by INDECI/COEN"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "COEN", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": [], "event_date": null, "event_location": "Santa Lucía, Puno, Peru", "event_name": null, "ew4all_pillars": [], "hazard": "wildfire", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Extinguen incendios forestales en distritos de Puno, Cusco y Apurímac", "outcome": "not_reported", "outcome_justification": "The snippet reports fire suppression only; no warnings, forecasts or early warning communication are mentioned.", "relevant": false, "review": false, "summary_en": "INDECI, through the COEN, reports that four forest fires in districts of Puno, Cusco and Apurímac have been extinguished. The snippet contains no information about monitoring, forecasts, warnings or dissemination, so it is not relevant to early warning service provision.", "summary_original": "INDECI, a través del COEN, informa que cuatro incendios forestales en distritos de Puno, Cusco y Apurímac fueron extinguidos. El extracto no menciona alertas, pronósticos ni difusión de avisos.", "title_en": "Forest fires extinguished in districts of Puno, Cusco and Apurímac", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9189,'claude-haiku-5-5','2026-11-04T04:23:12Z',1,0.8,0,'{"actions_taken": ["Presented a flood risk scenario study for Metropolitan Lima and Callao in the context of the El Niño phenomenon"], "agencies": [{"country": "PE", "name": "CENEPRED", "type": "other_national_agency"}, {"country": "PE", "name": "Ministry of Defence (Sector Defensa), Peru", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Lima Metropolitana and Callao, Peru", "event_name": "El Niño", "ew4all_pillars": [1, 2], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "CCENEPRED presenta el escenario de riesgo por inundaciones ante el Fenómeno El Niño en Lima Metropolitana y Callao", "outcome": "not_reported", "outcome_justification": "The item only announces the presentation of a risk scenario study; no outcomes of warnings are reported.", "relevant": true, "review": false, "summary_en": "Peru''s National Centre for Estimation, Prevention and Reduction of Disaster Risk (CENEPRED) presented a flood risk scenario study for Metropolitan Lima and the Constitutional Province of Callao in the framework of the forecast El Niño phenomenon. The study supports risk knowledge and preparedness ahead of possible flooding. The item does not report warnings issued or their outcomes.", "summary_original": "CENEPRED, del sector Defensa, presentó el Estudio de Escenario de Riesgo por Inundaciones en Lima Metropolitana y la Provincia Constitucional del Callao en el marco del Fenómeno El Niño.", "title_en": "CENEPRED presents flood risk scenario for El Niño phenomenon in Metropolitan Lima and Callao", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9353,'claude-haiku-5-5','2026-11-04T04:22:08Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": "AR", "name": "Servicio Meteorológico Nacional", "type": "NMHS"}, {"country": "AR", "name": "Clarín", "type": "media"}], "confidence": 0.8, "countries": ["AR"], "dissemination_channels": ["website"], "event_date": "2026-11-03", "event_location": "Córdoba, San Luis, La Pampa, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Súper Niño 2026 en Argentina, EN VIVO: cuándo llegan al AMBA tormentas y las provincias con alerta naranja este martes", "outcome": "not_reported", "outcome_justification": "The snippet reports SMN anticipated strong to very strong storms and orange alerts but gives no outcome information.", "relevant": true, "review": false, "summary_en": "Argentina''s National Meteorological Service (SMN) anticipated that the El Niño phenomenon would bring strong to very strong storms to the centre-east of the country, with strong storms expected in Córdoba, San Luis, La Pampa and Santa Fe. A live news feed reports on the timing of storms reaching the Buenos Aires metropolitan area and provinces under orange alert.", "summary_original": "El Servicio Meteorológico Nacional anticipó que el fenómeno tendrá en el centro-este argentino una intensidad \"fuerte o muy fuerte\". Se esperan tormentas fuertes en Córdoba, San Luis, La Pampa y Santa Fe.", "title_en": "Super El Niño 2026 in Argentina, LIVE: when storms reach Buenos Aires metro area and the provinces under orange alert this Tuesday", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9382,'claude-haiku-5-5','2026-11-04T04:22:16Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "La República", "type": "media"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-03", "event_location": "Máncora, Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Intensas lluvias golpean Máncora y dejan calles anegadas: advierten riesgo de activación de quebradas principalmente en Piura", "outcome": "not_reported", "outcome_justification": "The snippet reports flooding and a Senamhi red alert for possible increased river flows in five regions, but does not describe the outcome of the warning or actions taken.", "relevant": true, "review": false, "summary_en": "Heavy rains flooded streets in Máncora and Chulucanas and activated ravines in some sectors. Senamhi issued a red alert for possible increases in river flows across five regions, with more than 1.2 million people exposed.", "summary_original": "Las lluvias inundaron vías de Máncora, afectaron zonas comerciales de Chulucanas y activaron quebradas en algunos sectores, mientras el Senamhi emitió una alerta roja por posible incremento de caudales en cinco regiones, con más de 1,2 millones de personas expuestas.", "title_en": "Intense rains hit Máncora and leave flooded streets: warning of risk of activation of ravines mainly in Piura", "wmo_regions": ["III"]}');
