INSERT INTO "classifications" VALUES(9554,'claude-haiku-5-5','2026-11-05T04:17:33Z',1,0.9,0,'{"actions_taken": ["JMA issued a Level 4 landslide danger warning (土砂災害危険警報) for Mikurajima village", "JMA indicated that municipalities would issue evacuation information"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Mikurajima village government", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-11-05", "event_location": "Mikurajima, Tokyo, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "landslide", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "東京 御蔵島村に「レベル4土砂災害危険警報」", "outcome": "not_reported", "outcome_justification": "The snippet reports the warning issuance and that evacuation information would follow from local governments, but gives no information on actual evacuations or results.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency issued a Level 4 landslide danger warning for Mikurajima village in the Izu Islands, Tokyo, at 4:33 a.m. on the 5th, indicating very high landslide risk requiring strict vigilance. JMA stated that municipalities would issue evacuation information based on the warning. The snippet does not report dissemination details or outcomes.", "summary_original": "気象庁は5日午前4時33分、東京・伊豆諸島の御蔵島村にレベル4土砂災害危険警報を発表しました。土砂災害の危険性が非常に高くなっているため、厳重な警戒が必要です。気象庁は、自治体からの避難の情報を基に…", "title_en": "Tokyo: \"Level 4 landslide danger warning\" issued for Mikurajima village", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(9618,'claude-haiku-5-5','2026-11-05T04:18:46Z',0,0.85,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Disaster Prevention Agency (防災庁)", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": [], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "細野担当相 、 15年前の災害対応を回想 「 この時 、 日本有事が起これば …」 防災庁発足会見で", "outcome": "not_reported", "outcome_justification": "The snippet is a policy statement about disaster preparedness and institutional launch; it does not describe monitoring, forecasts, warnings or their outcomes for a specific event.", "relevant": false, "review": false, "summary_en": "Japan''s Disaster Prevention Minister Hosono, at the launch press conference of the new Disaster Prevention Agency, warned that large-scale disasters such as a Nankai Trough megaquake would be a test of the nation''s survival. He drew on lessons from the 2011 Great East Japan Earthquake regarding how disasters can weaken institutions. The item is general policy commentary rather than a report on early warning services.", "summary_original": "細野豪志防災相は防災庁発足の記者会見で、南海トラフ巨大地震などの大規模災害への対応を誤れば国家の没落は避けられないと危機感を示し、東日本大震災の経験を踏まえて災害時の国家の脆弱性を語った。", "title_en": "Minister Hosono recalls disaster response 15 years ago: \"At this time, if a national emergency occurred in Japan...\" at press conference on launch of Disaster Prevention Agency", "wmo_regions": ["II", "V"]}');
INSERT INTO "classifications" VALUES(9620,'claude-haiku-5-5','2026-11-05T04:17:42Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "Infobae", "type": "media"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-04", "event_location": "Tumbes, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "days (warnings covering 4 to 6 November, issued around 3 November)", "lead_time_hours": null, "original_title": "Alerta roja del Senamhi por precipitaciones en la costa norte desde este miércoles 4 hasta el viernes 6 de noviembre - Infobae", "outcome": "not_reported", "outcome_justification": "The item reports warnings issued by Senamhi but no outcomes, impacts or actions are described.", "relevant": true, "review": false, "summary_en": "Senamhi issued a red alert for 4 and 5 November and an orange alert for 6 November for rainfall on Peru''s north coast, mainly in Tumbes. The rain is expected to bring electrical discharges and wind gusts near 40 km/h.", "summary_original": "El Senamhi estableció alerta roja para el 4 y 5 de noviembre y alerta naranja para el 6 por lluvias en la costa norte de Perú, principalmente en Tumbes. Las lluvias irán acompañadas de descargas eléctricas y ráfagas de viento cercanas a 40 km/h.", "title_en": "Senamhi red alert for rainfall on Peru''s north coast from Wednesday 4 to Friday 6 November", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9621,'claude-haiku-5-5','2026-11-05T04:17:20Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-04", "event_location": "Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta roja por lluvias intensas en Piura", "outcome": "not_reported", "outcome_justification": "The article reports a red-level warning issued by Senamhi for heavy rain in northern Peru but gives no information on outcomes or actions taken.", "relevant": true, "review": false, "summary_en": "Peru''s national meteorological service, Senamhi, declared a red-level alert for intense rainfall in the north of the country through 2 November, forecasting moderate to extreme precipitation. The warning highlights risks of pluvial flooding, electrical discharges and strong winds in Piura.", "summary_original": "Senamhi declaró nivel rojo por lluvias intensas hasta el 2 de noviembre en el norte del país, con pronóstico de precipitaciones de moderada a extrema intensidad y riesgo de inundaciones pluviales, descargas eléctricas y vientos fuertes.", "title_en": "Red alert for intense rain in Piura", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9622,'claude-haiku-5-5','2026-11-05T04:17:54Z',1,0.85,0,'{"actions_taken": ["Mandatory evacuation ordered for residents near Oak Creek in Sedona", "Full evacuation ordered for Gisela in Gila County"], "agencies": [{"country": "US", "name": "Gila County", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["US"], "dissemination_channels": [], "event_date": "2026-11-01", "event_location": "Sedona, Arizona, United States", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Las lluvias torrenciales provocan evacuaciones e inundaciones repentinas en Arizona, Colorado y Nuevo México - Infobae", "outcome": "not_reported", "outcome_justification": "The snippet reports mandatory evacuations but does not state whether warnings were timely or whether evacuations were effective.", "relevant": true, "review": false, "summary_en": "Torrential rains caused sudden flash floods and mandatory evacuations on 1 November in Arizona, Colorado and New Mexico. Residents near Oak Creek in Sedona were ordered to evacuate, and Gila County ordered a full evacuation of Gisela. The item reports evacuation orders but no details on the forecasts or warning dissemination.", "summary_original": "Lluvias torrenciales provocaron inundaciones repentinas y evacuaciones obligatorias el 1 de noviembre en Arizona, Colorado y Nuevo México. En Sedona se ordenó evacuar a residentes cerca de Oak Creek, y el condado de Gila decretó la evacuación total de Gisela.", "title_en": "Torrential rains trigger evacuations and flash floods in Arizona, Colorado and New Mexico - Infobae", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(9628,'claude-haiku-5-5','2026-11-05T04:18:58Z',1,0.6,0,'{"actions_taken": ["Launched a special section on its website providing weather forecasts for activities linked to Pope Leo XIV''s apostolic visit to Peru"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.6, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Peru", "event_name": null, "ew4all_pillars": [3], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Visita del papa León XIV: SENAMHI habilita plataforma digital para consultar el pronóstico del tiempo", "outcome": "not_reported", "outcome_justification": "The snippet describes forecast provision for public planning but reports no outcome of hazardous weather warnings.", "relevant": true, "review": false, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, has launched a dedicated digital section on its website so citizens can consult weather forecasts for events linked to Pope Leo XIV''s apostolic visit. The item concerns public access to forecast information rather than a hazardous event or warning, so its relevance to early warning is marginal.", "summary_original": "SENAMHI habilitó una sección especial en su web para que la ciudadanía consulte el pronóstico del tiempo durante las actividades de la visita apostólica del papa León XIV al Perú.", "title_en": "Pope Leo XIV''s visit: SENAMHI launches digital platform to check weather forecasts", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9629,'claude-haiku-5-5','2026-11-05T04:18:22Z',1,0.8,0,'{"actions_taken": ["Participation in earthquake-followed-by-tsunami drill (simulacro), in line with Resolution 001-2025-PCM/SGRD, marking World Tsunami Awareness Day"], "agencies": [{"country": "PE", "name": "INDECI (Instituto Nacional de Defensa Civil)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": [], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [4], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "INDECI participó en Simulacro por Sismo seguido de Tsunami", "outcome": "not_reported", "outcome_justification": "The snippet describes a preparedness drill only; no real warning outcome is reported.", "relevant": true, "review": false, "summary_en": "Peru''s National Civil Defence Institute (INDECI) took part in a national earthquake-followed-by-tsunami drill under PCM/SGRD Resolution 001-2025, held in the framing of World Tsunami Awareness Day. The item concerns tsunami preparedness and response exercises rather than an actual event or warning issuance.", "summary_original": "INDECI participó en el Simulacro por Sismo seguido de Tsunami, en cumplimiento de la Resolución de Secretaría de Gestión del Riesgo de Desastres N.° 001-2025-PCM/SGRD, en el marco del Día Mundial de la Concienciación sobre los Tsunamis.", "title_en": "INDECI participated in Earthquake-followed-by-Tsunami Drill", "wmo_regions": ["III"]}');
