INSERT INTO "classifications" VALUES(9781,'claude-haiku-5-5','2026-11-05T04:17:51Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "AR", "name": "Servicio Meteorológico Nacional", "type": "NMHS"}], "confidence": 0.85, "countries": ["AR"], "dissemination_channels": ["website"], "event_date": "2026-11-04", "event_location": "Misiones, Formosa and Salta, Argentina", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Súper Niño 2026 en Argentina, EN VIVO: dónde habrá tormentas fuertes y qué provincias están en alerta este 4 de noviembre", "outcome": "not_reported", "outcome_justification": "The snippet reports an active orange alert in Misiones with rain damage to homes, but does not state whether the warnings led to specific protective actions or how well they performed.", "relevant": true, "review": false, "summary_en": "Argentina''s National Meteorological Service (SMN) maintains an orange alert for Misiones, where rains have already caused damage to homes, and a yellow storm alert for Formosa and central-eastern Salta. The live coverage tracks where strong storms are expected and which provinces are under warning.", "summary_original": "El Servicio Meteorológico Nacional mantiene una alerta naranja para Misiones, donde las lluvias ya causaron daños en viviendas, y rige una alerta amarilla por tormentas para Formosa y el centro-este de Salta.", "title_en": "El Niño 2026 in Argentina, LIVE: where strong storms will occur and which provinces are on alert this November 4", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9788,'claude-haiku-5-5','2026-11-05T04:17:58Z',1,0.85,0,'{"actions_taken": ["Senamhi recommends protecting property and staying informed about rainfall and flooding"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-11-04", "event_location": "Piura, Tumbes and Cajamarca, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Tormentas eléctricas y 60 mm de agua: la severa advertencia del Senamhi que pone en riesgo a Piura, Tumbes y Cajamarca", "outcome": "not_reported", "outcome_justification": "The item reports a forecast and advisory of heavy rain and thunderstorms; no outcomes are described yet.", "relevant": true, "review": false, "summary_en": "Peru''s national meteorological service Senamhi forecasts thunderstorms and up to 60 mm of rain, with strong rainfall expected in 21 provinces of seven coastal regions, including Piura, Tumbes and Cajamarca. Senamhi advises residents to protect property and stay informed about rainfall and flood risks.", "summary_original": "Se pronostican tormentas eléctricas y hasta 60 mm de agua en Piura, Tumbes y Cajamarca; lluvias fuertes en 21 provincias de siete regiones costeras. El Senamhi recomienda proteger bienes y mantenerse informado.", "title_en": "Thunderstorms and 60 mm of water: the severe Senamhi warning that puts Piura, Tumbes and Cajamarca at risk", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9802,'claude-haiku-5-5','2026-11-05T04:17:46Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": "2026-11-04", "event_location": "Coastal Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heatwave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Senamhi emite alerta roja por calor extremo en la costa: temperaturas de 38 °C y radiación UV elevada hasta el 8 de noviembre", "outcome": "not_reported", "outcome_justification": "The item reports a red alert and forecasts but does not describe outcomes or impacts of the warning.", "relevant": true, "review": false, "summary_en": "Senamhi, Peru''s national meteorological service, issued a red alert for extreme heat on the coast, with forecast temperatures of 24–38 °C and high UV radiation until 8 November. Forecast gusts of up to 45 km/h are also expected in the afternoon. The item concerns the warning and forecast only, with no reported outcomes.", "summary_original": "Senamhi emitió alerta roja por calor extremo en la costa, con temperaturas previstas de 24–38 °C y radiación UV elevada hasta el 8 de noviembre. Se esperan también ráfagas de viento de hasta 45 km/h por la tarde.", "title_en": "Senamhi issues red alert for extreme heat on the coast: temperatures of 38 °C and high UV radiation until 8 November", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(9810,'claude-haiku-5-5','2026-11-05T04:17:40Z',1,0.85,0,'{"actions_taken": ["Nationwide tsunami alert drill conducted to evaluate response to a possible tsunami on the Peruvian coast"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SISMATE", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": ["cell_broadcast"], "event_date": "2026-11-04", "event_location": "Callao, Peru", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "tsunami", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Alerta de tsunami del Sismate sonó hoy en Perú: ¿por qué se activó y qué debes saber del simulacro de Indeci?", "outcome": "not_reported", "outcome_justification": "The item describes a planned drill exercise; no real event outcome is reported.", "relevant": true, "review": false, "summary_en": "A SISMATE tsunami alert was sounded in Peru as part of an INDECI national drill simulating an 8.8 Mw earthquake about 60 km from Callao. The exercise aimed to evaluate the response to a possible tsunami on the Peruvian coast. The item concerns a simulation rather than a real hazard event.", "summary_original": "Un simulacro de INDECI contempló un terremoto de magnitud 8.8 Mw con epicentro a 60 km del Callao para evaluar la respuesta ante un posible tsunami en la costa peruana.", "title_en": "Tsunami alert from SISMATE sounded today in Peru: why it was activated and what you should know about the INDECI drill", "wmo_regions": ["III"]}');
