INSERT INTO "classifications" VALUES(10074,'claude-haiku-5-5','2026-11-06T04:14:49Z',0,0.9,0,'{"actions_taken": ["Temporary evacuation order issued", "Self-Defense Forces recovered the unexploded bomb", "Evacuation order lifted after about six hours"], "agencies": [], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-11-02", "event_location": "Tosa, Kochi Prefecture, Japan", "event_name": null, "ew4all_pillars": [], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "高知 土佐市で不発弾見つかり自衛隊が回収 一時避難指示も", "outcome": "not_reported", "outcome_justification": "The item concerns an unexploded ordnance incident, a non-natural hazard, with no meteorological or natural hazard warning content.", "relevant": false, "review": false, "summary_en": "An unexploded bomb was found at a seaside plaza in Tosa, Kochi Prefecture, on 2 November, prompting a temporary evacuation order. The Self-Defense Forces recovered the device and the order was lifted about six hours later. This is a non-natural hazard and is not relevant to early warning of natural hazards.", "summary_original": "2日午後、高知県土佐市の海沿いの広場で不発弾が見つかり、周辺に一時避難指示が出されました。自衛隊が回収し安全が確保されたとして、約6時間後に解除されたと報じられています。", "title_en": "Unexploded bomb found in Tosa, Kochi; SDF recovers it and temporary evacuation order issued", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(10075,'claude-haiku-5-5','2026-11-06T04:15:12Z',0,0.3,1,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Cabinet Office of Japan (内閣府)", "type": "other_national_agency"}], "confidence": 0.3, "countries": ["JP"], "dissemination_channels": [], "event_date": null, "event_location": "Kumamoto, Japan", "event_name": "2026 Kumamoto Earthquake", "ew4all_pillars": [], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "11月5日公表 令和８年熊本地震に係る現地視察に関する報告", "outcome": "not_reported", "outcome_justification": "Title only indicates a government report on an on-site inspection after the earthquake; no information on warnings, forecasts or outcomes is available.", "relevant": false, "review": true, "summary_en": "A Cabinet Office press release reports on an on-site inspection of the 2026 Kumamoto Earthquake. The title alone gives no information about early warning monitoring, warnings, or their dissemination, so relevance is uncertain.", "summary_original": "内閣府が令和８年熊本地震の現地視察について公表した報告。タイトルのみのため、早期警戒に関する内容は確認できない。", "title_en": "Report on On-Site Inspection Related to the 2026 Kumamoto Earthquake (released November 5)", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(10077,'claude-haiku-5-5','2026-11-06T04:14:56Z',1,0.7,0,'{"actions_taken": ["Residents calling for materials to reinforce flood defences"], "agencies": [{"country": "AR", "name": "Vecinal de Alto Verde (neighbourhood association)", "type": "other"}, {"country": "AR", "name": "UNO Santa Fe", "type": "media"}], "confidence": 0.7, "countries": ["AR"], "dissemination_channels": ["other"], "event_date": "2026-11-06", "event_location": "Alto Verde, Santa Fe, Argentina", "event_name": null, "ew4all_pillars": [3], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "in the coming days", "lead_time_hours": null, "original_title": "Crecida del Paraná: advierten que el acceso a La Boca podría cortarse en los próximos días y más de 1.500 personas podrían quedar aisladas", "outcome": "not_reported", "outcome_justification": "The item reports a community warning about imminent road cut-off and isolation, but no official warning outcome is described.", "relevant": true, "review": false, "summary_en": "Residents of Alto Verde, along the Paraná river, are on alert as floodwaters approach the access road to La Boca. The neighbourhood association president warned that the road could be cut off in the coming days, isolating more than 1,500 people, two schools and a health centre, and requested materials to reinforce defences.", "summary_original": "El avance del río mantiene en alerta a los vecinos de Alto Verde. El presidente de la vecinal advirtió que el agua está cada vez más cerca del camino y reclamó materiales para reforzar las defensas, ya que su interrupción dejaría aislados a más de 1.500 personas, dos escuelas y un centro de salud.", "title_en": "Paraná river flood: warning that access to La Boca could be cut in the coming days and more than 1,500 people could be isolated", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(10079,'claude-haiku-5-5','2026-11-06T04:14:32Z',1,0.6,0,'{"actions_taken": ["Evacuation of residents from flooded areas in northern Corrientes Province"], "agencies": [], "confidence": 0.6, "countries": ["AR"], "dissemination_channels": [], "event_date": "2026-11-05", "event_location": "Corrientes Province, Argentina", "event_name": null, "ew4all_pillars": [4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": 1967, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "El Paraná se estaciona y Corrientes tiene 1.967 evacuados por la crecida", "outcome": "not_reported", "outcome_justification": "The snippet reports river levels stabilising and an increase in evacuees, but gives no information on how warnings were issued or whether they were effective.", "relevant": true, "review": false, "summary_en": "The Paraná River dropped slightly in northern Corrientes Province, but the number of people who had to leave their homes rose to 1,967. The item reports the flood-related evacuation as a response to rising waters, though it does not describe the forecasts or warnings that preceded it.", "summary_original": "Aunque el río Paraná descendió algunos centímetros en el norte de la provincia, la cantidad de personas que debieron abandonar sus hogares aumentó.", "title_en": "The Paraná stabilises and Corrientes has 1,967 evacuees from the flood", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(10082,'claude-haiku-5-5','2026-11-06T04:14:03Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "CO", "name": "Ideam", "type": "NMHS"}], "confidence": 0.9, "countries": ["CO"], "dissemination_channels": ["website"], "event_date": "2026-11-03", "event_location": "Colombia", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Ideam prevé lluvias y mantiene alertas por crecientes súbitas y deslizamientos en Colombia hoy 3 de noviembre: consulte el pronóstico del clima - Infobae", "outcome": "not_reported", "outcome_justification": "The snippet reports ongoing alert status and forecasts but no outcomes of the warnings.", "relevant": true, "review": false, "summary_en": "Ideam reports that 196 hydrographic subzones and 429 municipalities remain under some level of alert for flash floods, floods or mass movements, including one subzone under red alert in the Magdalena-Cauca area. The item covers ongoing rain forecasts and alert maintenance by Colombia''s national meteorological service.", "summary_original": "El Ideam informó que 196 subzonas hidrográficas y 429 municipios permanecen bajo algún nivel de alerta por crecientes súbitas, inundaciones o movimientos en masa, con una subzona en alerta roja en el área Magdalena-Cauca.", "title_en": "Ideam forecasts rain and maintains alerts for flash floods and landslides in Colombia today, 3 November: check the weather forecast", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(10083,'claude-haiku-5-5','2026-11-06T04:13:57Z',1,0.95,0,'{"actions_taken": ["Issued red alert meteorological warning N.° 451 for heavy to extreme precipitation in 13 departments of the northern coast"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.95, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-06", "event_location": "Tumbes, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Lluvias extremas y decenas de litros de agua por metro cuadrado: Piura y Tumbes en emergencia y Lima superó una marca histórica apuesplan", "outcome": "not_reported", "outcome_justification": "The snippet reports the red alert issuance but gives no information on impacts or the effectiveness of the warning.", "relevant": true, "review": false, "summary_en": "Senamhi issued a red alert for heavy to extreme rainfall on Peru''s northern coast, mainly in Tumbes, through meteorological warning No. 451, valid until 6 November across 13 departments. The article also reports Piura and Tumbes in emergency and Lima exceeding a historic rainfall mark.", "summary_original": "Senamhi emitió alerta roja por precipitaciones de fuerte a extrema intensidad en la costa norte, principalmente en Tumbes, mediante el aviso meteorológico N.° 451, vigente hasta el 6 de noviembre en 13 departamentos.", "title_en": "Extreme rains with tens of liters of water per square meter: Piura and Tumbes in emergency and Lima exceeded a historic mark", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(10084,'claude-haiku-5-5','2026-11-06T04:14:00Z',1,0.93,0,'{"actions_taken": ["COEN-INDECI maintained red danger level in Piura via bulletin N.° 210-2026", "Senamhi issued warning notice N.° 456 with rainfall expected until 8 November"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "COEN-INDECI", "type": "other_national_agency"}], "confidence": 0.93, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-06", "event_location": "Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Lluvias sorprenden a Piura en plena noche: Senamhi mantiene alerta roja y advierte nuevas precipitaciones", "outcome": "not_reported", "outcome_justification": "The snippet reports warnings and alert levels issued but does not state any outcome or impacts of the rainfall.", "relevant": true, "review": false, "summary_en": "COEN-INDECI kept a red danger level in Piura, Peru, due to possible activation of gullies, according to bulletin N.° 210-2026. Senamhi issued warning notice N.° 456 forecasting further rainfall until 8 November 2026.", "summary_original": "El COEN-INDECI mantuvo un nivel rojo de peligro en Piura por posible activación de quebradas según su boletín N.° 210-2026, y el Senamhi emitió el aviso N.° 456 con lluvias hasta el 8 de noviembre.", "title_en": "Rain catches Piura at night: Senamhi keeps red alert and warns of new precipitation", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(10085,'claude-haiku-5-5','2026-11-06T04:14:15Z',1,0.85,0,'{"actions_taken": ["Town of McCaysville declared a state of emergency", "Evacuations ordered for affected residents"], "agencies": [{"country": "US", "name": "National Weather Service", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["US"], "dissemination_channels": [], "event_date": "2026-11-05", "event_location": "McCaysville, Fannin County, Georgia, USA", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "flash_flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Una ciudad de Georgia declara la emergencia por inundaciones y ordena evacuaciones - Infobae", "outcome": "not_reported", "outcome_justification": "The snippet reports flash flood warning extension and evacuations but does not state whether warnings were received in time or what the outcome was.", "relevant": true, "review": false, "summary_en": "McCaysville, Georgia declared a state of emergency after sudden floods flooded homes and displaced families. The National Weather Service extended its flash flood alert for Fannin County, and evacuations were ordered. The snippet does not detail warning dissemination or lead time.", "summary_original": "McCaysville, Georgia, declaró estado de emergencia por inundaciones repentinas que dejaron viviendas anegadas y familias desplazadas, mientras el Servicio Meteorológico Nacional extendió la alerta de inundación repentina en el condado de Fannin.", "title_en": "A Georgia city declares emergency over floods and orders evacuations", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(10086,'claude-haiku-5-5','2026-11-06T04:14:17Z',1,0.95,0,'{"actions_taken": ["Senamhi issued short-term warning notice N.º 309-2026 with extreme danger level"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "elpopular.pe", "type": "media"}], "confidence": 0.95, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": "2026-11-05", "event_location": "Tumbes, Zarumilla and Contralmirante Villar, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "valid for 24 hours from issuance", "lead_time_hours": 24, "original_title": "¡ATENCIÓN! Fuertes LLUVIAS ponen en alerta a la costa norte: Senamhi advierte posibles INUNDACIONES", "outcome": "not_reported", "outcome_justification": "The snippet reports the warning issuance only; no outcomes are described.", "relevant": true, "review": false, "summary_en": "Senamhi issued short-term warning notice No. 309-2026 with an extreme danger level for heavy rain and possible flooding in Tumbes, Zarumilla and Contralmirante Villar on Peru''s northern coast, valid for 24 hours from issuance. The warning was reported by local media as an alert to the northern coastal population.", "summary_original": "Senamhi emitió el aviso de corto plazo N.º 309-2026 con nivel de peligro extremo en Tumbes, Zarumilla y Contralmirante Villar por lluvias fuertes y posibles inundaciones, con vigencia de 24 horas desde su emisión.", "title_en": "ATTENTION! Heavy rains put northern coast on alert: Senamhi warns of possible floods", "wmo_regions": ["III"]}');
