INSERT INTO "classifications" VALUES(10552,'claude-haiku-5-5','2026-11-07T04:16:40Z',0,0.9,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Chiba Prefectural Government", "type": "other_national_agency"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": [], "event_date": null, "event_location": "Chiba Prefecture, Japan", "event_name": null, "ew4all_pillars": [], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "千葉県、499億円の補正予算案発表 豪雨・台風の復旧支援が柱", "outcome": "not_reported", "outcome_justification": "The item concerns post-event budget and recovery funding for the August heavy rain and September typhoon; it does not describe monitoring, forecasts, warnings, or their outcomes.", "relevant": false, "review": false, "summary_en": "Chiba Prefecture announced a supplementary budget of 49.9 billion yen focused on recovery from the August heavy rain and September Typhoon No. 25. It includes prefectural support for households whose homes were certified as half-destroyed and funding to restore suspended railway lines. The article does not address early warning services.", "summary_original": "千葉県は6日、8月の千葉豪雨や9月の台風25号の復旧支援を柱とした総額499億1300万円の補正予算案を発表した。国の支援対象外の住宅が「半壊」と認定された世帯への県独自支援金や、運休中の小湊鉄道・いすみ鉄道の復旧補助費用を計上する。", "title_en": "Chiba Prefecture announces 49.9 billion yen supplementary budget, centred on flood and typhoon recovery support", "wmo_regions": ["II"]}');
