INSERT INTO "classifications" VALUES(10577,'claude-haiku-5-5','2026-11-07T04:17:31Z',1,0.9,0,'{"actions_taken": ["INDECI recommends preparedness measures in response to SENAMHI meteorological warning No. 456 (red level)"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.9, "countries": ["PE"], "dissemination_channels": ["website"], "event_date": null, "event_location": "Coast and highlands, Peru", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante precipitaciones en la costa y sierra", "outcome": "not_reported", "outcome_justification": "The snippet describes issued warnings and recommended preparedness measures but reports no outcomes.", "relevant": true, "review": false, "summary_en": "INDECI recommends preparedness measures following SENAMHI meteorological warning No. 456 at red level, which reports snow, hail, sleet and rain of light to heavy intensity in the highlands. The advisory covers coastal and highland areas of Peru. The snippet does not report observed impacts.", "summary_original": "El Instituto Nacional de Defensa Civil (INDECI) recomienda medidas de preparación ante el aviso meteorológico N.° 456 (nivel rojo) del SENAMHI, que informa sobre precipitaciones (nieve, granizo, aguanieve y lluvia) de ligera a fuerte intensidad en la sierra.", "title_en": "INDECI recommends preparedness measures for precipitation in the coast and highlands", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(10739,'claude-haiku-5-5','2026-11-07T04:16:25Z',1,0.8,0,'{"actions_taken": ["Civil Defence recommends households keep an emergency backpack ready for possible floods and huaicos"], "agencies": [{"country": "PE", "name": "Defensa Civil (Civil Defence, Peru)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-06", "event_location": "Northern coast and highlands, Peru", "event_name": "El Niño (2026-2027)", "ew4all_pillars": [3, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "Warning issued for summer 2027 rains, roughly 6-7 months ahead", "lead_time_hours": null, "original_title": "Fenómeno El Niño: ¿qué debe llevar una mochila de emergencia para una eventual tragedia?", "outcome": "not_reported", "outcome_justification": "The item reports a forward-looking alert and preparedness advice; no realised outcome of warnings is described.", "relevant": true, "review": false, "summary_en": "Peru''s Civil Defence warned that rainfall on the northern coast and highlands is expected to increase for summer 2027 due to El Niño, and recommends households keep an emergency backpack ready for floods and huaicos. The item focuses on public preparedness advice in response to this early alert.", "summary_original": "Ante la alerta de que las lluvias en la costa norte y sierra se incrementarán para el verano de 2027, Defensa Civil recomienda tener a la mano la mochila de emergencia para afrontar posibles inundaciones y huaicos.", "title_en": "El Niño phenomenon: what should an emergency backpack contain for a possible disaster?", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(10750,'claude-haiku-5-5','2026-11-07T04:17:01Z',0,0.85,0,'{"actions_taken": [], "agencies": [], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-11-06", "event_location": "San Martín, Peru", "event_name": null, "ew4all_pillars": [], "hazard": "wildfire", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "San Martín en alerta: incendio forestal de gran magnitud continúa activo pese a lluvias", "outcome": "not_reported", "outcome_justification": "The snippet reports an active wildfire and rainfall reducing its intensity, but mentions no forecasts, warnings, monitoring agencies or outcomes of early warning.", "relevant": false, "review": false, "summary_en": "A large forest fire in San Martín, Peru, has been burning since Thursday in San Antonio de Cumbaza, with two further fires reported in Cacatachi and La Banda de Shilcayo. Rainfall has partially reduced the flames'' intensity. The item does not describe any warnings, forecasts or early warning actions.", "summary_original": "Un incendio forestal de gran magnitud se registra desde el jueves en San Antonio de Cumbaza, con otros dos siniestros en Cacatachi y La Banda de Shilcayo; las lluvias redujeron parcialmente su intensidad.", "title_en": "San Martín on alert: large forest fire remains active despite rains", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(10756,'claude-haiku-5-5','2026-11-07T04:16:48Z',1,0.7,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Lima Airport Partners (LAP)", "type": "other"}], "confidence": 0.7, "countries": ["PE"], "dissemination_channels": [], "event_date": "2026-11-06", "event_location": "Callao, Peru", "event_name": null, "ew4all_pillars": [1, 2], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Aeropuerto Jorge Chávez: LAP alerta riesgo de inundaciones por crecida del río Rímac", "outcome": "not_reported", "outcome_justification": "The item reports a flood risk warning issued by the airport operator; no outcome of the warning is described.", "relevant": true, "review": false, "summary_en": "The operator of Lima''s Jorge Chávez International Airport warned that a possible rise in the Rímac River flow could flood Néstor Gambetta avenue and parts of the second runway, and affect electrical and communication systems. The warning highlights risk knowledge and hazard awareness ahead of a possible river rise, though no official forecast or dissemination details are given in the snippet.", "summary_original": "El operador del Aeropuerto Jorge Chávez advirtió que una eventual crecida del río Rímac podría afectar la avenida Néstor Gambetta, sectores de la segunda pista y sistemas eléctricos y de comunicaciones.", "title_en": "Jorge Chávez Airport: LAP warns of flood risk from Rímac River rise", "wmo_regions": ["III"]}');
