INSERT INTO "classifications" VALUES(10895,'claude-haiku-5-5','2026-11-08T04:16:16Z',1,0.8,0,'{"actions_taken": ["Raised wildfire prevention measures to maximum alert status", "Began deploying forest protection personnel", "Training forest rangers"], "agencies": [{"country": "PH", "name": "Department of Environment and Natural Resources (DENR)", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PH"], "dissemination_channels": ["other"], "event_date": "2026-11-07", "event_location": "Philippines", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "wildfire", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "en", "lead_time": null, "lead_time_hours": null, "original_title": "DENR on maximum alert vs wildfires amid ‘very strong’ El Niño", "outcome": "not_reported", "outcome_justification": "The snippet describes alert status and preparedness deployments but reports no outcome of the warnings.", "relevant": true, "review": false, "summary_en": "The Philippine DENR raised its wildfire prevention measures to maximum alert amid extreme heat and dry conditions linked to a ''very strong'' El Niño. The agency announced deployment of forest protection personnel and training of forest rangers in response to the threat.", "summary_original": null, "title_en": "DENR on maximum alert vs wildfires amid ''very strong'' El Niño", "wmo_regions": ["II", "V"]}');
INSERT INTO "classifications" VALUES(10900,'claude-haiku-5-5','2026-11-08T04:16:19Z',1,0.85,0,'{"actions_taken": ["Provisional operation of landslide-related warnings and advisories following the earthquake"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-11-08", "event_location": "Western Shizuoka Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "令和８年11月８日01時04分頃の静岡県西部の地震に伴う土砂災害に関する警報等の暫定的な運用について", "outcome": "not_reported", "outcome_justification": "The item is an official JMA press release announcing a provisional operation of warnings; no outcomes are reported in the title.", "relevant": true, "review": false, "summary_en": "JMA announced the provisional operation of landslide disaster warnings and related alerts following an earthquake in western Shizuoka Prefecture at about 01:04 on 8 November 2026. The release concerns how warnings for earthquake-triggered landslide risk are issued during the interim period. The snippet is empty, so specific warning levels and dissemination details cannot be confirmed.", "summary_original": "令和8年11月8日01時04分頃に発生した静岡県西部の地震に伴う土砂災害に関する警報等について、暫定的な運用を行うことを発表した気象庁の報道発表です。", "title_en": "Provisional operation of warnings related to landslide disasters following the earthquake in western Shizuoka Prefecture at around 01:04 on 8 November 2026", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(10901,'claude-haiku-5-5','2026-11-08T04:16:38Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": ["website"], "event_date": "2026-11-08", "event_location": "Western Shizuoka Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "令和８年11月８日01時04分頃の静岡県西部の地震について", "outcome": "not_reported", "outcome_justification": "The official JMA press release concerns an earthquake report and no outcomes of warnings are stated in the title or snippet.", "relevant": true, "review": false, "summary_en": "The Japan Meteorological Agency issued an official press release regarding an earthquake that occurred in western Shizuoka Prefecture at about 01:04 on 8 November 2026. The release is an earthquake information bulletin from the national meteorological service; the snippet provides no details on intensity, tsunami or warning content.", "summary_original": "気象庁が、2026年11月8日01時04分頃に静岡県西部で発生した地震について発表した報道発表。スニペットには震度や津波の情報などの詳細は記載されていない。", "title_en": "Regarding the earthquake in western Shizuoka Prefecture at about 01:04 on November 8, 2026", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(10903,'claude-haiku-5-5','2026-11-08T04:16:29Z',1,0.85,0,'{"actions_taken": ["JMA stated that, based on the earthquake''s mechanism and magnitude, the plate boundary where a Nankai Trough megaquake could occur showed no particular abnormality", "JMA advised of possible similar shaking for about one week"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-11-08", "event_location": "Western Shizuoka Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "震度5強 愛知で観測約30年ぶり 1週間ほど同程度の揺れに注意", "outcome": "not_reported", "outcome_justification": "Snippet reports JMA''s assessment and advisory but does not state any impacts or whether the advisory was acted upon.", "relevant": true, "review": false, "summary_en": "An earthquake off western Shizuoka Prefecture on the early morning of 8 November produced seismic intensity 5-upper in Aichi Prefecture and 5-lower across the Tokai region and Nagano Prefecture. JMA stated that the event showed no particular abnormality at the Nankai Trough plate boundary and warned of similar shaking for about a week.", "summary_original": "8日未明、静岡県西部を震源とする地震があり、愛知県で震度5強、東海の各地や長野県で震度5弱の揺れを観測しました。気象庁は、地震のメカニズムや規模などから、南海トラフの巨大地震が起きるプレート境界に特段の異常はないとした上で、1週間ほど同程度の揺れに注意するよう呼びかけています。", "title_en": "Seismic intensity 5-upper observed in Aichi for first time in about 30 years; similar shaking possible for about a week", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(10916,'claude-haiku-5-5','2026-11-08T04:16:21Z',1,0.8,0,'{"actions_taken": ["JMA called on the public to pay attention to future information"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": ["other"], "event_date": "2026-11-07", "event_location": "South of Japan, Pacific Ocean", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "tropical_cyclone", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "台風32号が発生 年間発生数は1994年以来の多さに", "outcome": "not_reported", "outcome_justification": "The item reports formation of the typhoon and a JMA advisory to monitor information, but gives no information on warning effectiveness or impacts.", "relevant": true, "review": false, "summary_en": "Typhoon No. 32 formed on 7 November at noon, south of Japan, making the annual typhoon count the highest since 1994. The Japan Meteorological Agency urged the public to follow future information. The report focuses on monitoring and advisory communication without outcome details.", "summary_original": "7日正午、日本のはるか南で台風32号が発生しました。年間の台風発生数としては、32年前の1994年以来の多さです。気象庁は今後の情報に注意するよう呼びかけています。", "title_en": "Typhoon No. 32 forms; annual number of typhoons highest since 1994", "wmo_regions": ["II", "V"]}');
INSERT INTO "classifications" VALUES(10917,'claude-haiku-5-5','2026-11-08T04:16:13Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": ["mobile_app", "tv", "other"], "event_date": "2026-11-08", "event_location": "Western Shizuoka Prefecture, Japan", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": 3, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "静岡県内では3人がけが 深夜の緊急地震速報に釣り人「パニックに」", "outcome": "mixed", "outcome_justification": "An earthquake early warning (緊急地震速報) was issued and received, but the snippet reports at least three injuries and anglers describing panic, with no clear statement on how effective the warning was in enabling protective action.", "relevant": true, "review": false, "summary_en": "An earthquake centred in western Shizuoka Prefecture at about 1 a.m. on 8 November produced a seismic intensity of 5-lower in several cities, injuring at least three people. An earthquake early warning (Kinkyu Jishin Sokuho) was issued, and anglers reported panic upon receiving it. The item highlights public reaction to late-night early warnings.", "summary_original": "8日午前1時過ぎに静岡県西部を震源とする地震が発生し、浜松市などで震度5弱を観測、少なくとも3人がけがをした。深夜の緊急地震速報を受け、釣り人がパニックになったと報じられている。", "title_en": "Three injured in Shizuoka Prefecture; anglers ''panicked'' by late-night earthquake early warning", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(10968,'claude-haiku-5-5','2026-11-08T04:16:35Z',0,0.8,0,'{"actions_taken": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency", "type": "NMHS"}], "confidence": 0.8, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-11-08", "event_location": "Chita, Aichi, Japan", "event_name": null, "ew4all_pillars": [], "hazard": "earthquake", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": 20, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "愛知県知多市で震度5強 M5 ・ 7 、 けが20人以上 津波の心配なし - スポニチ Sponichi Annex 社会", "outcome": "not_reported", "outcome_justification": "The snippet reports earthquake magnitude, intensity, injuries and the absence of a tsunami concern, but does not describe any warning issued, forecast, or response action.", "relevant": false, "review": false, "summary_en": "An earthquake of seismic intensity 5-upper and magnitude 5.7 struck Chita City, Aichi Prefecture, with over 20 people reportedly injured; the Japan Meteorological Agency stated there was no tsunami concern. The snippet does not describe any early warning dissemination or response actions, so the item is treated as not relevant.", "summary_original": "8日午前1時4分ごろ、愛知県知多市で震度5強を観測する地震があった。気象庁によると、震源は静岡県西部で深さは41キロ。地震の規模を示すマグニチュード（M）は…", "title_en": "Seismic intensity 5-upper in Chita City, Aichi Prefecture; M5.7, over 20 injured, no tsunami concern", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(10969,'claude-haiku-5-5','2026-11-08T04:16:43Z',0,0.9,0,'{"actions_taken": ["Group-wide comprehensive disaster drill simulating a large earthquake with 763 participants", "Confirmation of procedures including prohibition of re-entry into facilities"], "agencies": [{"country": "JP", "name": "Aeon", "type": "NGO"}], "confidence": 0.9, "countries": ["JP"], "dissemination_channels": [], "event_date": null, "event_location": null, "event_name": null, "ew4all_pillars": [], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "イオンが爆発事故後初の防災訓練 再入館禁止など手順確認 ： 中日新聞Web", "outcome": "not_reported", "outcome_justification": "The item concerns a corporate disaster drill after a non-natural explosion accident; no warnings, forecasts or hazard early warning services are described.", "relevant": false, "review": false, "summary_en": "Aeon conducted a group-wide disaster drill simulating a large earthquake, involving 763 participants from its malls and retail units, its first drill since a July explosion accident. The drill confirmed procedures such as prohibiting re-entry into facilities. The item does not involve monitoring, warnings or forecasts of a natural hazard.", "summary_original": "イオンは６日、大規模地震の発生を想定したグループ総合防災訓練を実施し、イオンモールやイオンリテールなどから７６３人が参加した。７月に発生した爆発事故後初の訓練で、再入館禁止などの手順を確認した。", "title_en": "Aeon holds first disaster drill since explosion accident, confirms procedures such as no re-entry into buildings", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(10970,'claude-haiku-5-5','2026-11-08T04:16:49Z',0,0.85,0,'{"actions_taken": ["National emergency disaster field headquarters training held at Wakayama Prefectural Office"], "agencies": [{"country": "JP", "name": "Disaster Management Agency (防災庁)", "type": "other_national_agency"}, {"country": "JP", "name": "Wakayama Prefectural Government", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["JP"], "dissemination_channels": [], "event_date": "2026-11-05", "event_location": "Wakayama, Japan", "event_name": null, "ew4all_pillars": [4], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "防災庁発足後初の訓練 、 和歌山県庁で現地対策本部 ： 紀伊民報AGARA｜和歌山県のニュースサイト", "outcome": "not_reported", "outcome_justification": "The item describes a disaster response training exercise for a hypothetical Nankai Trough earthquake, with no actual warnings, forecasts, or hazard monitoring reported.", "relevant": false, "review": false, "summary_en": "Japan''s newly established Disaster Management Agency held its first national emergency field headquarters training at the Wakayama Prefectural Office on 5-6 November, simulating a future Nankai Trough earthquake. The item concerns response-coordination drills rather than actual early warning services, so it is not relevant to early warning monitoring or dissemination.", "summary_original": "防災庁発足後、初となる国の緊急災害現地対策本部訓練が和歌山県庁で実施された。南海トラフ地震を想定した訓練で、現地対策本部の設置と運営を確認した。", "title_en": "First training by the Disaster Management Agency after its launch; emergency field headquarters set up at Wakayama Prefectural Office", "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(10971,'claude-haiku-5-5','2026-11-08T04:16:26Z',1,0.85,0,'{"actions_taken": ["Extended preventive surveillance until 7 November", "Urged identification of evacuation routes"], "agencies": [{"country": "PA", "name": "Sinaproc", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["PA"], "dissemination_channels": [], "event_date": "2026-11-07", "event_location": "Los Santos Province, Panama", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": 16, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Lluvias dejan al menos 16 afectados en Panamá y autoridades extienden advertencia por la presencia de dos sistemas de baja presión - Infobae", "outcome": "not_reported", "outcome_justification": "The article reports 16 people affected but does not state whether warnings led to avoided losses or were late or missed.", "relevant": true, "review": false, "summary_en": "Heavy rains affected at least 16 people in Panama, mainly in Los Santos. Sinaproc extended its preventive watch until 7 November due to two low-pressure systems and urged residents to identify evacuation routes.", "summary_original": "Al menos 16 personas resultaron afectadas por lluvias en Panamá, principalmente en Los Santos. El Sinaproc extendió la vigilancia preventiva hasta el 7 de noviembre y exhortó a identificar rutas de evacuación.", "title_en": "Rains leave at least 16 affected in Panama and authorities extend warning due to two low-pressure systems", "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(10972,'claude-haiku-5-5','2026-11-08T04:16:10Z',1,0.85,0,'{"actions_taken": [], "agencies": [{"country": "MX", "name": "Coordinación Nacional de Protección Civil", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["MX"], "dissemination_channels": [], "event_date": "2026-11-07", "event_location": "Mexico", "event_name": null, "ew4all_pillars": [3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Protección Civil alerta por lluvias intensas y frío en estos estados de México", "outcome": "not_reported", "outcome_justification": "The item reports a warning issued for heavy rain, flooding, landslides and river rises tied to cold front 4, but gives no information on impacts or the effectiveness of the warning.", "relevant": true, "review": false, "summary_en": "Mexico''s National Civil Protection Coordination issued an alert for heavy rain and cold across several states on 7 November, linked to cold front 4. The warning highlighted risks of flooding, landslides and river flooding. The snippet does not describe dissemination channels or outcomes.", "summary_original": "La Coordinación Nacional de Protección Civil alertó por lluvias intensas y frío en varios estados de México el 7 de noviembre por el frente frío 4, advirtiendo sobre inundaciones, deslaves y crecidas de ríos.", "title_en": "Civil Protection warns of heavy rain and cold in these Mexican states", "wmo_regions": ["IV"]}');
