INSERT INTO "classifications" VALUES(10978,'claude-haiku-5-5','2026-11-08T04:16:56Z',1,0.95,0,'{"actions_taken": ["INDECI recommends preparedness measures in response to SENAMHI Meteorological Warning No. 461 (orange level)"], "agencies": [{"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "SENAMHI", "type": "NMHS"}], "confidence": 0.95, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": null, "event_location": "Central and southern jungle, Peru", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "other", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "INDECI recomienda medidas de preparación ante el incremento de la velocidad del viento en la selva centro y sur - décimo quinto friaje", "outcome": "not_reported", "outcome_justification": "The item announces recommended preparedness measures for a warned wind event but reports no outcome.", "relevant": true, "review": false, "summary_en": "INDECI issued a press release recommending preparedness measures following SENAMHI''s orange-level Meteorological Warning No. 461, which reports increasing moderate-to-strong wind speeds in the central and southern Peruvian jungle during the fifteenth friaje of the season. The item focuses on warning communication and preparedness advice rather than observed impacts.", "summary_original": "INDECI recomienda adoptar medidas de preparación ante el Aviso Meteorológico N.° 461 (nivel naranja) del SENAMHI, que informa sobre el incremento de la velocidad del viento de moderada a fuerte en la selva centro y sur durante el décimo quinto friaje.", "title_en": "INDECI recommends preparedness measures for increased wind speed in the central and southern jungle - fifteenth friaje", "wmo_regions": ["III"]}');
