INSERT INTO "classifications" VALUES(11722,'claude-haiku-5-5','2026-11-10T04:17:24Z',1,0.85,0,'{"actions_taken": ["Warnings issued advising people to avoid approaching swollen rivers and flooded roads", "Residents urged to follow municipal evacuation orders"], "agencies": [{"country": "PT", "name": "Portuguese meteorological and civil protection authorities", "type": "other_national_agency"}, {"country": "ES", "name": "Spanish meteorological authorities", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["ES", "PT"], "dissemination_channels": [], "event_date": "2026-11-11", "event_location": null, "event_name": null, "ew4all_pillars": [2, 3], "hazard": "severe_storm", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "ja", "lead_time": null, "lead_time_hours": null, "original_title": "ポルトガルやスペインに発達したストーム 大雨や暴風に警戒｜Infoseekニュース", "outcome": "not_reported", "outcome_justification": "The article describes warnings and advice issued ahead of the storm''s peak on 11 November; no outcome has been reported.", "relevant": true, "review": false, "summary_en": "Meteorological authorities in Portugal and Spain issued warnings for a developing storm, advising people to avoid swollen rivers and flooded roads and to follow municipal evacuation orders. The storm''s peak was expected on 11 November, with wind gusts over 30 m/s and high waves forecast.", "summary_original": "ポルトガルとスペインの気象当局は、発達中のストームに対し警報を発表し、増水した河川や浸水道路への接近回避と自治体の避難指示への従いを呼びかけている。荒天のピークは11日で、30m/s超の暴風と高波が警戒されている。", "title_en": "Developing storm in Portugal and Spain: warnings for heavy rain and strong winds", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(11724,'claude-haiku-5-5','2026-11-10T04:17:35Z',1,0.93,0,'{"actions_taken": ["Urgent municipal coordination meeting convened", "Public advised to avoid unnecessary travel through flood-prone areas"], "agencies": [{"country": "ES", "name": "Ayuntamiento de Plasencia", "type": "other_national_agency"}], "confidence": 0.93, "countries": ["ES"], "dissemination_channels": ["other"], "event_date": "2026-11-10", "event_location": "Plasencia, Spain", "event_name": null, "ew4all_pillars": [3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Plasencia activa un dispositivo especial ante la alerta roja y naranja por fuertes lluvias", "outcome": "not_reported", "outcome_justification": "The item reports warnings and preparedness actions in advance of the event but gives no information on actual impacts or how the warnings performed.", "relevant": true, "review": false, "summary_en": "Plasencia city council convened an urgent coordination meeting after forecasts of heavy rain for 10 November and the activation of orange alert in Plasencia and red alert in northern Cáceres. Residents were advised to avoid unnecessary travel through flood-prone zones. The item describes a warning-driven preparedness response but reports no outcome.", "summary_original": "El Ayuntamiento de Plasencia convocó una reunión urgente de coordinación ante la previsión de fuertes lluvias para el martes 10 de noviembre y la activación de alerta naranja en Plasencia y roja en el norte de Cáceres, recomendando evitar desplazamientos por zonas inundables.", "title_en": "Plasencia activates special deployment ahead of red and orange alerts for heavy rain", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(11725,'claude-haiku-5-5','2026-11-10T04:17:39Z',1,0.9,0,'{"actions_taken": ["Declared Alerta Temprana Preventiva for Coquimbo, Metropolitana and O''Higgins", "Reinforced monitoring", "Coordination of the National Prevention and Disaster Response System"], "agencies": [{"country": "CL", "name": "SENAPRED", "type": "other_national_agency"}, {"country": "CL", "name": "Dirección Meteorológica de Chile", "type": "NMHS"}], "confidence": 0.9, "countries": ["CL"], "dissemination_channels": [], "event_date": "2026-11-10", "event_location": "Coquimbo, Metropolitana and O''Higgins regions, Chile", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "tonight (same day as publication)", "lead_time_hours": null, "original_title": "Declaran alerta preventiva por lluvias y tormentas eléctricas que llegarían esta noche - El Rancagüino", "outcome": "not_reported", "outcome_justification": "The item reports the alert declaration and expected conditions but no outcome of the event is given.", "relevant": true, "review": false, "summary_en": "SENAPRED declared a preventive early alert for Coquimbo, Metropolitana and O''Higgins regions in Chile based on Dirección Meteorológica de Chile forecasts of rain and thunderstorms linked to a cut-off low expected that night. The measure involves strengthening monitoring and coordination within the national disaster prevention and response system.", "summary_original": "SENAPRED declaró Alerta Temprana Preventiva para Coquimbo, Metropolitana y O''Higgins ante un pronóstico de precipitaciones y tormentas asociadas a una baja segregada, según avisos de la Dirección Meteorológica de Chile. La medida implica reforzar el monitoreo y la coordinación del Sistema Nacional de Prevención y Respuesta ante Desastres.", "title_en": "Preventive alert declared for rain and thunderstorms expected tonight", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(11726,'claude-haiku-5-5','2026-11-10T04:17:30Z',1,0.9,0,'{"actions_taken": [], "agencies": [{"country": "EC", "name": "INAMHI", "type": "NMHS"}, {"country": "EC", "name": "Teleamazonas", "type": "media"}], "confidence": 0.9, "countries": ["EC"], "dissemination_channels": ["other"], "event_date": "2026-11-10", "event_location": "Orellana and Sucumbíos cantons, Ecuador", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Inamhi emite pronósticos de lluvias para este martes 10 de noviembre de 2026 en el país", "outcome": "not_reported", "outcome_justification": "The item reports an official forecast with red and orange alerts for heavy rain but gives no information on impacts or the outcome of the warnings.", "relevant": true, "review": false, "summary_en": "Ecuador''s National Institute of Meteorology and Hydrology (INAMHI) issued its official rainfall forecast for Tuesday 10 November 2026, with a red alert for heavy rain in the Orellana and Sucumbíos cantons and orange alerts in several coastal areas. The item is a forecast and alert announcement; no outcomes are reported.", "summary_original": "El INAMHI emitió su pronóstico oficial de lluvias para el martes 10 de noviembre de 2026, con alerta roja por lluvias fuertes en cantones de Orellana y Sucumbíos y alerta naranja en varias zonas de la Costa.", "title_en": "INAMHI issues rainfall forecasts for Tuesday 10 November 2026 in the country", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(11727,'claude-haiku-5-5','2026-11-10T04:17:52Z',1,0.93,0,'{"actions_taken": ["Municipal parks and sports facilities closed on 10 November 2026 in response to AEMET red alert"], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}, {"country": "ES", "name": "Ayuntamiento de Moraleja", "type": "other_national_agency"}], "confidence": 0.93, "countries": ["ES"], "dissemination_channels": [], "event_date": "2026-11-10", "event_location": "Moraleja, Cáceres, Spain", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "same day (closures announced for 10 November 2026)", "lead_time_hours": null, "original_title": "Moraleja cierra sus parques e instalaciones deportivas ante la alerta roja por lluvias", "outcome": "not_reported", "outcome_justification": "The item reports the preventive closures but gives no information on actual rainfall, impacts or effectiveness of the measures.", "relevant": true, "review": false, "summary_en": "AEMET activated a red alert for rain and storms in northern Cáceres, forecasting up to 120 litres per square metre in 12 hours. The Moraleja town council responded by closing its municipal parks and sports facilities on 10 November 2026. The item does not report observed rainfall or outcomes.", "summary_original": "AEMET activó una alerta roja por lluvias y tormentas para el norte de Cáceres, con previsiones de hasta 120 litros por metro cuadrado en 12 horas, y el Ayuntamiento de Moraleja cerró sus parques e instalaciones deportivas el 10 de noviembre.", "title_en": "Moraleja closes parks and sports facilities ahead of red rain alert", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(11728,'claude-haiku-5-5','2026-11-10T04:17:47Z',1,0.85,0,'{"actions_taken": ["Suspension of school activities in affected areas to avoid travel and ensure pupil safety"], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}, {"country": "ES", "name": "Junta de Extremadura", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["ES"], "dissemination_channels": ["other"], "event_date": "2026-11-10", "event_location": "Northern Cáceres, Extremadura, Spain", "event_name": null, "ew4all_pillars": [2, 3, 4], "hazard": "heavy_rain", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "La amenaza de lluvias torrenciales obliga a ampliar la alerta roja en el norte de Cáceres", "outcome": "not_reported", "outcome_justification": "The snippet describes a red alert and school suspension but does not report outcomes of these measures.", "relevant": true, "review": false, "summary_en": "A red alert for heavy rain and storms remains in force in northern Cáceres on 10 November and has been extended to more areas. School activities in affected zones were suspended to avoid travel and protect pupils. The snippet does not report the outcome of these measures.", "summary_original": "El norte de Cáceres permanecerá en alerta roja por fuertes lluvias y tormentas el martes 10 de noviembre, y la suspensión de la actividad lectiva en las zonas afectadas busca evitar desplazamientos y garantizar la seguridad de los escolares.", "title_en": "The threat of torrential rain forces expansion of red alert in northern Cáceres", "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(11730,'claude-haiku-5-5','2026-11-10T04:18:47Z',1,0.85,0,'{"actions_taken": ["Participation in regional working meeting convened by the Gobierno Regional de Ica", "Verification and evaluation of regional response capacity", "Provision of scientific information and technical assistance for El Niño preparedness"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}, {"country": "PE", "name": "Gobierno Regional de Ica", "type": "other_national_agency"}], "confidence": 0.85, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": null, "event_location": "Ica, Peru", "event_name": "El Niño", "ew4all_pillars": [1, 2, 4], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "SENAMHI fortalece la preparación ante el Fenómeno El Niño en Ica con información científica y asistencia técnica", "outcome": "not_reported", "outcome_justification": "The snippet describes preparedness coordination and technical support but reports no outcomes of warnings or response.", "relevant": true, "review": false, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, took part in a regional working meeting convened by the Ica regional government to assess the region''s capacity to respond to the El Niño phenomenon. SENAMHI provided scientific information and technical assistance to strengthen preparedness. The item focuses on risk knowledge and preparedness coordination rather than on a specific warning event.", "summary_original": "SENAMHI participó en una reunión de trabajo convocada por el Gobierno Regional de Ica para verificar y evaluar la capacidad de respuesta ante El Niño, brindando información científica y asistencia técnica para fortalecer la preparación.", "title_en": "SENAMHI strengthens preparedness for El Niño phenomenon in Ica with scientific information and technical assistance", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(11739,'claude-haiku-5-5','2026-11-10T04:17:44Z',1,0.8,0,'{"actions_taken": ["Participation in governance and risk knowledge work to strengthen multi-hazard early warning system in Lambayeque"], "agencies": [{"country": "PE", "name": "Cenepred", "type": "other_national_agency"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": [], "event_date": null, "event_location": "Lambayeque, Peru", "event_name": null, "ew4all_pillars": [1, 3], "hazard": "multi_hazard", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "Cenepred aporta al conocimiento del riesgo en Lambayeque, en el marco del Sistema de Alerta Temprana Multiamenaza", "outcome": "not_reported", "outcome_justification": "The snippet describes capacity-building and risk knowledge activities for an early warning system but reports no specific warning event or outcome.", "relevant": true, "review": false, "summary_en": "Cenepred, Peru''s national disaster risk estimation and reduction centre, took part in workshops in Lambayeque aimed at strengthening disaster risk management governance with emphasis on risk knowledge. The activities are framed within the development of a multi-hazard early warning system. No specific hazard event or warning outcome is described in the snippet.", "summary_original": "El Cenepred participó en jornadas para fortalecer la gobernanza en gestión del riesgo de desastres en Lambayeque, con énfasis en el conocimiento del riesgo dentro del Sistema de Alerta Temprana Multiamenaza.", "title_en": "Cenepred contributes to risk knowledge in Lambayeque, within the Multi-hazard Early Warning System framework", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(11743,'claude-haiku-5-5','2026-11-10T04:18:50Z',1,0.7,0,'{"actions_taken": ["Technical support to municipality for reconnaissance of ten critical points ahead of river floods"], "agencies": [{"country": "PE", "name": "CENEPRED", "type": "other_national_agency"}, {"country": "PE", "name": "Autoridad Local del Agua (ALA)", "type": "other_national_agency"}, {"country": "PE", "name": "Municipalidad Distrital de Laberinto", "type": "other_national_agency"}], "confidence": 0.7, "countries": ["PE"], "dissemination_channels": [], "event_date": null, "event_location": "Laberinto, Peru", "event_name": null, "ew4all_pillars": [1, 4], "hazard": "flood", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": null, "lead_time_hours": null, "original_title": "CENEPRED y ALA recorren el distrito de Laberinto para identificar puntos críticos ante inundaciones del río Madre de Dios", "outcome": "not_reported", "outcome_justification": "The snippet describes preventive risk identification work only; no warning outcomes are reported.", "relevant": true, "review": false, "summary_en": "CENEPRED and the Local Water Authority (ALA) provided technical support to the Laberinto district municipality to recognise ten critical points vulnerable to flooding from the Madre de Dios River. The work focuses on risk knowledge and preparedness rather than on a specific warning event.", "summary_original": "CENEPRED y la ALA brindaron acompañamiento técnico a la Municipalidad de Laberinto para reconocer diez puntos críticos ante inundaciones del río Madre de Dios.", "title_en": "CENEPRED and ALA tour Laberinto district to identify critical points for Madre de Dios River floods", "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(11906,'claude-haiku-5-5','2026-11-10T04:18:11Z',1,0.8,0,'{"actions_taken": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "confidence": 0.8, "countries": ["PE"], "dissemination_channels": ["other"], "event_date": "2026-11-09", "event_location": "Piura, Peru", "event_name": null, "ew4all_pillars": [2, 3], "hazard": "heatwave", "impacts": {"affected": null, "deaths": null, "economic_losses": null, "evacuated": null, "injured": null, "missing": null, "people_reached": null}, "language": "es", "lead_time": "multi-day forecast through 12 November", "lead_time_hours": null, "original_title": "Ola de calor en Piura: Senamhi prevé temperaturas de más de 36 °C y posibles lluvias hasta el 12 de noviembre", "outcome": "not_reported", "outcome_justification": "The article reports a Senamhi forecast of high temperatures, UV radiation and possible atmospheric instability, but no outcomes of the warning are given.", "relevant": true, "review": false, "summary_en": "Peru''s National Meteorological and Hydrological Service (Senamhi) forecasts a heat wave in Piura with temperatures of 23 °C to 36 °C on the north coast and 19 °C to 32 °C in the northern highlands, alongside high ultraviolet radiation and possible atmospheric instability and rain until 12 November. The item focuses on the forecast itself and does not report how the warning was disseminated or acted upon.", "summary_original": "El Senamhi pronostica una ola de calor en Piura con temperaturas de 23 °C a 36 °C en la costa norte y de 19 °C a 32 °C en la sierra norte, además de alta radiación ultravioleta y posible inestabilidad atmosférica hasta el 12 de noviembre.", "title_en": "Heat wave in Piura: Senamhi forecasts temperatures above 36 °C and possible rain until 12 November", "wmo_regions": ["III"]}');
