INSERT INTO "items" VALUES(141,'https://www.defconlevel.com/alert/2026-10-16-nws-noaa-weather-tropical-storm-warning-issued-october-16-at-9-43pm-chst-by-nws-tiyan-gu','https://defconlevel.com/alert/2026-10-16-nws-noaa-weather-tropical-storm-warning-issued-october-16-at-9-43pm-chst-by-nws-tiyan-gu','NWS / NOAA weather: Tropical Storm Warning issued October 16 at 9:43PM ChST by NWS Tiyan GU','nwsnoaaweathertropicalstormwarningissuedoctober16at943pmchstbynwstiyangu','websearch_en','defconlevel.com','en','2026-10-16T15:08:16Z','2026-10-16T15:08:22Z','Guam was placed in Condition of Readiness 2 as of 1 PM ChST, and Champi is likely to move near Guam as a typhoon. A Typhoon Warning continues for Guam and Rota, with a Tropical Storm Warning and Typhoon Watch for Tinian and Saipan.',3.0,'classified',NULL,43);
INSERT INTO "items" VALUES(142,'https://govonestop.com/nws/extreme-typhoon-warning-effective-10152026-2351','https://govonestop.com/nws/extreme-typhoon-warning-effective-10152026-2351','Extreme Typhoon Warning','extremetyphoonwarning','websearch_en','govonestop.com','en','2026-10-16T15:08:16Z','2026-10-16T15:08:22Z','The NWS Tiyan GU Typhoon Warning, effective October 15, 2026 at 11:51 PM, expires October 16 at 2:00 PM and warns of typhoon conditions with winds of 64 knots or more for Guam and Rota coastal waters.',2.0,'classified',NULL,43);
