INSERT INTO "items" VALUES(1448,'https://www.preventionweb.net/publication/documents-and-publications/silent-adapters-uncovering-resilience-smaller-firms','https://preventionweb.net/publication/documents-and-publications/silent-adapters-uncovering-resilience-smaller-firms','The silent adapters: Uncovering the resilience of smaller firms in developing countries','thesilentadaptersuncoveringtheresilienceofsmallerfirmsindevelopingcountries','preventionweb','PreventionWeb','en','2026-10-16T16:14:24Z','2026-10-18T03:04:05Z','This report analyzes how MSMEs in EMDEs adapt to climate change using WBES data, finds adaptation is more widespread than assumed yet underreported, shows finance as a key constraint, and presents an MSME Adaptation Finance Typology to inform solutions.',0.0,'filtered_out',NULL,NULL);
