INSERT INTO "items" VALUES(1453,'https://www.preventionweb.net/publication/documents-and-publications/immersive-geospatial-learning-flood-disaster-education','https://preventionweb.net/publication/documents-and-publications/immersive-geospatial-learning-flood-disaster-education','Immersive geospatial learning for flood disaster education: Integrating GIS, augmented reality, spatial literacy, and ecopedagogy','immersivegeospatiallearningforflooddisastereducationintegratinggisaugmentedrealityspatialliteracyandecopedagogy','preventionweb','PreventionWeb','en','2026-10-16T13:51:29Z','2026-10-18T03:04:05Z','This study investigates the development and evaluation of immersive geospatial learning materials for flood disaster education, integrating GIS, Augmented Reality (AR), spatial literacy, higher-order thinking skills, and ecopedagogical perspectives.',1.0,'classified',NULL,NULL);
INSERT INTO "items" VALUES(1454,'https://www.preventionweb.net/publication/documents-and-publications/disaster-risk-reduction-state-play-africa','https://preventionweb.net/publication/documents-and-publications/disaster-risk-reduction-state-play-africa','Disaster risk reduction state of play in Africa','disasterriskreductionstateofplayinafrica','preventionweb','PreventionWeb','en','2026-10-16T13:31:05Z','2026-10-18T03:04:05Z','This report assesses 2023–2026 disaster risk reduction in Africa since the 2015 Sendai Framework, finding climate hazards caused 90% of disasters and $133B losses, noting policy progress but highlighting persistent finance, data, and implementation gaps.',0.0,'filtered_out',NULL,NULL);
