INSERT INTO "items" VALUES(3183,'https://www.preventionweb.net/publication/documents-and-publications/managing-infodemic-global-south-systematic-evidence','https://preventionweb.net/publication/documents-and-publications/managing-infodemic-global-south-systematic-evidence','Managing an infodemic in the global south: a systematic evidence synthesis from COVID-19 social listening reports','managinganinfodemicintheglobalsouthasystematicevidencesynthesisfromcovid19sociallisteningreports','preventionweb','PreventionWeb','en','2026-10-21T11:00:18Z','2026-10-22T03:09:53Z','This study analyses COVID-19 misinformation in South Africa, highlighting how continuous social listening and community-based communication can inform more adaptive responses to public health misinformation.',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(3184,'https://www.preventionweb.net/news/listen-understand-repeat-circular-approach-good-communication-health-crisis','https://preventionweb.net/news/listen-understand-repeat-circular-approach-good-communication-health-crisis','Listen, understand, repeat: the circular approach to good communication in a health crisis','listenunderstandrepeatthecircularapproachtogoodcommunicationinahealthcrisis','preventionweb','PreventionWeb','en','2026-10-21T09:48:14Z','2026-10-22T03:09:53Z','This article addresses how social listening can improve health crisis communication, highlighting the need to identify public concerns, tailor responses and continuously assess changing information needs.',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(3185,'https://www.preventionweb.net/event/droughts-floods-and-food-systems-risk-dialogue-part-i-when-el-nino-meets-global-warming-rise','https://preventionweb.net/event/droughts-floods-and-food-systems-risk-dialogue-part-i-when-el-nino-meets-global-warming-rise','Droughts, Floods and Food Systems Risk Dialogue – Part I: When El Niño meets global warming: The rise of compound drought extremes','droughtsfloodsandfoodsystemsriskdialoguepartiwhenelninomeetsglobalwarmingtheriseofcompounddroughtextremes','preventionweb','PreventionWeb','en','2026-10-21T07:41:04Z','2026-10-22T03:09:53Z','In Part 1 of the Risk Dialogue Series on "Droughts, Floods and Food Systems," experts and participants will examine how changing climate extremes are transforming drought risk and reshaping the future of food security.',2.0,'classified',NULL,NULL);
