INSERT INTO "items" VALUES(3189,'https://www.preventionweb.net/publication/documents-and-publications/anthropogenic-fingerprint-emerging-infectious-diseases','https://preventionweb.net/publication/documents-and-publications/anthropogenic-fingerprint-emerging-infectious-diseases','The anthropogenic fingerprint on emerging infectious diseases','theanthropogenicfingerprintonemerginginfectiousdiseases','preventionweb','PreventionWeb','en','2026-10-20T15:37:41Z','2026-10-22T03:09:53Z','This paper consolidates 58,319 outbreak event records for 32 diseases and systematically test how 16 hypothesized social and environmental drivers impact outbreak geographies, while accounting for detection and reporting biases.',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(3190,'https://www.preventionweb.net/publication/documents-and-publications/assessment-nature-related-risks-ecosystem-services','https://preventionweb.net/publication/documents-and-publications/assessment-nature-related-risks-ecosystem-services','The assessment of nature-related risks: From ecosystem services vulnerability to economic exposure and financial disclosures','theassessmentofnaturerelatedrisksfromecosystemservicesvulnerabilitytoeconomicexposureandfinancialdisclosures','preventionweb','PreventionWeb','en','2026-10-20T15:21:35Z','2026-10-22T03:09:53Z','This paper describes how to use the Integrated system for Natural Capital Accounts to measure and account for ecosystem vulnerability, which constitutes the first component of nature-related risk.',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(3191,'https://www.preventionweb.net/publication/documents-and-publications/alpine-hazards-cultural-memory-and-storytellings-relevance','https://preventionweb.net/publication/documents-and-publications/alpine-hazards-cultural-memory-and-storytellings-relevance','Alpine hazards, cultural memory, and storytelling''s relevance for collective risk communication and disaster processing: A scoping review','alpinehazardsculturalmemoryandstorytellingsrelevanceforcollectiveriskcommunicationanddisasterprocessingascopingreview','preventionweb','PreventionWeb','en','2026-10-20T15:03:10Z','2026-10-22T03:09:53Z','This study examines how storytelling and cultural memory can strengthen risk communication in Alpine communities, helping translate hazard information into protective action, collective resilience and disaster recovery.',0.0,'filtered_out',NULL,NULL);
