INSERT INTO "items" VALUES(3725,'https://www.preventionweb.net/publication/documents-and-publications/building-lasting-financial-protection-enduring-legacy-global','https://preventionweb.net/publication/documents-and-publications/building-lasting-financial-protection-enduring-legacy-global','Building lasting financial protection: The enduring legacy of the global partnership on disaster risk financing analytics','buildinglastingfinancialprotectiontheenduringlegacyoftheglobalpartnershipondisasterriskfinancinganalytics','preventionweb','PreventionWeb','en','2026-10-21T19:38:11Z','2026-10-23T03:10:24Z','This report describes DRF Analytics, a World Bank–managed initiative that developed adaptable tools for governments to improve disaster risk financing, enabling proactive planning and operational impact across diverse countries and hazards.',0.0,'filtered_out',NULL,NULL);
