INSERT INTO "items" VALUES(5616,'https://npr.org/2026/10/23/nx-s1-6014742/flooding-weather-four-corners','https://npr.org/2026/10/23/nx-s1-6014742/flooding-weather-four-corners','Flooding in Four Corners region displaces residents, as storms move southeast','floodinginfourcornersregiondisplacesresidentsasstormsmovesoutheast','websearch_en','npr.org','en','2026-10-25T04:09:36Z','2026-10-27T04:09:39Z','Emergency responders rescued people from roofs after floodwater inundated homes in the Four Corners region; a county was placed under emergency declaration and residents in susceptible areas were told to evacuate. Colorado Gov. Jared Polis declared disaster emergencies in 12 counties.',2.0,'classified',NULL,182);
