INSERT INTO "items" VALUES(6052,'https://www.preventionweb.net/publication/documents-and-publications/exploring-risk-tolerance-under-uncertainty-workshop','https://preventionweb.net/publication/documents-and-publications/exploring-risk-tolerance-under-uncertainty-workshop','Exploring risk tolerance under uncertainty: workshop on a participatory risk-tolerance methodology for recovery decisions in Grindavík, Iceland','exploringrisktoleranceunderuncertaintyworkshoponaparticipatoryrisktolerancemethodologyforrecoverydecisionsingrindavikiceland','preventionweb','PreventionWeb','en','2026-10-26T18:07:53Z','2026-10-28T04:06:53Z','This report presents a participatory risk-tolerance methodology developed to support recovery decision-making in Grindavík, Iceland, following prolonged volcanic and seismic activity that began in 2023.',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(6053,'https://www.preventionweb.net/news/flood-risk-rises-some-communities-question-idea-resilience','https://preventionweb.net/news/flood-risk-rises-some-communities-question-idea-resilience','As flood risk rises, some communities question the idea of resilience','asfloodriskrisessomecommunitiesquestiontheideaofresilience','preventionweb','PreventionWeb','en','2026-10-26T18:04:04Z','2026-10-28T04:06:53Z','Resilience is often considered to be a positive idea. It suggests that people can adapt to uncertainty, to prepare for disruption, and recover quickly when floods strike. But research suggests many communities are deeply uncomfortable with this messaging.',2.0,'classified',NULL,NULL);
