INSERT INTO "items" VALUES(6508,'https://www.preventionweb.net/news/where-humans-build-mosquitoes-follow-bringing-dengue-west-nile-and-other-diseases-them','https://preventionweb.net/news/where-humans-build-mosquitoes-follow-bringing-dengue-west-nile-and-other-diseases-them','Where humans build, mosquitoes follow – bringing dengue, West Nile and other diseases with them','wherehumansbuildmosquitoesfollow','preventionweb','PreventionWeb','en','2026-10-28T13:43:36Z','2026-10-29T04:10:16Z','Longer warm seasons means mosquitoes will become a growing public health issue, and controlling them will become increasingly crucial.',0.0,'filtered_out',NULL,NULL);
