INSERT INTO "items" VALUES(8195,'https://reliefweb.int/report/south-sudan/united-kingdom-funding-helps-protect-south-sudan-anticipated-climate-shocks','https://reliefweb.int/report/south-sudan/united-kingdom-funding-helps-protect-south-sudan-anticipated-climate-shocks','United Kingdom funding helps protect South Sudan from anticipated climate shocks','unitedkingdomfundinghelpsprotectsouthsudanfromanticipatedclimateshocks','reliefweb_ew_en','ReliefWeb - Updates','en','2026-10-30T15:03:08Z','2026-11-02T04:10:19Z','Countries: South Sudan, United Kingdom of Great Britain and Northern Ireland Sources: Food and Agriculture Organization of the United Nations, World Food Programme FAO-WFP JOINT News Release JUBA, South Sudan – The United Kingdom has provided £2.1 million (US$2.8 million) to the Food and Agriculture Organization of the United Nations (FAO) and the United Nations World Food Programme (WFP) to expand anticipatory action interventions in South Sudan, helping hundreds of thousands of people in vulnerable communities prepare for forecast climate shocks before their most damaging impacts are felt. T',3.0,'classified',NULL,245);
