INSERT INTO "items" VALUES(9902,'https://www.preventionweb.net/publication/documents-and-publications/improving-seismic-resilience-indonesia-baseline-analysis-and','https://preventionweb.net/publication/documents-and-publications/improving-seismic-resilience-indonesia-baseline-analysis-and','Improving seismic resilience in Indonesia: a baseline analysis and investment recommendations towards establishing a national program','improvingseismicresilienceinindonesiaabaselineanalysisandinvestmentrecommendationstowardsestablishinganationalprogram','preventionweb','PreventionWeb','en','2026-11-04T22:30:17Z','2026-11-06T04:07:04Z','The overall objective of this report is to give guidance and facilitate discussion on priority areas for investment to inform a new national-level seismic resilience program for Indonesia, with a focus on public buildings in urban areas.',0.0,'filtered_out',NULL,NULL);
