INSERT INTO "items" VALUES(9904,'https://www.preventionweb.net/publication/documents-and-publications/heatwaves-invisible-disasters-disability-climate-justice-and','https://preventionweb.net/publication/documents-and-publications/heatwaves-invisible-disasters-disability-climate-justice-and','Heatwaves as invisible disasters: Disability, climate justice, and urban and peri-urban risk reduction in Bangladesh','heatwavesasinvisibledisastersdisabilityclimatejusticeandurbanandperiurbanriskreductioninbangladesh','preventionweb','PreventionWeb','en','2026-11-04T22:23:15Z','2026-11-06T04:07:04Z','This qualitative community-based study explores how people with disabilities in urban and suburban Bangladesh experience and cope with extreme heat through a decolonial framework that centers lived experiences and community knowledge.',1.0,'classified',NULL,NULL);
