INSERT INTO "stories" VALUES(31,'flood|AR|anelo','heavy_rain','2026-10-16T15:43:05Z','2026-10-21T03:21:03Z','2026-10-16','{"actions": ["Warning issued about flash flooding, water accumulation and possible complications on roads and riverside areas", "Public advised to follow official information channels", "Evacuations of residents"], "agencies": [{"country": "AR", "name": "Secretaría de Emergencias y Gestión de Riesgos (Neuquén)", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["other"], "confidence": 0.8, "countries": [{"code": "AR", "name": "Argentina"}], "event_date": "2026-10-16", "event_location": "Neuquén, Argentina", "event_name": null, "first_seen": "2026-10-16T15:35:56Z", "hazard": "heavy_rain", "hazards": ["flash_flood", "heavy_rain"], "id": 31, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-21T03:21:03Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes warnings issued but does not report any outcome of the alert.", "pillars": [3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-16T00:38:22Z", "source_name": "Clarín (Argentina) sociedad", "title": "Calles inundadas, ríos de barro y vecinos en canoa tras una fuerte tormenta en Añelo, la capital de Vaca Muerta", "title_en": "Flooded streets, mud rivers and neighbours in canoes after a strong storm in Añelo, the capital of Vaca Muerta", "url": "https://www.clarin.com/sociedad/calles-inundadas-rios-barro-vecinos-canoa-fuerte-tormenta-anelo-capital-vaca-muerta_0_t3B8Bf9Ebz.html"}, {"language": "es", "published_at": "2026-10-19T21:30:00Z", "source_name": "neuquenalinstante.com.ar", "title": "Una semana de lluvias pone en alerta a distintas zonas de Neuquén | Neuquén Al Instante", "title_en": "A week of rain puts various areas of Neuquén on alert", "url": "https://www.neuquenalinstante.com.ar/noticias/2026/10/19/145160-una-semana-de-lluvias-pone-en-alerta-a-distintas-zonas-de-neuquen"}, {"language": "es", "published_at": "2026-10-20T04:45:00Z", "source_name": "anbariloche.com.ar", "title": "Una semana de lluvias pone en alerta a distintas zonas de Neuquén", "title_en": "A week of rain puts various areas of Neuquén on alert", "url": "https://www.anbariloche.com.ar/noticias/2026/10/19/120443-una-semana-de-lluvias-pone-en-alerta-a-distintas-zonas-de-neuquen"}], "summaries_original": {"es": "La Secretaría de Emergencias y Gestión de Riesgos de Neuquén advirtió sobre fenómenos repentinos, acumulación de agua y posibles complicaciones en rutas y zonas ribereñas tras una semana de lluvias, y recomendó seguir los canales oficiales de información."}, "summary_en": "The Emergency and Risk Management Secretariat of Neuquén warned of sudden flooding, water accumulation and possible disruption on roads and riverside zones after a week of rain. Residents were advised to follow official channels for information. No outcome of the warning is reported.", "title": "A week of rain puts various areas of Neuquén on alert", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(32,'flood|RW|rubavu and nyabihu districts','flood','2026-10-16T15:43:05Z','2026-10-16T15:26:20Z','2026-10-16','{"actions": ["Activation of simplified Early Action Protocol (sEAP) triggered by Meteo Rwanda dekadal forecast exceeding 90 mm of rainfall over 10 days in Rubavu and Nyabihu districts"], "agencies": [{"country": "RW", "name": "Rwanda Red Cross", "type": "NGO"}, {"country": "RW", "name": "Meteo Rwanda", "type": "NMHS"}, {"country": null, "name": "International Federation of Red Cross and Red Crescent Societies", "type": "international"}], "agency_types": ["NGO", "NMHS", "international"], "channels": [], "confidence": 0.93, "countries": [{"code": "RW", "name": "Rwanda"}], "event_date": "2026-10-16", "event_location": "Rubavu and Nyabihu districts, Western Province, Rwanda", "event_name": null, "first_seen": "2026-10-16T15:26:20Z", "hazard": "flood", "hazards": ["flood"], "id": 32, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-16T15:26:20Z", "lead_time": "10-day dekadal rainfall forecast issued 10 October 2026", "outcome": "not_reported", "outcome_justification": "The item describes the activation of an early action protocol based on forecasts; no outcomes of the actions are reported in the snippet.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-16T01:00:43Z", "source_name": "ReliefWeb - Updates", "title": "Rwanda | Flood - Simplified Early Action Protocol: Activation (EAP No.: sEAP2025RW01, Operation No.: MDRRW026), 13 October 2026", "title_en": "Rwanda | Flood - Simplified Early Action Protocol: Activation (EAP No.: sEAP2025RW01, Operation No.: MDRRW026), 13 October 2026", "url": "https://reliefweb.int/report/rwanda/rwanda-flood-simplified-early-action-protocol-activation-eap-no-seap2025rw01-operation-no-mdrrw026-13-october-2026"}], "summaries_original": {}, "summary_en": "The IFRC activated a simplified Early Action Protocol for floods in Rubavu and Nyabihu distric