INSERT INTO "stories" VALUES(79,'','drought','2026-10-20T03:20:27Z','2026-10-20T03:07:52Z','2026-10-19','{"actions": ["planting and harvesting decisions based on sub-seasonal forecasts", "more efficient irrigation planning"], "agencies": [{"country": "IN", "name": "India Meteorological Department", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": [], "confidence": 0.7, "countries": [{"code": "IN", "name": "India"}], "event_date": "2026-10-19", "event_location": null, "event_name": null, "first_seen": "2026-10-20T03:07:52Z", "hazard": "drought", "hazards": ["drought"], "id": 79, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-20T03:07:52Z", "lead_time": "weeks ahead (sub-seasonal)", "outcome": "not_reported", "outcome_justification": "The snippet describes use of sub-seasonal forecasts for anticipatory planning but does not report measured outcomes.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-19T13:14:53Z", "source_name": "PreventionWeb", "title": "How Indian farmers use weather forecasts to plan weeks ahead", "title_en": "How Indian farmers use weather forecasts to plan weeks ahead", "url": "https://www.preventionweb.net/news/how-indian-farmers-use-weather-forecasts-plan-weeks-ahead"}], "summaries_original": {}, "summary_en": "India is using sub-seasonal forecasts to help farmers anticipate rainfall, drought and pest risks several weeks in advance. Examples show how longer-range weather information supports planting, harvesting and irrigation decisions. The snippet does not report quantified outcomes.", "title": "How Indian farmers use weather forecasts to plan weeks ahead", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(80,'','flood','2026-10-20T03:20:27Z','2026-10-20T03:07:52Z','2026-10-19','{"actions": ["Anticipatory action using established triggers and beneficiary registries", "Development of flood risk insurance and a Community Protection Fund for post-flood payouts"], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "BD", "name": "Bangladesh"}], "event_date": "2026-10-19", "event_location": "Bangladesh", "event_name": null, "first_seen": "2026-10-20T03:07:52Z", "hazard": "flood", "hazards": ["flood"], "id": 80, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-20T03:07:52Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes an initiative under development and does not report measured outcomes of warnings.", "pillars": [3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-19T13:15:36Z", "source_name": "PreventionWeb", "title": "Leveraging anticipatory action for disaster risk finance: lessons from Bangladesh", "title_en": "Leveraging anticipatory action for disaster risk finance: lessons from Bangladesh", "url": "https://www.preventionweb.net/news/leveraging-anticipatory-action-disaster-risk-finance-lessons-bangladesh"}], "summaries_original": {}, "summary_en": "Bangladesh is building flood risk insurance and a Community Protection Fund by reusing its existing anticipatory action systems, including established flood triggers, beneficiary registries and delivery networks. The initiative adapts these early warning-linked mechanisms for post-flood payouts. The snippet does not report specific warning lead times or outcomes.", "title": "Leveraging anticipatory action for disaster risk finance: lessons from Bangladesh", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(81,'tropical_cyclone|AL|adriatic sea','storm_surge','2026-10-20T03:20:27Z','2026-10-20T03:07:52Z','2026-10-19','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "AL", "name": "Albania"}, {"code": "HR", "name": "Croatia"}, {"code": "IT", "name": "Italy"}, {"code": "ME", "name": "Montenegro"}, {"code": "SI", "name": "Slovenia"}], "event_date": "2026-10-19", "event_location": "Adriatic Sea", "event_name": null, "first_seen": "2026-10-20T03:07:52Z", "hazard": "storm_surge", "hazards": ["storm_surge"], "id": 81, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-20T03:07:52Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a research evaluation of forecasting approaches for a past event; no warning dissemination or outcomes are reported.", "pillars": [2], "review": false, "sources": [{"language": "en", "published_at": "2026-10-19T14:19:25Z", "source_name": "PreventionWeb", "title": "Forecasting compound sea level extremes: the 29–30 October 2018 Adriatic storm surge and meteotsunami extreme", "title_en": "Forecasting compound sea level extremes: the 29–30 October 2018 Adriatic storm surge and meteotsunami extreme", "url": "https://www.preventionweb.net/publication/documents-and-publications/forecasting-compound-sea-level-extremes-29-30-october-2018"}], "summaries_original": {}, "summary_en": "This study uses the October 2018 extreme sea level event in the Adriatic Sea as a case study to evaluate two approaches for forecasting compound sea level extremes, combining storm surge and meteotsunami hazards. The work focuses on forecasting methodology, which relates to detection, monitoring, analysis and forecasting of the hazard. It does not report on warnings issued or their outcomes.", "title": "Forecasting compound sea level extremes: the 29–30 October 2018 Adriatic storm surge and meteotsunami extreme", "wmo_regions": ["VI"]}');
