INSERT INTO "stories" VALUES(96,'heatwave|CH|geneva','heatwave','2026-10-21T03:25:56Z','2026-10-22T03:09:51Z','2026-10-20','{"actions": ["Convened a Europe-wide dialogue in Geneva on extreme heat resilience, reviewing the summer 2026 heat events and discussing coordinated action across government levels", "Multi-stakeholder dialogue in Geneva on extreme heat resilience and linking heat forecasts to action"], "agencies": [{"country": null, "name": "UN Office for Disaster Risk Reduction (UNDRR)", "type": "international"}, {"country": null, "name": "UNDRR", "type": "international"}, {"country": "CH", "name": "Government of Switzerland", "type": "other_national_agency"}], "agency_types": ["international", "other_national_agency"], "channels": [], "confidence": 0.8, "countries": [{"code": "CH", "name": "Switzerland"}], "event_date": "2026-10-20", "event_location": "Geneva, Switzerland", "event_name": null, "first_seen": "2026-10-21T03:10:57Z", "hazard": "heatwave", "hazards": ["heatwave"], "id": 96, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-22T03:09:51Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a policy dialogue event; it does not report whether warnings were issued or what outcomes resulted from them.", "pillars": [1, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-20T12:36:07Z", "source_name": "UNDRR news", "title": "From forecasts to action: UNDRR and Switzerland convene Europe-wide dialogue on extreme heat resilience", "title_en": "From forecasts to action: UNDRR and Switzerland convene Europe-wide dialogue on extreme heat resilience", "url": "https://www.undrr.org/news/forecasts-action-undrr-and-switzerland-convene-europe-wide-dialogue-extreme-heat-resilience"}, {"language": "en", "published_at": "2026-10-21T08:33:05Z", "source_name": "ReliefWeb - Updates", "title": "World: From forecasts to action: UNDRR and Switzerland convene Europe-wide dialogue on extreme heat resilience", "title_en": "World: From forecasts to action: UNDRR and Switzerland convene Europe-wide dialogue on extreme heat resilience", "url": "https://reliefweb.int/report/world/forecasts-action-undrr-and-switzerland-convene-europe-wide-dialogue-extreme-heat-resilience"}], "summaries_original": {}, "summary_en": "More than 60 representatives from governments, European institutions, academia, civil society, the private sector and UN agencies met in Geneva to review Europe''s summer 2026 heat and discuss extreme heat as a systemic risk requiring coordinated action. The item is relevant to early warning mainly through its focus on moving from forecasts to action on heat resilience, though the snippet provides no specific warning details.", "title": "World: From forecasts to action: UNDRR and Switzerland convene Europe-wide dialogue on extreme heat resilience", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(97,'flood|AR|alto valle','flood','2026-10-21T03:26:03Z','2026-10-21T03:21:03Z','2026-10-20','{"actions": ["Legislative project requesting reports on works executed after a 2009 Supreme Court ruling"], "agencies": [{"country": "AR", "name": "Legislatura de Río Negro", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.7, "countries": [{"code": "AR", "name": "Argentina"}], "event_date": "2026-10-20", "event_location": "Alto Valle, Río Negro, Argentina", "event_name": null, "first_seen": "2026-10-21T03:21:03Z", "hazard": "flood", "hazards": ["flood"], "id": 97, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-21T03:21:03Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a legislative initiative on flood-risk infrastructure and the effects of El Niño; no warning issuance, dissemination or outcome is reported.", "pillars": [1], "review": false, "sources": [{"language": "es", "published_at": "2026-10-20T16:00:00Z", "source_name": "anroca.com.ar", "title": "Alerta por el riesgo de inundaciones en el Alto Valle: piden informes por las obras en Portezuelo Grande", "title_en": "Flood risk alert in the Alto Valle: reports requested on works at Portezuelo Grande", "url": "https://www.anroca.com.ar/noticias/2026/10/20/228641-alerta-por-el-riesgo-de-inundaciones-en-el-alto-valle-piden-informes-por-las-obras-en-portezuelo-grande"}], "summaries_original": {"es": "Un proyecto presentado en la Legislatura de Río Negro busca conocer qué medidas se ejecutaron tras un fallo de la Corte Suprema de 2009, en medio de la alerta por riesgo de inundaciones en el Alto Valle y los efectos de El Niño."}, "summary_en": "A bill presented in the Río Negro Legislature seeks information on measures taken at Portezuelo Grande following a 2009 Supreme Court ruling, amid concern about flood risk in the Alto Valle. The item also highlights potential El Niño effects and the safety of local communities. It concerns flood risk governance rather than a specific warning event.", "title": "Flood risk alert in the Alto Valle: reports requested on works at Portezuelo Grande", "wmo_regions": ["III"]}');
