INSERT INTO "stories" VALUES(128,'heatwave|PE|selva (jungle region)','heatwave','2026-10-23T03:23:34Z','2026-10-25T04:16:26Z','2026-10-23','{"actions": ["Precautions advised to the population", "INDECI recommends adopting preparedness measures in response to SENAMHI Aviso N.° 433"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "INDECI", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other", "website"], "confidence": 0.93, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-23", "event_location": "Peruvian jungle (selva), Peru", "event_name": null, "first_seen": "2026-10-23T03:19:49Z", "hazard": "heatwave", "hazards": ["heatwave"], "id": 128, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-25T04:16:26Z", "lead_time": "about 1 day before 25-26 October", "outcome": "not_reported", "outcome_justification": "The item reports a forecast and red alert issued by Senamhi ahead of the event; no outcomes are yet reported.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "INDECI Perú noticias", "title": "INDECI recomienda medidas de preparación ante el incremento de la temperatura diurna en la selva", "title_en": "INDECI recommends preparedness measures ahead of rising daytime temperatures in the jungle", "url": "https://www.gob.pe/institucion/indeci/noticias/1461278-indeci-recomienda-medidas-de-preparacion-ante-el-incremento-de-la-temperatura-diurna-en-la-selva"}, {"language": "es", "published_at": "2026-10-24T14:09:16Z", "source_name": "La República (Perú) sociedad", "title": "Termómetros llegarán a 39°C y activan alerta roja este fin de semana: Senamhi advierte ola de calor extremo en 7 regiones", "title_en": "Thermometers to reach 39°C and trigger red alert this weekend: Senamhi warns of extreme heatwave in 7 regions", "url": "https://larepublica.pe/sociedad/2026/10/24/termometros-llegaran-a-39c-y-activan-alerta-roja-este-fin-de-semana-senamhi-advierte-ola-de-calor-extremo-en-7-regiones-1248144"}], "summaries_original": {"es": "Senamhi advierte que la selva peruana enfrentará temperaturas de hasta 39°C el 25 y 26 de octubre, lo que activa alertas rojas en varias regiones. Se requieren precauciones."}, "summary_en": "Senamhi forecasts temperatures up to 39°C in Peru''s jungle on 25-26 October, triggering red alerts in several regions. The agency urges precautions for the population. The item documents a forecast and heat alert issued in advance of the hazard.", "title": "Thermometers to reach 39°C and trigger red alert this weekend: Senamhi warns of extreme heatwave in 7 regions", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(129,'','tropical_cyclone','2026-10-23T03:23:43Z','2026-10-23T03:10:24Z','2026-10-21','{"actions": [], "agencies": [{"country": "US", "name": "Florida State University", "type": "other"}], "agency_types": ["other"], "channels": ["other"], "confidence": 0.9, "countries": [{"code": "US", "name": "United States"}], "event_date": "2026-10-21", "event_location": null, "event_name": null, "first_seen": "2026-10-23T03:10:24Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 129, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-23T03:10:24Z", "lead_time": null, "outcome": "mixed", "outcome_justification": "The study finds the updated hurricane forecast graphic helps people identify inland watch areas but does not improve risk perception or protective intentions.", "pillars": [3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-21T19:38:55Z", "source_name": "PreventionWeb", "title": "FSU study finds new hurricane graphic helps people identify watch areas, doesn’t change risk perception", "title_en": "FSU study finds new hurricane graphic helps people identify watch areas, doesn''t change risk perception", "url": "https://www.preventionweb.net/news/fsu-study-finds-new-hurricane-graphic-helps-people-identify-watch-areas-doesnt-change-risk"}], "summaries_original": {}, "summary_en": "A Florida State University study evaluated an updated hurricane forecast graphic and found it helps people identify inland watch areas. However, it did not improve their risk perception or protective intentions. The authors highlight the need for clearer local impact information to support safety decisions.", "title": "FSU study finds new hurricane graphic helps people identify watch areas, doesn''t change risk perception", "wmo_regions": ["IV"]}');
