INSERT INTO "stories" VALUES(136,'','multi_hazard','2026-10-23T03:23:51Z','2026-10-23T03:10:24Z','2026-10-22','{"actions": [], "agencies": [{"country": "BD", "name": "Bangladesh Meteorological Department", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": [], "confidence": 0.85, "countries": [{"code": "BD", "name": "Bangladesh"}], "event_date": "2026-10-22", "event_location": "Bangladesh", "event_name": null, "first_seen": "2026-10-23T03:10:24Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 136, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-23T03:10:24Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet discusses how forecasts should be used for anticipatory action but does not report a specific warning event outcome.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-22T13:35:19Z", "source_name": "PreventionWeb", "title": "Rethinking how we use forecast: Five changes to strengthen anticipatory action in Bangladesh", "title_en": "Rethinking how we use forecast: Five changes to strengthen anticipatory action in Bangladesh", "url": "https://www.preventionweb.net/news/rethinking-how-we-use-forecast-five-changes-strengthen-anticipatory-action-bangladesh"}], "summaries_original": {}, "summary_en": "The article argues that better forecasts alone will not produce early action in Bangladesh and calls for actionable risk information, stronger decision-support systems and local capacity to act before disasters strike. It frames anticipatory action as dependent on how forecasts are translated and used by local organisations.", "title": "Rethinking how we use forecast: Five changes to strengthen anticipatory action in Bangladesh", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(137,'','flood','2026-10-23T03:23:51Z','2026-10-23T03:10:24Z','2026-10-22','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "AU", "name": "Australia"}], "event_date": "2026-10-22", "event_location": "Australia", "event_name": null, "first_seen": "2026-10-23T03:10:24Z", "hazard": "flood", "hazards": ["flood"], "id": 137, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-23T03:10:24Z", "lead_time": "weeks to months ahead", "outcome": "not_reported", "outcome_justification": "The report assesses feasibility of long-range flood outlooks and finds sub-seasonal-to-seasonal forecasts can enhance preparedness, but no realised warning outcome is described.", "pillars": [1, 2], "review": false, "sources": [{"language": "en", "published_at": "2026-10-22T13:40:05Z", "source_name": "PreventionWeb", "title": "Long-range flood outlook for strategic preparedness - final report", "title_en": "Long-range flood outlook for strategic preparedness - final report", "url": "https://www.preventionweb.net/publication/documents-and-publications/long-range-flood-outlook-strategic-preparedness-final-report"}], "summaries_original": {}, "summary_en": "A final report assesses the feasibility of long-range flood outlooks for Australia, using co-design with end users and the BJP model to quantify and map flood likelihood. It finds that sub-seasonal-to-seasonal (S2S) forecasts can enhance preparedness by identifying elevated flood-risk weeks to months ahead.", "title": "Long-range flood outlook for strategic preparedness - final report", "wmo_regions": ["V"]}');
INSERT INTO "stories" VALUES(138,'','wildfire','2026-10-23T03:23:52Z','2026-10-23T03:10:24Z','2026-10-22','{"actions": ["Combining NASA fire observations with official reports", "Email alerts for followed locations"], "agencies": [{"country": "US", "name": "NASA", "type": "other"}], "agency_types": ["other"], "channels": ["other"], "confidence": 0.7, "countries": [], "event_date": "2026-10-22", "event_location": null, "event_name": null, "first_seen": "2026-10-23T03:10:24Z", "hazard": "wildfire", "hazards": ["wildfire"], "id": 138, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-23T03:10:24Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item describes a platform offering monitoring and alerts but reports no outcomes of warnings.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-22T14:03:40Z", "source_name": "PreventionWeb", "title": "Watch Fire brings wildfire information, analysis and risk insights together for communities worldwide", "title_en": "Watch Fire brings wildfire information, analysis and risk insights together for communities worldwide", "url": "https://www.preventionweb.net/news/watch-fire-brings-wildfire-information-analysis-and-risk-insights-together-communities"}], "summaries_original": {}, "summary_en": "A new wildfire information platform, Watch Fire, combines NASA satellite fire observations with official reports to provide information, analysis and risk insights. Users can subscribe to location-based email alerts for fire activity. The platform also accepts community-contributed photos and videos, which are reviewed before publication.", "title": "Watch Fire brings wildfire information, analysis and risk insights together for communities worldwide", "wmo_regions": []}');
INSERT INTO "stories" VALUES(139,'flood|JP|miyako and yaeyama regions','heavy_rain','2026-10-23T03:23:59Z','2026-10-24T03:09:24Z','2026-10-23','{"actions": ["JMA issued a linear precipitation band half-day-ahead forecast information (線状降水帯半日前予測) at 03:58 on 23 Oct", "JMA issued a Kishō Bōsai Sokuhō (weather disaster bulletin) announcing an imminent linear precipitation band forecast at 10:28 JST for the Ishigaki Island area"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}, {"country": "JP", "name": "Japan Weather Association (tenki.jp)", "type": "media"}, {"country": "JP", "name": "NHK", "type": "media"}, {"country": "JP", "name": "San''in Chuo Shimbun", "type": "media"}], "agency_types": ["NMHS", "media"], "channels": ["other", "website"], "confidence": 0.95, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-23", "event_location": "Miyako and Yaeyama regions, Okinawa Prefecture, Japan", "event_name": null, "first_seen": "2026-10-23T03:19:00Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 139, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-24T03:09:24Z", "lead_time": "about half a day (半日前予測) ahead of the expected event, from midday 23 Oct to early morning 24 Oct", "outcome": "not_reported", "outcome_justification": "The item only reports the forecast/advisory issuance; no outcome of the event is stated.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-23T03:18:55Z", "source_name": "tenki.jp", "title": "【速報】沖縄県は23日昼過ぎから24日明け方にかけて「線状降水帯」発生の可能性(気象予報士 日直主任 2026年10月23日) - 日本気象協会 tenki.jp", "title_en": "[Breaking] Okinawa Prefecture may see linear precipitation bands (senjō kōsuitai) from midday on the 23rd to early morning on the 24th (Weather forecaster duty chief, 23 October 2026) - Japan Weather Association tenki.jp", "url": "https://tenki.jp/forecaster/deskpart/2026/10/23/41058.html"}, {"language": "ja", "published_at": "2026-10-23T03:18:55Z", "source_name": "sanin-chuo.co.jp", "title": "全般気象解説情報（線状降水帯半日前予測）（第１報）＝気象庁発表（２３日３時５８分） ：気象解説情報", "title_en": "General Weather Commentary (Half-day Advance Forecast of Linear Precipitation Bands) No.1 issued by JMA (23 Oct 03:58)", "url": "https://www.sanin-chuo.co.jp/articles/-/1102551"}, {"language": "ja", "published_at": "2026-10-24T01:38:39Z", "source_name": "NHK ニュース 主要", "title": "沖縄 石垣島地方に「線状降水帯直前予測」 気象庁発表", "title_en": "Okinawa: JMA issues ''Senjo Kosui-tai Chokuzen Yosoku'' (imminent linear rainband forecast) for Ishigaki Island area", "url": "https://news.web.nhk/newsweb/na/nd-20261024de64712"}], "summaries_original": {"ja": "気象庁は23日3時58分に線状降水帯半日前予測を発表し、沖縄県宮古島地方と八重山地方で23日昼過ぎから24日明け方にかけて線状降水帯が発生する可能性を示した。"}, "summary_en": "The Japan Meteorological Agency issued a half-day-ahead linear precipitation band forecast at 03:58 on 23 October 2026, indicating possible formation of a linear precipitation band over the Miyako and Yaeyama regions of Okinawa from midday on the 23rd to early morning on the 24th. The item, published by Japan Weather Association tenki.jp, relays this JMA advisory as a forecaster briefing. No impacts or outcomes are reported.", "title": "[Breaking] Okinawa Prefecture may see linear precipitation bands (senjō kōsuitai) from midday on the 23rd to early morning on the 24th (Weather forecaster duty chief, 23 October 2026) - Japan Weather Association tenki.jp", "wmo_regions": ["II"]}');
