INSERT INTO "stories" VALUES(163,'','other','2026-10-25T04:20:47Z','2026-10-27T04:09:49Z','2026-10-23','{"actions": ["Partial suspension of Area Mail (emergency alert) service for security response", "Suspension of ''Dokodemo Saigai/Hinan Joho'' disaster and evacuation information distribution", "Emergency maintenance carried out", "SoftBank suspended delivery of disaster and evacuation information from national and local governments for maintenance after a serious PHP vulnerability was found", "SoftBank resumed all emergency alert mail deliveries on the evening of 26 October"], "agencies": [{"country": "JP", "name": "NHK", "type": "media"}, {"country": "JP", "name": "NTT Docomo", "type": "other"}, {"country": "JP", "name": "SoftBank", "type": "other"}], "agency_types": ["media", "other"], "channels": ["cell_broadcast", "mobile_app"], "confidence": 0.85, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-23", "event_location": null, "event_name": null, "first_seen": "2026-10-25T04:11:37Z", "hazard": "other", "hazards": ["other"], "id": 163, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-27T04:09:49Z", "lead_time": null, "outcome": "mixed", "outcome_justification": "Disruption of cell-broadcast emergency alerts, including J-Alert and evacuation information, reduces warning dissemination capacity, though earthquake alerts continue.", "pillars": [3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-23T15:00:00Z", "source_name": "k-tai.watch.impress.co.jp", "title": "ドコモ 「 エリアメール 」 がPHP対応で一部停止 、 Jアラートや避難情報対象 ・ 地震速報は継続", "title_en": "NTT Docomo''s Area Mail partially suspended due to PHP support, affecting J-Alert and evacuation information; earthquake alerts continue", "url": "https://k-tai.watch.impress.co.jp/docs/news/2150887.html"}, {"language": "ja", "published_at": "2026-10-26T16:03:00Z", "source_name": "NHK ニュース 社会", "title": "ソフトバンク 緊急速報メールの配信すべて再開", "title_en": "SoftBank resumes all emergency alert mail deliveries", "url": "https://news.web.nhk/newsweb/na/nd-20261027de66055"}], "summaries_original": {"ja": "NTTドコモは10月23日、セキュリティ対応に伴い、緊急速報「エリアメール」の一部サービスおよび「どこでも災害・避難情報」の配信を停止し、緊急メンテナンスを実施していると発表した。"}, "summary_en": "NTT Docomo announced on 23 October that, due to a security response involving PHP support, parts of its Area Mail emergency alert service and the ''Dokodemo Saigai/Hinan Joho'' disaster and evacuation information distribution were suspended for emergency maintenance. Earthquake early alerts continue. The suspension affects delivery of J-Alert and evacuation information to mobile users.", "title": "NTT Docomo''s Area Mail partially suspended due to PHP support, affecting J-Alert and evacuation information; earthquake alerts continue", "wmo_regions": ["II"]}');
