er 26)", "outcome": "not_reported", "outcome_justification": "The snippet describes preparations and warnings but does not report outcomes such as casualties or evacuation results.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-25T04:11:51Z", "source_name": "vajiramandravi.com", "title": "Odisha Cyclone Alert 2026, Date, Name, Latest Update, Tracker", "title_en": "Odisha Cyclone Alert 2026, Date, Name, Latest Update, Tracker", "url": "https://vajiramandravi.com/current-affairs/odisha-cyclone/"}, {"language": "en", "published_at": "2026-10-25T05:30:00Z", "source_name": "timesofindia.indiatimes.com", "title": "Weather tomorrow: IMD forecasts rain, thunderstorms in 9 states; cyclone to hit Andhra and Odisha, Keralam under red alert", "title_en": "Weather tomorrow: IMD forecasts rain, thunderstorms in 9 states; cyclone to hit Andhra and Odisha, Keralam under red alert", "url": "https://timesofindia.indiatimes.com/city/delhi/weather-tomorrow-imd-forecasts-rain-thunderstorms-in-8-states-cyclone-to-hit-andhra-odisha-keralam-under-red-alert/articleshow/135183124.cms"}, {"language": "en", "published_at": "2026-10-25T09:30:00Z", "source_name": "livemint.com", "title": "Cyclone Arnab: Depression over Bay of Bengal to intensify; when and where will landfall occur? IMD latest updates", "title_en": "Cyclone Arnab: Depression over Bay of Bengal to intensify; when and where will landfall occur? IMD latest updates", "url": "https://www.livemint.com/news/india/cyclone-arnab-depression-over-bay-of-bengal-to-intensify-when-and-where-will-landfall-occur-imds-latest-updates-11792917730320.html"}, {"language": "en", "published_at": "2026-10-26T01:51:40Z", "source_name": "GDACS", "title": "Orange notification for tropical cyclone TWO-26. Population affected by Category 1 (120 km/h) wind speeds or higher is 0.356 million .", "title_en": "Orange notification for tropical cyclone TWO-26. Population affected by Category 1 (120 km/h) wind speeds or higher is 0.356 million.", "url": "http://www.gdacs.org/report.aspx?eventtype=TC&eventid=1001345"}, {"language": "en", "published_at": "2026-10-28T04:10:32Z", "source_name": "watchers.news", "title": "Very severe cyclone Arnab nears Andhra Pradesh–Yanam coast ahead of October 28 landfall, India - The Watchers", "title_en": "Very severe cyclone Arnab nears Andhra Pradesh–Yanam coast ahead of October 28 landfall, India", "url": "https://watchers.news/2026/10/27/very-severe-cyclone-arnab-nears-andhra-pradesh-yanam-coast-ahead-of-october-28-landfall-india"}, {"language": "en", "published_at": "2026-10-28T04:10:57Z", "source_name": "france24.com", "title": "India orders evacuations as Cyclone Arnab looms", "title_en": "India orders evacuations as Cyclone Arnab looms", "url": "https://france24.com/en/live-news/20261027-india-orders-evacuations-as-cyclone-arnab-looms"}], "summaries_original": {}, "summary_en": "The National Crisis Management Committee reviewed cyclone preparations on October 26, arranging shelters, evacuation measures, district control rooms and rescue teams ahead of Very Severe Cyclone Arnab''s expected landfall on October 28. IMD advised residents of vulnerable coastal housing to move to safer places, and the Coast Guard guided vessels to shore.", "title": "Very severe cyclone Arnab nears Andhra Pradesh–Yanam coast ahead of October 28 landfall, India", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(180,'other|PE|marcapomacocha','other','2026-10-27T04:20:57Z','2026-10-27T04:18:36Z','2026-10-27','{"actions": ["Participatory PICSA climate services workshop with farmers on decisions related to frost, snowfall and rainfall variability"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Ministerio del Ambiente", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other"], "confidence": 0.8, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-27", "event_location": "Marcapomacocha, Peru", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "other", "hazards": ["other"], "id": 180, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:36Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a capacity-building workshop on climate services; no warning outcomes are reported.", "pillars": [1, 2, 3], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "SENAMHI Perú noticias", "title": "SENAMHI desarrolla segundo taller PICSA en Marcapomacocha para fortalecer decisiones frente a heladas, nevadas y variabilidad de lluvias", "title_en": "SENAMHI develops second PICSA workshop in Marcapomacocha to strengthen decisions on frost, snowfall and rainfall variability", "url": "https://www.gob.pe/institucion/senamhi/noticias/1462533-senamhi-desarrolla-segundo-taller-picsa-en-marcapomacocha-para-fortalecer-decisiones-frente-a-heladas-nevadas-y-variabilidad-de-lluvias"}], "summaries_original": {"es": "El SENAMHI desarrolló el segundo taller participativo PICSA con comuneros de Marcapomacocha para fortalecer decisiones frente a heladas, nevadas y variabilidad de lluvias, bajo el enfoque de Servicios Climáticos Integrados y Participativos para la Agricultura."}, "summary_en": "SENAMHI held a second participatory PICSA (Integrated and Participatory Climate Services for Agriculture) workshop with community members in Marcapomacocha to strengthen decision-making against frost, snowfall and rainfall variability. The initiative focuses on translating climate information into actionable guidance for farmers. No specific warning event or outcome is described in the snippet.", "title": "SENAMHI develops second PICSA workshop in Marcapomacocha to strengthen decisions on frost, snowfall and rainfall variability", "wmo_regions": ["III"]}');
