INSERT INTO "stories" VALUES(186,'flood|CN|nepal and china border region','flood','2026-10-27T04:21:03Z','2026-10-27T04:08:01Z','2026-10-26','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [{"code": "CN", "name": "China"}, {"code": "NP", "name": "Nepal"}], "event_date": "2026-10-26", "event_location": "Nepal and China border region", "event_name": null, "first_seen": "2026-10-27T04:08:01Z", "hazard": "flood", "hazards": ["flood"], "id": 186, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-27T04:08:01Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet discusses using AI for flood anticipation and cross-border warnings but reports no specific warning outcome.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-26T12:07:43Z", "source_name": "PreventionWeb", "title": "Can AI save lives before the next flood?", "title_en": "Can AI save lives before the next flood?", "url": "https://www.preventionweb.net/news/can-ai-save-lives-next-flood"}], "summaries_original": {}, "summary_en": "An opinion piece on PreventionWeb uses a Nepal–China flood to argue that AI should be applied now to anticipate floods and accelerate cross-border early warnings. It emphasises protecting lives in the near term rather than focusing only on future threats. No specific warnings or outcomes are described in the snippet.", "title": "Can AI save lives before the next flood?", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(187,'flood|PE|ayabaca','heavy_rain','2026-10-27T04:21:05Z','2026-10-27T04:18:51Z','2026-10-26','{"actions": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "Defensoría del Pueblo", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": [], "confidence": 0.8, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-26", "event_location": "Ayabaca, Piura, Peru", "event_name": null, "first_seen": "2026-10-27T04:18:51Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 187, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:51Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports flooding of homes and Senamhi forecasts of up to 40 mm/day, but does not state whether warnings were received or acted upon.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-10-26T17:03:56Z", "source_name": "La República (Perú) sociedad", "title": "Fuertes lluvias en Piura inundan viviendas en Ayabaca: Senamhi alerta por precipitaciones intensas en el norte del país", "title_en": "Heavy rains in Piura flood homes in Ayabaca: Senamhi warns of intense precipitation in northern Peru", "url": "https://larepublica.pe/sociedad/2026/10/26/fuertes-lluvias-en-piura-inundan-viviendas-en-ayabaca-senamhi-alerta-por-precipitaciones-intensas-en-el-norte-del-pais-1491022"}], "summaries_original": {"es": "Las lluvias del domingo afectaron 15 viviendas en Ayabaca y Senamhi prevé hasta 40 mm diarios en la costa norte, además de descargas eléctricas y ráfagas de viento."}, "summary_en": "Rainfall on Sunday flooded 15 homes in Ayabaca, Piura, according to the Ombudsman''s office, carrying mud through streets and shops. Senamhi forecasts accumulations of up to 40 mm per day on the northern coast, along with electrical discharges and gusts near 40 km/h.", "title": "Heavy rains in Piura flood homes in Ayabaca: Senamhi warns of intense precipitation in northern Peru", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(188,'flood|CL|las condes','flash_flood','2026-10-27T04:21:05Z','2026-10-27T04:18:52Z','2026-10-27','{"actions": ["Residents advised to stay in place (SAE alert sent to mobile phones at 22:04)", "Red Alert declared in 10 precordillera communes of the Metropolitan Region"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["cell_broadcast"], "confidence": 0.95, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-27", "event_location": "Las Condes, Región Metropolitana, Chile", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "flash_flood", "hazards": ["flash_flood"], "id": 188, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:52Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports the alert being issued and sent to phones but does not describe its effects or any impacts.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T01:12:40Z", "source_name": "BioBioChile nacional", "title": "Senapred activa nuevamente alerta SAE por repentino desborde de Quebrada Honda en Las Condes", "title_en": "Senapred activates SAE alert again due to sudden overflow of Quebrada Honda in Las Condes", "url": "https://www.biobiochile.cl/noticias/nacional/chile/2026/10/26/senapred-activa-nuevamente-alerta-sae-por-repentino-desborde-de-quebrada-honda-en-las-condes.shtml"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "elmostrador.cl", "title": "Senapred declara Alerta Roja en 10 comunas de la RM por riesgo de aluviones tras intensas lluvias", "title_en": "Senapred declares Red Alert in 10 communes of the Metropolitan Region due to risk of debris flows after intense rains", "url": "https://elmostrador.cl/noticias/pais/2026/10/26/senapred-declara-alerta-roja-en-10-comunas-de-la-rm-por-riesgo-de-aluviones-tras-intensas-lluvias"}], "summaries_original": {"es": "Senapred activó nuevamente una alerta SAE por el desborde de Quebrada Honda, en la comuna de Las Condes, en medio de intensas lluvias en la capital. La advertencia fue enviada a los celulares a las 22:04 horas, llamando a los vecinos a mantenerse en lugares seguros."}, "summary_en": "Senapred issued a SAE emergency alert to mobile phones at 22:04 local time after the Quebrada Honda overflowed suddenly in Las Condes amid intense rain in Santiago. The alert called on residents to remain in safe locations. This is a repeat activation of the alert for the same ravine.", "title": "Senapred activates SAE alert again due to sudden overflow of Quebrada Honda in Las Condes", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(189,'flood|PE|kimbiri','flood','2026-10-27T04:21:06Z','2026-10-27T04:18:51Z','2026-10-27','{"actions": ["Emergency evacuation of residents initiated by authorities"], "agencies": [{"country": "PE", "name": "Local authorities", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.6, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-27", "event_location": "Kimbiri, Cusco, Peru", "event_name": null, "first_seen": "2026-10-27T04:18:51Z", "hazard": "flood", "hazards": ["flood"], "id": 189, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:51Z", "lead_time": null, "outcome": "negative", "outcome_justification": "The event caught residents by surprise and some people were reportedly trapped in the river, suggesting no effective advance warning was given.", "pillars": [4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T03:00:17Z", "source_name": "La República (Perú) sociedad", "title": "Cusco: desborde del río Kimbiri arrasa viviendas en el VRAEM y obliga a evacuar a pobladores", "title_en": "Cusco: Kimbiri river overflow sweeps away homes in the VRAEM and forces residents to evacuate", "url": "https://larepublica.pe/sociedad/2026/10/26/cusco-desborde-del-rio-kimbiri-arrasa-viviendas-en-el-vraem-y-obliga-a-evacuar-a-pobladores-1288378"}], "summaries_original": {"es": "Un desborde del río Kimbiri en el VRAEM, Cusco, arrasó viviendas y obligó a las autoridades a evacuar de emergencia a los pobladores; algunas personas habrían quedado atrapadas en el río, y el evento tomó por sorpresa a la población."}, "summary_en": "A sudden overflow of the Kimbiri river in the VRAEM area of Cusco, Peru, swept away homes and forced authorities to launch an emergency evacuation. Residents were reportedly taken by surprise and some people may have been trapped in the river, indicating that advance warning was limited or absent.", "title": "Cusco: Kimbiri river overflow sweeps away homes in the VRAEM and forces residents to evacuate", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(190,'severe_storm|CL|region metropolitana','severe_storm','2026-10-27T04:21:08Z','2026-10-27T04:18:36Z','2026-10-27','{"actions": ["Declaration of Early Preventive Alert (Alerta Temprana Preventiva) for the Metropolitan Region"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["other"], "confidence": 0.95, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-27", "event_location": "Región Metropolitana, Chile", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 190, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:36Z", "lead_time": "from Monday afternoon until conditions warrant; issued 26 October 2026 for Monday 27 October", "outcome": "not_reported", "outcome_justification": "The item reports only the issuance of the alert; no outcomes of the event are described.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "biobiochile.cl", "title": "Decretan Alerta Temprana Preventiva en la RM por pronóstico de lluvia, tormenta eléctrica y granizos", "title_en": "Early Preventive Alert declared in the Metropolitan Region due to forecast rain, thunderstorms and hail", "url": "https://www.biobiochile.cl/noticias/nacional/region-metropolitana/2026/10/26/decretan-alerta-temprana-preventiva-en-la-rm-por-pronostico-de-lluvia-tormenta-electrica-y-granizos.shtml"}], "summaries_original": {"es": "Senapred declaró Alerta Temprana Preventiva para la Región Metropolitana ante el pronóstico de lluvias normales a moderadas, tormentas eléctricas y posibles granizos para la tarde del lunes. El aviso rige desde ese día hasta que las condiciones lo ameriten."}, "summary_en": "Chile''s national emergency agency Senapred declared an Early Preventive Alert for the Metropolitan Region ahead of forecast normal to moderate rain, electrical storms and possible hail on Monday afternoon. The alert remains in force until conditions warrant it being lifted.", "title": "Early Preventive Alert declared in the Metropolitan Region due to forecast rain, thunderstorms and hail", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(191,'flood|PE|peru (northern coast and highlands)','heavy_rain','2026-10-27T04:21:11Z','2026-10-28T04:16:03Z','2026-10-27','{"actions": ["Indeci warned of possible huaicos and landslides and called for reinforced preventive measures", "Senamhi issued red-level meteorological warning No. 440 for heavy to extreme rainfall", "Indeci recommended reinforcing house roofs and establishing early warning mechanisms with local authorities", "Indeci recommended authorities verify evacuation routes and emergency services", "National authorities urged regional and local governments to adopt measures to ensure population safety", "SENAMHI maintained red-level Meteorological Warning No. 440 for precipitation on the northern coast and highlands, valid until Thursday 29 October 2026"], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}, {"country": "PE", "name": "Indeci", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other", "website"], "confidence": 0.97, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-27", "event_location": "Peru", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 191, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-28T04:16:03Z", "lead_time": "period 27-29 October 2026", "outcome": "negative", "outcome_justification": "The item reports the issuance of a red alert and warnings but no observed outcomes of the warnings.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:15:55Z", "source_name": "wapa.pe", "title": "Senamhi activa ALERTA ROJA por lluvias intensas: estas 11 regiones serán afectadas hasta el 29 de octubre", "title_en": "Senamhi activates RED ALERT for intense rain: these 11 regions will be affected until October 29", "url": "https://wapa.pe/ocio/2026/10/26/senamhi-activa-alerta-roja-lluvias-intensas-11-regiones-seran-afectadas-29-octubre-911742"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "infobae.com", "title": "El Senamhi emite una alerta roja por lluvias intensas en 11 departamentos del Perú entre el 27 y 29 de octubre - Infobae", "title_en": "Senamhi issues red alert for heavy rains in 11 departments of Peru between 27 and 29 October", "url": "https://www.infobae.com/peru/2026/10/26/el-senamhi-emite-una-alerta-roja-por-lluvias-intensas-en-11-departamentos-del-peru-entre-el-27-y-29-de-octubre/"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "larepublica.pe", "title": "Alerta roja del Senamhi en 11 departamentos: pronostican lluvias de extrema intensidad, granizo y nevadas hasta el 29 de octubre", "title_en": "Senamhi red alert in 11 departments: extreme-intensity rain, hail and snowfall forecast until 29 October", "url": "https://larepublica.pe/sociedad/2026/10/26/alerta-roja-del-senamhi-en-11-departamentos-pronostican-lluvias-de-extrema-intensidad-granizo-y-nevadas-hasta-el-29-de-octubre-322478"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "elcomercio.pe", "title": "Estos 11 departamentos del Perú serán afectados por fuertes lluvias entre el 27 y 29 de octubre del 2026: Senamhi ya lanzó la alerta roja", "title_en": "These 11 departments of Peru will be affected by heavy rains between October 27 and 29, 2026: Senamhi has already issued the red alert", "url": "https://elcomercio.pe/respuestas/que/estos-11-departamentos-del-peru-seran-afectados-por-fuertes-lluvias-entre-el-27-y-29-de-octubre-del-2026-senamhi-ya-lanzo-la-alerta-roja-tdpe-noticia/"}, {"language": "es", "published_at": "2026-10-28T04:15:55Z", "source_name": "buenapepa.pe", "title": "Alerta roja por lluvias en Tumbes y Piura: ¿hasta cuándo durará y con qué intensidad lloverá?", "title_en": "Red alert for rain in Tumbes and Piura: how long will it last and how intense will the rain be?", "url": "https://buenapepa.pe/senamhi-alerta-roja-lluvias-tumbes-piura/"}], "summaries_original": {"es": "El Senamhi activó alerta roja por lluvias intensas en 11 regiones para el periodo del 27 al 29 de octubre, con posible granizo, nevadas y fuertes vientos. El Indeci advirtió sobre posibles huaicos y deslizamientos y pidió reforzar medidas preventivas."}, "summary_en": "Peru''s national meteorological service Senamhi activated a red alert for intense rainfall in 11 regions for 27-29 October 2026, with possible hail, snowfall and strong winds. The civil protection agency Indeci warned of possible flash floods (huaicos) and landslides and urged reinforced preventive measures.", "title": "Senamhi activates RED ALERT for intense rain: these 11 regions will be affected until October 29", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(192,'flood|CL|metropolitan region','heavy_rain','2026-10-27T04:21:15Z','2026-10-28T04:16:03Z','2026-10-27','{"actions": ["Red alert issued for ten communes for risk of mass movements", "Class suspension in Las Condes", "Evacuation of 25 people in San Carlos de Apoquindo", "Evacuation of 16 people in Lo Barnechea", "Declaration of preventive early alert for the Metropolitan Region in response to two active DMC warnings", "Activation of Sinapred to reinforce surveillance and act in a timely manner"], "agencies": [{"country": "CL", "name": "Dirección Meteorológica de Chile", "type": "NMHS"}, {"country": "CL", "name": "Government of Chile (Metropolitan Region authorities)", "type": "other_national_agency"}, {"country": "CL", "name": "Senapred", "type": "other_national_agency"}, {"country": "CL", "name": "Sinapred", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["website"], "confidence": 0.9, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-27", "event_location": "Metropolitan Region, Chile", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 192, "impacts": {"evacuated": 41}, "languages": ["es"], "last_updated": "2026-10-28T04:16:03Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports alerts and evacuations but does not state whether the warnings were timely or effective.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:15:55Z", "source_name": "latercera.com", "title": "Minuto a minuto: sigue el avance de las lluvias en la zona oriente de la RM - La Tercera", "title_en": "Live blog: follow the rainfall progress in the eastern zone of the Metropolitan Region", "url": "https://www.latercera.com/nacional/noticia/minuto-a-minuto-se-activa-quebrada-honda-en-las-condes-por-fuertes-lluvias-en-zona-oriente/"}, {"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "radio.uchile.cl", "title": "Por lluvias y posibles tormentas eléctricas: Senapred declara alerta temprana preventiva para la RM - Diario y Radio Universidad Chile", "title_en": "Due to rain and possible thunderstorms: Senapred declares preventive early alert for the Metropolitan Region", "url": "https://radio.uchile.cl/2026/10/26/por-lluvias-y-posibles-tormentas-electricas-senapred-declara-alerta-temprana-preventiva-para-la-rm/"}], "summaries_original": {"es": "Diez comunas de la Región Metropolitana están con alerta roja por riesgo de remociones en masa, con suspensión de clases en Las Condes y evacuaciones en San Carlos de Apoquindo y Lo Barnechea."}, "summary_en": "A live news blog reports that ten communes in the Metropolitan Region of Santiago are under red alert for the risk of mass movements due to heavy rain. Authorities suspended classes in Las Condes and evacuated 25 people in San Carlos de Apoquindo and 16 in Lo Barnechea. The snippet does not describe how the warnings were disseminated or their lead time.", "title": "Live blog: follow the rainfall progress in the eastern zone of the Metropolitan Region", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(193,'multi_hazard|GR|attica and rhodes','multi_hazard','2026-10-27T04:21:15Z','2026-10-27T04:18:36Z','2026-10-27','{"actions": ["Civil protection issued a reinforced alert in Attica and Rhodes until 29 October", "EMY raised the alert level to red and extended the warning until 28 October in several regions"], "agencies": [{"country": "GR", "name": "EMY (Hellenic National Meteorological Service)", "type": "NMHS"}, {"country": "GR", "name": "Civil Protection (Attica and Rhodes authorities)", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other"], "confidence": 0.95, "countries": [{"code": "GR", "name": "Greece"}], "event_date": "2026-10-27", "event_location": "Attica and Rhodes, Greece", "event_name": null, "first_seen": "2026-10-27T04:18:36Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 193, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-27T04:18:36Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports warnings and alert levels issued but gives no information on outcomes, impacts or how the warnings were received.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:18:28Z", "source_name": "es.rua.gr", "title": "Grecia bajo la influencia del mal tiempo: las lluvias durarán hasta el 28 de octubre, donde será más peligroso - Noticias de Atenas", "title_en": "Greece under the influence of bad weather: rains will last until 28 October, where it will be most dangerous", "url": "https://es.rua.gr/2026/10/26/grecia-bajo-la-influencia-del-mal-tiempo-las-lluvias-duraran-hasta-el-28-de-octubre-donde-sera-mas-peligroso/"}], "summaries_original": {"es": "Las autoridades de Ática y Rodas anunciaron una alerta reforzada de protección civil hasta el 29 de octubre. El EMY elevó el nivel de alerta a rojo y amplió el aviso hasta el 28 de octubre en varias regiones griegas."}, "summary_en": "Greek civil protection authorities in Attica and Rhodes announced a reinforced alert until 29 October, and EMY raised its alert level to red, extending the warning to 28 October in several regions. The item concerns forecast-based warnings of prolonged bad weather, with no outcome reported in the snippet.", "title": "Greece under the influence of bad weather: rains will last until 28 October, where it will be most dangerous", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(194,'','heatwave','2026-10-28T04:18:05Z','2026-10-28T04:11:02Z','2026-10-28','{"actions": ["Public engagement with weather warnings and advice assessed through new research"], "agencies": [{"country": "GB", "name": "Met Office", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": [], "confidence": 0.85, "countries": [{"code": "GB", "name": "United Kingdom"}], "event_date": "2026-10-28", "event_location": null, "event_name": null, "first_seen": "2026-10-28T04:11:02Z", "hazard": "heatwave", "hazards": ["heatwave"], "id": 194, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:11:02Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports survey findings on how engaged 18-24-year-olds are with weather warnings after a record summer heat period, but does not describe specific warning outcomes.", "pillars": [3], "review": false, "sources": [{"language": "en", "published_at": null, "source_name": "UK Met Office news", "title": "Young people most likely to act on weather warnings after record summer Following this summer''s extreme heat, new Met Office research suggests 18-24-year-olds are among the most engaged age group when it comes to following weather warnings and advice. Read more", "title_en": "Young people most likely to act on weather warnings after record summer", "url": "https://www.metoffice.gov.uk/about-us/news-and-media/media-centre/weather-and-climate-news/2026/young-people-most-likely-to-act-on-weather-warnings-after-record-summer-"}], "summaries_original": {}, "summary_en": "The UK Met Office reports new research indicating that 18-24-year-olds are among the most engaged age groups in following weather warnings and advice after an extreme summer heat period. The finding concerns warning uptake and communication effectiveness, which is central to early warning dissemination.", "title": "Young people most likely to act on weather warnings after record summer", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(195,'','other','2026-10-28T04:18:06Z','2026-10-28T04:11:05Z','2026-10-28','{"actions": [], "agencies": [{"country": "PH", "name": "PAGASA", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": ["website"], "confidence": 0.6, "countries": [{"code": "PH", "name": "Philippines"}], "event_date": "2026-10-28", "event_location": "Philippines", "event_name": null, "first_seen": "2026-10-28T04:11:05Z", "hazard": "other", "hazards": ["other"], "id": 195, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:11:05Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "Only the title is available; the press release is a PAGASA monitoring/advisory announcement on seasonal monsoon onset with no reported impacts or actions.", "pillars": [2], "review": false, "sources": [{"language": "en", "published_at": null, "source_name": "PAGASA press releases", "title": "ONSET OF THE NORTHEAST MONSOON", "title_en": "Onset of the Northeast Monsoon", "url": "https://pagasa.dost.gov.ph/press-release/230"}], "summaries_original": {}, "summary_en": "PAGASA, the Philippine NMHS, issued a press release announcing the onset of the Northeast Monsoon, a seasonal climate-monitoring and forecasting update. Only the title is available, so no details on hazards, warnings, or outcomes can be confirmed.", "title": "Onset of the Northeast Monsoon", "wmo_regions": ["II", "V"]}');
INSERT INTO "stories" VALUES(196,'cold_wave|PE|peruvian amazon jungle (selva)','cold_wave','2026-10-28T04:18:06Z','2026-10-29T04:17:03Z','2026-10-28','{"actions": ["INDECI recommends preparedness measures in response to SENAMHI Aviso N.° 442"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "INDECI", "type": "other_national_agency"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other", "website"], "confidence": 0.93, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-28", "event_location": "Southern jungle (selva sur), Peru", "event_name": null, "first_seen": "2026-10-28T04:16:03Z", "hazard": "cold_wave", "hazards": ["cold_wave"], "id": 196, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-29T04:17:03Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a warning and recommended preparedness measures but reports no outcomes.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "SENAMHI Perú noticias", "title": "SENAMHI pronostica lluvias y descenso de temperaturas por décimo cuarto friaje en la selva", "title_en": "SENAMHI forecasts rain and temperature drop due to the fourteenth friaje in the Peruvian jungle", "url": "https://www.gob.pe/institucion/senamhi/noticias/1463550-senamhi-pronostica-lluvias-y-descenso-de-temperaturas-por-decimo-cuarto-friaje-en-la-selva"}, {"language": "es", "published_at": null, "source_name": "INDECI Perú noticias", "title": "INDECI recomienda medidas de preparación ante el descenso de la temperatura diurna en la selva sur – décimo cuarto friaje", "title_en": "INDECI recommends preparedness measures for daytime temperature drop in southern jungle – fourteenth friaje", "url": "https://www.gob.pe/institucion/indeci/noticias/1464756-indeci-recomienda-medidas-de-preparacion-ante-el-descenso-de-la-temperatura-diurna-en-la-selva-sur-decimo-cuarto-friaje"}], "summaries_original": {"es": "INDECI recomienda adoptar medidas de preparación ante el Aviso N.° 442 del SENAMHI, que informa sobre el descenso de la temperatura diurna en la selva, de moderada a fuerte intensidad, asociado al décimo cuarto friaje."}, "summary_en": "INDECI, Peru''s civil defence institute, recommends preparedness measures following SENAMHI Aviso N.° 442, which warns of moderate to strong daytime temperature drops in the southern jungle associated with the fourteenth friaje (cold surge) of the season. The notice is a government press release on an official SENAMHI warning and its follow-up advice.", "title": "INDECI recommends preparedness measures for daytime temperature drop in southern jungle – fourteenth friaje", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(197,'landslide|CL|metropolitan region','landslide','2026-10-28T04:18:10Z','2026-10-28T04:16:03Z','2026-10-27','{"actions": ["Red Alert declared for mass movement in 10 pre-Andean communes including San José de Maipo, Puente Alto, Las Condes and Colina"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.9, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-10-27", "event_location": "Metropolitan Region, Chile", "event_name": null, "first_seen": "2026-10-28T04:16:03Z", "hazard": "landslide", "hazards": ["landslide"], "id": 197, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-28T04:16:03Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports the alert declaration but gives no information on outcomes or impacts.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-10-27T04:15:55Z", "source_name": "biobiochile.cl", "title": "Senapred declara Alerta Roja en 10 comunas precordilleranas de la RM por remoción en masa tras lluvias", "title_en": "Senapred declares Red Alert in 10 pre-Andean communes of the Metropolitan Region due to mass movement after rains", "url": "https://www.biobiochile.cl/noticias/nacional/region-metropolitana/2026/10/26/senapred-declara-alerta-roja-en-10-comunas-precordilleranas-de-la-rm-por-remocion-en-masa-tras-lluvias.shtml"}], "summaries_original": {"es": "Senapred declaró Alerta Roja por remoción en masa en 10 comunas precordilleranas de la Región Metropolitana debido al intenso sistema frontal, abarcando comunas como San José de Maipo, Puente Alto, Las Condes y Colina."}, "summary_en": "Chile''s national emergency agency Senapred declared a Red Alert for mass movement (landslide) risk in 10 pre-Andean communes of the Metropolitan Region following an intense frontal system. The alert covers communes including San José de Maipo, Puente Alto, Las Condes and Colina. The snippet does not report channels, lead time or impacts.", "title": "Senapred declares Red Alert in 10 pre-Andean communes of the Metropolitan Region due to mass movement after rains", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(198,'','tropical_cyclone','2026-10-28T04:18:12Z','2026-10-28T04:06:53Z','2026-10-27','{"actions": [], "agencies": [{"country": null, "name": "Directorate-General for European Civil Protection and Humanitarian Aid Operations (DG ECHO)", "type": "international"}], "agency_types": ["international"], "channels": [], "confidence": 0.2, "countries": [{"code": "PH", "name": "Philippines"}, {"code": "VN", "name": "Viet Nam"}], "event_date": "2026-10-27", "event_location": null, "event_name": null, "first_seen": "2026-10-28T04:06:53Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 198, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:06:53Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a risk analysis report commissioned to inform preparedness and anticipatory action frameworks, with no specific warnings, forecasts or outcomes reported.", "pillars": [], "review": true, "sources": [{"language": "en", "published_at": "2026-10-27T13:52:41Z", "source_name": "PreventionWeb", "title": "Tropical cyclone risk evolution in the Philippines and Vietnam", "title_en": "Tropical cyclone risk evolution in the Philippines and Vietnam", "url": "https://www.preventionweb.net/publication/documents-and-publications/tropical-cyclone-risk-evolution-philippines-and-vietnam"}], "summaries_original": {}, "summary_en": "A report commissioned by DG ECHO analyses the evolution of tropical cyclone risk in the Philippines and Vietnam to inform preparedness and anticipatory action frameworks. The snippet does not describe monitoring, warnings, or dissemination of early warnings during a specific event, so its relevance to early warning service delivery is limited.", "title": "Tropical cyclone risk evolution in the Philippines and Vietnam", "wmo_regions": ["II", "V"]}');
INSERT INTO "stories" VALUES(199,'','tsunami','2026-10-28T04:18:13Z','2026-10-28T04:06:53Z','2026-10-27','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [], "event_date": "2026-10-27", "event_location": null, "event_name": null, "first_seen": "2026-10-28T04:06:53Z", "hazard": "tsunami", "hazards": ["tsunami"], "id": 199, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:06:53Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports a research study on evacuation route safety and timing after earthquakes, without describing any actual warning event or its outcome.", "pillars": [1, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-27T14:06:19Z", "source_name": "PreventionWeb", "title": "A low-cost tool can help people plan successful evacuation routes during a tsunami", "title_en": "A low-cost tool can help people plan successful evacuation routes during a tsunami", "url": "https://www.preventionweb.net/news/low-cost-tool-can-help-people-plan-successful-evacuation-routes-during-tsunami"}], "summaries_original": {}, "summary_en": "Researchers Alejandra Gubler and Matías Carvajal published a study in Seismological Research Letters showing that evacuation route safety during a tsunami depends strongly on how quickly people start evacuating after an earthquake. The work proposes a low-cost tool to help people plan safer evacuation routes. The item focuses on evacuation planning as a preparedness measure rather than on a specific warning event.", "title": "A low-cost tool can help people plan successful evacuation routes during a tsunami", "wmo_regions": []}');
INSERT INTO "stories" VALUES(200,'drought|XX|southern africa','drought','2026-10-28T04:18:14Z','2026-10-28T04:06:53Z','2026-10-27','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.6, "countries": [], "event_date": "2026-10-27", "event_location": "Southern Africa", "event_name": null, "first_seen": "2026-10-28T04:06:53Z", "hazard": "drought", "hazards": ["drought"], "id": 200, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:06:53Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes drought impacts on livestock and suggests improved weather forecasts with targeted support could help, but reports no specific warning issued or outcome.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-27T15:27:12Z", "source_name": "PreventionWeb", "title": "Drought forces livestock farmers to make tough decisions: our model shows the impact on inequality", "title_en": "Drought forces livestock farmers to make tough decisions: our model shows the impact on inequality", "url": "https://www.preventionweb.net/news/drought-forces-livestock-farmers-make-tough-decisions-our-model-shows-impact-inequality"}], "summaries_original": {}, "summary_en": "Drought threatens livestock and livelihoods in southern Africa and worsens inequality among pastoralist communities. The study argues that improved weather forecasts combined with targeted support could help these communities adapt and reduce impacts.", "title": "Drought forces livestock farmers to make tough decisions: our model shows the impact on inequality", "wmo_regions": ["I"]}');
INSERT INTO "stories" VALUES(201,'severe_storm|JP|northern japan','severe_storm','2026-10-28T04:18:14Z','2026-10-28T04:11:13Z','2026-10-28','{"actions": ["JMA announced the ''Kogarashi 1'' (first winter wind) observation for Tokyo and Kinki at 11:00", "Strong wind alerts issued for northern Japan"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": ["other"], "confidence": 0.8, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-28", "event_location": "Northern Japan, Japan", "event_name": null, "first_seen": "2026-10-28T04:11:13Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 201, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-28T04:11:13Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports warnings and observations but no outcomes or impacts from the event.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-28T03:03:00Z", "source_name": "NHK ニュース 主要", "title": "冬型気圧配置 初雪や「木枯らし1号」も 北日本は暴風など警戒", "title_en": "Winter pressure pattern brings first snow and ''first north wind of winter'' (Kogarashi 1); strong winds warned in northern Japan", "url": "https://news.web.nhk/newsweb/na/nd-20261028de66726"}], "summaries_original": {"ja": "冬型の気圧配置と上空の寒気の影響で北日本を中心に雪が降り、札幌市や青森市などで初雪が観測された。気象庁は東京と近畿で「木枯らし1号」を発表し、北日本では暴風への警戒が呼びかけられた。"}, "summary_en": "A winter pressure pattern and upper-level cold air brought snow and first-snow observations to northern Japan, including Sapporo and Aomori. JMA announced the ''Kogarashi 1'' winter wind observation for Tokyo and Kinki, and strong wind warnings were issued for northern Japan.", "title": "Winter pressure pattern brings first snow and ''first north wind of winter'' (Kogarashi 1); strong winds warned in northern Japan", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(202,'earthquake|PH|sarangani','earthquake','2026-10-28T04:18:17Z','2026-10-28T04:11:13Z','2026-10-28','{"actions": ["Suspension of face-to-face classes at all levels across Sarangani province", "Suspension of government office work across Sarangani province", "Post-earthquake safety assessments ordered"], "agencies": [{"country": "PH", "name": "Sarangani Provincial Information Office", "type": "other_national_agency"}, {"country": "PH", "name": "Sarangani provincial government", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["social_media"], "confidence": 0.6, "countries": [{"code": "PH", "name": "Philippines"}], "event_date": "2026-10-28", "event_location": "Sarangani, Philippines", "event_name": null, "first_seen": "2026-10-28T04:11:13Z", "hazard": "earthquake", "hazards": ["earthquake"], "id": 202, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-28T04:11:13Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports protective actions after the quake but gives no information on whether warnings or advisories preceded it or on resulting impacts.", "pillars": [3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-28T09:59:09Z", "source_name": "Philippine Daily Inquirer", "title": "Sarangani suspends classes, gov’t work after magnitude 5.5 quake", "title_en": "Sarangani suspends classes, gov''t work after magnitude 5.5 quake", "url": "https://newsinfo.inquirer.net/2331477/sarangani-suspends-classes-govt-work-after-magnitude-5-5-quake"}], "summaries_original": {}, "summary_en": "After a magnitude 5.5 earthquake struck Sarangani province around 7:43 a.m., the provincial government suspended classes and government work via a social media advisory to allow post-earthquake safety inspections. The item documents a post-event response advisory disseminated through social media, but does not describe monitoring, pre-event warnings or impacts.", "title": "Sarangani suspends classes, gov''t work after magnitude 5.5 quake", "wmo_regions": ["II", "V"]}');
