INSERT INTO "stories" VALUES(210,'','multi_hazard','2026-10-29T04:18:45Z','2026-10-29T04:10:16Z','2026-10-28','{"actions": ["Young adults prepare for and take action on upcoming severe weather warnings"], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.8, "countries": [], "event_date": "2026-10-28", "event_location": null, "event_name": null, "first_seen": "2026-10-29T04:10:16Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 210, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-29T04:10:16Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports that younger adults are more likely to act on warnings, but gives no outcome data on lives saved or losses reduced.", "pillars": [3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-28T13:54:23Z", "source_name": "PreventionWeb", "title": "Young people most likely to act on weather warnings after record summer", "title_en": "Young people most likely to act on weather warnings after record summer", "url": "https://www.preventionweb.net/news/young-people-most-likely-act-weather-warnings-after-record-summer"}], "summaries_original": {}, "summary_en": "A PreventionWeb article reports that young adults are more likely than any other generation to take action and prepare for upcoming severe weather, following a record summer. The finding relates to how people respond to weather warnings, which bears on the warning dissemination and preparedness pillars of Early Warnings for All. The snippet does not specify the survey, countries or hazard events involved.", "title": "Young people most likely to act on weather warnings after record summer", "wmo_regions": []}');
INSERT INTO "stories" VALUES(211,'','tsunami','2026-10-29T04:18:47Z','2026-10-31T04:07:58Z','2026-10-28','{"actions": [], "agencies": [{"country": null, "name": "UNDRR", "type": "international"}], "agency_types": ["international"], "channels": [], "confidence": 0.85, "countries": [], "event_date": "2026-10-28", "event_location": null, "event_name": null, "first_seen": "2026-10-29T04:10:16Z", "hazard": "tsunami", "hazards": ["tsunami"], "id": 211, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-31T04:07:58Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes tsunami readiness examples and the role of warnings and immediate public action, but does not report a specific warning outcome.", "pillars": [1, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-28T14:09:48Z", "source_name": "PreventionWeb", "title": "Nine examples of tsunami readiness – turning warnings into life-saving action", "title_en": "Nine examples of tsunami readiness – turning warnings into life-saving action", "url": "https://www.preventionweb.net/news/nine-examples-tsunami-readiness-turning-warnings-life-saving-action"}, {"language": "en", "published_at": "2026-10-30T08:08:02Z", "source_name": "UNDRR news", "title": "Let’s take charge of resilience. By working together we can be tsunami ready says UN Secretary-General António Guterres", "title_en": "Let''s take charge of resilience. By working together we can be tsunami ready says UN Secretary-General António Guterres", "url": "https://www.undrr.org/news/lets-take-charge-resilience-working-together-we-can-be-tsunami-ready-says-un-secretary-general"}], "summaries_original": {}, "summary_en": "The article presents nine examples of tsunami readiness, focusing on how communities and warning systems turn alerts into life-saving action. It notes that tsunamis can reach coasts within minutes of an earthquake, sometimes before any official alert, so pre-existing knowledge and immediate responses are critical. The emphasis is on linking warnings to preparedness and response.", "title": "Nine examples of tsunami readiness – turning warnings into life-saving action", "wmo_regions": []}');
