INSERT INTO "stories" VALUES(213,'multi_hazard|NP|bhote koshi–trishuli river corridor','multi_hazard','2026-10-29T04:18:48Z','2026-10-29T04:10:16Z','2026-10-28','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.85, "countries": [{"code": "NP", "name": "Nepal"}], "event_date": "2026-10-28", "event_location": "Bhote Koshi–Trishuli River Corridor, Nepal", "event_name": null, "first_seen": "2026-10-29T04:10:16Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 213, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-29T04:10:16Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes reconstruction and evaluation of the early warning system but does not report whether warnings were issued or what outcomes resulted.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-28T14:11:46Z", "source_name": "PreventionWeb", "title": "Cascading ice–rock avalanche multi-hazard early warning in the Bhote Koshi–Trishuli River Corridor", "title_en": "Cascading ice–rock avalanche multi-hazard early warning in the Bhote Koshi–Trishuli River Corridor", "url": "https://www.preventionweb.net/publication/documents-and-publications/cascading-ice-rock-avalanche-multi-hazard-early-warning"}], "summaries_original": {}, "summary_en": "This publication reconstructs the 26 August 2026 cascading ice–rock avalanche in the Bhote Koshi–Trishuli corridor in Nepal and analyses its downstream propagation. It evaluates elements of the existing early warning system and proposes a two-stage framework for hazard detection and emergency response in mountain river corridors.", "title": "Cascading ice–rock avalanche multi-hazard early warning in the Bhote Koshi–Trishuli River Corridor", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(214,'earthquake|JP|northeastern chiba prefecture','earthquake','2026-10-29T04:18:49Z','2026-10-29T04:11:24Z','2026-10-28','{"actions": [], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["other"], "confidence": 0.9, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-28", "event_location": "Northeastern Chiba Prefecture, Japan", "event_name": null, "first_seen": "2026-10-29T04:11:24Z", "hazard": "earthquake", "hazards": ["earthquake"], "id": 214, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-29T04:11:24Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item is an official JMA press release about an earthquake and its associated information; no outcomes of the warnings or advisories are reported in the available text.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-28T15:00:00Z", "source_name": "気象庁 (JMA)", "title": "令和８年10月29日00時07分頃の千葉県北東部の地震について", "title_en": "About the earthquake in northeastern Chiba Prefecture around 00:07 on October 29, 2026 (Reiwa 8)", "url": "https://www.jma.go.jp/jma/press/2610/29a/202610290210.html"}], "summaries_original": {"ja": "気象庁が2026年10月29日00時07分頃に発生した千葉県北東部の地震について発表した報道発表。地震情報の発表に関するもので、詳細な内容は本文が不明のため判断できない。"}, "summary_en": "The Japan Meteorological Agency issued a press release concerning an earthquake in northeastern Chiba Prefecture around 00:07 on 29 October 2026. As an official JMA earthquake information release, it falls under the agency''s detection and public earthquake information functions. No details on warning content, dissemination or impacts are available from the title alone.", "title": "About the earthquake in northeastern Chiba Prefecture around 00:07 on October 29, 2026 (Reiwa 8)", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(215,'flood|TH|bangkok','flash_flood','2026-10-29T04:18:49Z','2026-10-29T04:10:16Z','2026-10-28','{"actions": [], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.85, "countries": [{"code": "TH", "name": "Thailand"}], "event_date": "2026-10-28", "event_location": "Bangkok, Thailand", "event_name": null, "first_seen": "2026-10-29T04:10:16Z", "hazard": "flash_flood", "hazards": ["flash_flood"], "id": 215, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-29T04:10:16Z", "lead_time": null, "outcome": "negative", "outcome_justification": "The snippet states that despite advance warnings, preparedness lagged and a lack of unified command weakened the response to the September flooding.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-28T15:43:39Z", "source_name": "PreventionWeb", "title": "Worst-case persistent rainfall scenario: stress-testing Bangkok’s urban flood resilience", "title_en": "Worst-case persistent rainfall scenario: stress-testing Bangkok''s urban flood resilience", "url": "https://www.preventionweb.net/news/worst-case-persistent-rainfall-scenario-stress-testing-bangkoks-urban-flood-resilience"}], "summaries_original": {}, "summary_en": "Bangkok''s September flooding exposed a gap between forecasts and action, with advance warnings issued but preparedness lagging. The article attributes the weakened response to the absence of a unified command to integrate information, coordinate agencies and guide timely decisions. It frames the event as a stress test for urban flood resilience under a worst-case persistent rainfall scenario.", "title": "Worst-case persistent rainfall scenario: stress-testing Bangkok''s urban flood resilience", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(216,'','multi_hazard','2026-10-29T04:18:50Z','2026-10-29T04:10:15Z','2026-10-28','{"actions": [], "agencies": [{"country": null, "name": "Famine Early Warning System Network (FEWS NET)", "type": "other"}], "agency_types": ["other"], "channels": ["website"], "confidence": 0.8, "countries": [{"code": "CO", "name": "Colombia"}, {"code": "CR", "name": "Costa Rica"}, {"code": "ET", "name": "Ethiopia"}, {"code": "GT", "name": "Guatemala"}, {"code": "HN", "name": "Honduras"}, {"code": "HT", "name": "Haiti"}, {"code": "KE", "name": "Kenya"}, {"code": "NI", "name": "Nicaragua"}, {"code": "PA", "name": "Panama"}, {"code": "SD", "name": "Sudan"}, {"code": "SN", "name": "Senegal"}, {"code": "SO", "name": "Somalia"}, {"code": "SS", "name": "South Sudan"}, {"code": "SV", "name": "El Salvador"}, {"code": "UG", "name": "Uganda"}], "event_date": "2026-10-28", "event_location": null, "event_name": null, "first_seen": "2026-10-29T04:10:15Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 216, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-29T04:10:15Z", "lead_time": "one-week forecast period (October 29 – November 4, 2026)", "outcome": "not_reported", "outcome_justification": "The item is a weekly hazard outlook describing forecast flooding, abnormal heat and dryness risks but does not report on warning dissemination actions or their outcomes.", "pillars": [2], "review": false, "sources": [{"language": "en", "published_at": "2026-10-28T20:33:08Z", "source_name": "ReliefWeb - Updates", "title": "World: Global Weather Hazards Summary, October 29, 2026 – November 4, 2026", "title_en": "World: Global Weather Hazards Summary, October 29, 2026 – November 4, 2026", "url": "https://reliefweb.int/report/world/global-weather-hazards-summary-october-29-2026-november-4-2026"}], "summaries_original": {}, "summary_en": "FEWS NET''s weekly global weather hazards summary reports that El Niño continues to strengthen, with high flood risks forecast for parts of equatorial Africa, Central America, Hispaniola and Colombia, and abnormal heat expected in the eastern Sahel. It also notes persistent inundation in South Sudan''s Sudd wetlands and abnormal dryness across parts of East Africa following large rainfall deficits. The item is a forecast-based monitoring product rather than a report on warning dissemination or outcomes.", "title": "World: Global Weather Hazards Summary, October 29, 2026 – November 4, 2026", "wmo_regions": ["I", "III", "IV"]}');
INSERT INTO "stories" VALUES(217,'','tropical_cyclone','2026-10-29T04:18:50Z','2026-10-29T04:10:15Z','2026-10-28','{"actions": [], "agencies": [{"country": null, "name": "UN Office for the Coordination of Humanitarian Affairs", "type": "international"}], "agency_types": ["international"], "channels": [], "confidence": 0.85, "countries": [{"code": "VU", "name": "Vanuatu"}], "event_date": "2026-10-28", "event_location": "Vanuatu", "event_name": null, "first_seen": "2026-10-29T04:10:15Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 217, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-29T04:10:15Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes an anticipatory action framework for tropical cyclones but does not report the outcome of any specific warning.", "pillars": [1, 2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-28T21:21:56Z", "source_name": "ReliefWeb - Updates", "title": "Vanuatu Anticipatory Action Framework: Tropical Cyclones", "title_en": "Vanuatu Anticipatory Action Framework: Tropical Cyclones", "url": "https://reliefweb.int/report/vanuatu/vanuatu-anticipatory-action-framework-tropical-cyclones"}], "summaries_original": {}, "summary_en": "A UN OCHA document sets out an anticipatory action framework for tropical cyclones in Vanuatu, a highly cyclone-exposed Small Island Developing State where two to three cyclones strike annually. The framework is intended to trigger early actions ahead of predictable cyclone threats. The snippet does not detail specific forecasts, warnings or outcomes.", "title": "Vanuatu Anticipatory Action Framework: Tropical Cyclones", "wmo_regions": ["V"]}');
INSERT INTO "stories" VALUES(218,'volcanic|PH|batangas','volcanic','2026-10-29T04:18:50Z','2026-11-04T04:15:18Z','2026-10-29','{"actions": ["Daily volcano bulletin issued by Phivolcs reporting sulfur dioxide emissions and volcanic earthquake counts"], "agencies": [{"country": "PH", "name": "Philippine Institute of Volcanology and Seismology (Phivolcs)", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["other", "website"], "confidence": 0.85, "countries": [{"code": "PH", "name": "Philippines"}], "event_date": "2026-10-29", "event_location": "Batangas, Philippines", "event_name": null, "first_seen": "2026-10-29T04:11:24Z", "hazard": "volcanic", "hazards": ["volcanic"], "id": 218, "impacts": {}, "languages": ["en"], "last_updated": "2026-11-04T04:15:18Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports routine monitoring bulletin results with no stated outcome for people or communities.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-29T08:53:22Z", "source_name": "Philippine Daily Inquirer", "title": "Taal Volcano continues to shake, logs 8 earthquakes", "title_en": "Taal Volcano continues to shake, logs 8 earthquakes", "url": "https://newsinfo.inquirer.net/2332085/taal-volcano-continues-to-shake-logs-8-earthquakes"}, {"language": "en", "published_at": "2026-10-31T09:16:11Z", "source_name": "Philippine Daily Inquirer", "title": "Taal Volcano sulfur dioxide emissions drop as number of volcanic quakes rise", "title_en": "Taal Volcano sulfur dioxide emissions drop as number of volcanic quakes rise", "url": "https://newsinfo.inquirer.net/2333388/taal-volcano-sulfur-dioxide-emissions-drop-as-number-of-volcanic-quakes-rise"}, {"language": "en", "published_at": "2026-11-04T10:31:01Z", "source_name": "Philippine Daily Inquirer", "title": "Taal Volcano logs 30 quakes in past 24 hours", "title_en": "Taal Volcano logs 30 quakes in past 24 hours", "url": "https://newsinfo.inquirer.net/2335907/taal-volcano-logs-30-quakes-in-past-24-hours"}], "summaries_original": {}, "summary_en": "Phivolcs reported in its Saturday morning bulletin that Taal Volcano''s sulfur dioxide emissions fell sharply to 217 metric tons over the previous 24 hours while volcanic earthquakes increased. The item reports on volcano monitoring results issued by the national volcano agency. No warning-related impacts or outcomes are described in the snippet.", "title": "Taal Volcano sulfur dioxide emissions drop as number of volcanic quakes rise", "wmo_regions": ["II", "V"]}');
INSERT INTO "stories" VALUES(219,'multi_hazard|PE|ica','multi_hazard','2026-10-30T04:19:45Z','2026-10-30T04:18:40Z','2026-10-30','{"actions": ["Joint evaluation and optimization of the Ica Meteorological Radar operation in preparation for El Niño"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Autoridad Nacional de Infraestructura (ANIN)", "type": "other_national_agency"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": [], "confidence": 0.85, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-30", "event_location": "Ica, Peru", "event_name": null, "first_seen": "2026-10-30T04:18:40Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 219, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-30T04:18:40Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes preparatory work on monitoring infrastructure; no outcome of warnings is reported.", "pillars": [2], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "SENAMHI Perú noticias", "title": "SENAMHI y ANIN articulan esfuerzos para optimizar el Radar Meteorológico de Ica ante el fenómeno El Niño", "title_en": "SENAMHI and ANIN join efforts to optimize the Ica Meteorological Radar ahead of El Niño", "url": "https://www.gob.pe/institucion/senamhi/noticias/1465706-senamhi-y-anin-articulan-esfuerzos-para-optimizar-el-radar-meteorologico-de-ica-ante-el-fenomeno-el-nino"}], "summaries_original": {"es": "El SENAMHI y la ANIN articulan esfuerzos para evaluar y optimizar el funcionamiento del Radar Meteorológico de Ica ante el fenómeno El Niño."}, "summary_en": "SENAMHI and the National Infrastructure Authority (ANIN) are coordinating to evaluate and optimize the operation of the Meteorological Radar in Ica, Peru, ahead of the El Niño phenomenon. The effort strengthens detection and monitoring capacity for hazards associated with El Niño. No warnings or outcomes are described in the snippet.", "title": "SENAMHI and ANIN join efforts to optimize the Ica Meteorological Radar ahead of El Niño", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(220,'severe_storm|PE|central and southern coast','severe_storm','2026-10-30T04:19:45Z','2026-10-30T04:18:51Z','2026-10-30','{"actions": ["INDECI recommends preparedness measures in response to SENAMHI Meteorological Warning No. 446"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "INDECI", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["website"], "confidence": 0.93, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-10-30", "event_location": "Central and southern coast, Peru", "event_name": null, "first_seen": "2026-10-30T04:18:51Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 220, "impacts": {}, "languages": ["es"], "last_updated": "2026-10-30T04:18:51Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes a warning and recommended preparedness measures but reports no outcome.", "pillars": [3, 4], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "INDECI Perú noticias", "title": "INDECI recomienda medidas de preparación ante el incremento de la velocidad del viento en la costa centro y sur", "title_en": "INDECI recommends preparedness measures ahead of increased wind speed on the central and southern coast", "url": "https://www.gob.pe/institucion/indeci/noticias/1465327-indeci-recomienda-medidas-de-preparacion-ante-el-incremento-de-la-velocidad-del-viento-en-la-costa-centro-y-sur"}], "summaries_original": {"es": "INDECI recomienda adoptar medidas de preparación ante el Aviso Meteorológico N.° 446 del SENAMHI, que informa sobre el incremento de la velocidad del viento, de ligera a fuerte intensidad, en la costa centro y sur del país."}, "summary_en": "INDECI recommends preparedness measures following SENAMHI Meteorological Warning No. 446, which reports increasing wind speeds from light to strong intensity along the central and southern coast of Peru. The item shows a national civil protection agency relaying an NMHS warning to the public with recommended actions. No impacts or outcomes are reported in the snippet.", "title": "INDECI recommends preparedness measures ahead of increased wind speed on the central and southern coast", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(221,'','earthquake','2026-10-30T04:19:46Z','2026-10-30T04:13:46Z','2026-10-28','{"actions": ["Nationwide earthquake early warning (EEW) drill scheduled for 5 November 2026 with participating agencies announced"], "agencies": [{"country": "JP", "name": "Japan Meteorological Agency (JMA)", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": [], "confidence": 0.8, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-28", "event_location": null, "event_name": null, "first_seen": "2026-10-30T04:13:46Z", "hazard": "earthquake", "hazards": ["earthquake"], "id": 221, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-30T04:13:46Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item is an advance notice of a drill; no actual warning performance or outcome is reported.", "pillars": [3, 4], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-28T15:00:00Z", "source_name": "気象庁 (JMA)", "title": "令和８年11月５日（木）に緊急地震速報の訓練を行います-訓練参加機関をお知らせします-", "title_en": "Earthquake early warning drill to be held on Thursday, November 5, 2026 - participating organisations announced", "url": "https://www.jma.go.jp/jma/press/2610/29b/20261029_eewkunren.html"}], "summaries_original": {"ja": "気象庁は、令和8年11月5日（木）に緊急地震速報の訓練を実施すると発表し、訓練に参加する機関を公表した。"}, "summary_en": "JMA announced an earthquake early warning drill to be held on 5 November 2026 and published the list of participating organisations. The drill tests the dissemination and response chain of Japan''s earthquake early warning system. No actual hazard or warning performance is reported.", "title": "Earthquake early warning drill to be held on Thursday, November 5, 2026 - participating organisations announced", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(222,'','earthquake','2026-10-30T04:19:47Z','2026-10-30T04:15:37Z','2026-10-29','{"actions": ["Planned nationwide emergency earthquake early warning (Kinkyu Jishin Sokuho) drill on November 5"], "agencies": [{"country": "JP", "name": "Fire and Disaster Management Agency (FDMA)", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": ["other"], "confidence": 0.8, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-29", "event_location": "Japan", "event_name": null, "first_seen": "2026-10-30T04:15:37Z", "hazard": "earthquake", "hazards": ["earthquake"], "id": 222, "impacts": {}, "languages": ["ja"], "last_updated": "2026-10-30T04:15:37Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item announces a planned drill; no outcome of any warning is reported.", "pillars": [3, 4], "review": false, "sources": [{"language": "ja", "published_at": "2026-10-29T00:00:00Z", "source_name": "消防庁 報道発表", "title": "11月５日に緊急地震速報の訓練を行います（令和８年10月29日）", "title_en": "Emergency earthquake early warning drill to be held on November 5 (October 29, Reiwa 8)", "url": "https://www.fdma.go.jp/pressrelease/houdou/items/bousai-20261029.pdf"}], "summaries_original": {"ja": "消防庁は、令和８年11月５日に緊急地震速報の訓練を実施すると発表した。地震発生時に緊急地震速報を国民へ伝達する仕組みの確認を目的としている。"}, "summary_en": "Japan''s Fire and Disaster Management Agency announced an emergency earthquake early warning drill to be held on November 5, 2026. The drill tests the dissemination of earthquake early warnings to the public. The item concerns warning communication and preparedness rather than a specific hazard event.", "title": "Emergency earthquake early warning drill to be held on November 5 (October 29, Reiwa 8)", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(223,'other|BN|asean region','other','2026-10-30T04:19:49Z','2026-10-30T04:13:22Z','2026-10-29','{"actions": ["Downgraded transboundary haze alert level to Alert Level 2 for the southern ASEAN region"], "agencies": [{"country": null, "name": "ASEAN Specialised Meteorological Centre (ASMC)", "type": "RSMC"}], "agency_types": ["RSMC"], "channels": ["website"], "confidence": 0.9, "countries": [{"code": "BN", "name": "Brunei Darussalam"}, {"code": "ID", "name": "Indonesia"}, {"code": "KH", "name": "Cambodia"}, {"code": "LA", "name": "Lao PDR"}, {"code": "MM", "name": "Myanmar"}, {"code": "MY", "name": "Malaysia"}, {"code": "PH", "name": "Philippines"}, {"code": "SG", "name": "Singapore"}, {"code": "TH", "name": "Thailand"}, {"code": "VN", "name": "Viet Nam"}], "event_date": "2026-10-29", "event_location": "Southern ASEAN Region", "event_name": null, "first_seen": "2026-10-30T04:13:22Z", "hazard": "other", "hazards": ["other"], "id": 223, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-30T04:13:22Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet reports reduced hotspot counts and some improvement in smoke haze, but does not describe measured impacts of the warning.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-10-29T06:49:18Z", "source_name": "ASEAN Specialised Meteorological Centre", "title": "Review of Regional Haze Situation for September 2026", "title_en": "Review of Regional Haze Situation for September 2026", "url": "https://asmc.asean.org/review-of-regional-haze-situation-for-september-2026/"}, {"language": "en", "published_at": "2026-10-29T10:40:03Z", "source_name": "ASEAN Specialised Meteorological Centre", "title": "Alert20261029 – Downgrade to Alert Level 2 for Southern ASEAN Region", "title_en": "Alert20261029 – Downgrade to Alert Level 2 for Southern ASEAN Region", "url": "https://asmc.asean.org/alert20261029-downgrade-to-alert-level-2-for-southern-asean-region/"}], "summaries_original": {}, "summary_en": "The ASEAN Specialised Meteorological Centre downgraded the transboundary haze alert for the southern ASEAN region to Alert Level 2 after shower activity reduced hotspot counts and improved smoke haze conditions. The centre notes that elevated hotspot activity and transboundary haze may still occur in some areas. The alert is an official update from the regional monitoring centre tracking haze from fires.", "title": "Alert20261029 – Downgrade to Alert Level 2 for Southern ASEAN Region", "wmo_regions": ["II", "V"]}');
INSERT INTO "stories" VALUES(224,'','tropical_cyclone','2026-10-30T04:19:50Z','2026-10-30T04:09:02Z','2026-10-29','{"actions": ["Anticipatory action framework prepared for tropical storms and hurricanes ahead of the Atlantic hurricane season"], "agencies": [{"country": null, "name": "UN Office for the Coordination of Humanitarian Affairs", "type": "international"}, {"country": null, "name": "United Nations Development Programme", "type": "international"}], "agency_types": ["international"], "channels": [], "confidence": 0.8, "countries": [{"code": "HT", "name": "Haiti"}], "event_date": "2026-10-29", "event_location": "Haiti", "event_name": null, "first_seen": "2026-10-30T04:09:02Z", "hazard": "tropical_cyclone", "hazards": ["tropical_cyclone"], "id": 224, "impacts": {}, "languages": ["en"], "last_updated": "2026-10-30T04:09:02Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item describes a planning framework for anticipatory action; no hazard event outcome is reported.", "pillars": [1, 2, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-10-29T16:59:36Z", "source_name": "ReliefWeb - Updates", "title": "Haiti: Haïti: Cadre d’Action Anticipatoire Tempêtes/Ouragans", "title_en": "Haiti: Anticipatory Action Framework for Storms/Hurricanes", "url": "https://reliefweb.int/report/haiti/haiti-cadre-daction-anticipatoire-tempetesouragans"}], "summaries_original": {}, "summary_en": "An OCHA document presents an anticipatory action framework for storms and hurricanes in Haiti, noting that about 96 per cent of the population is exposed to climate-related hazards. The framework aims to ensure preparedness before the 1 June to 30 November Atlantic hurricane season. It concerns early action planning rather than a specific event.", "title": "Haiti: Anticipatory Action Framework for Storms/Hurricanes", "wmo_regions": ["IV"]}');
