INSERT INTO "stories" VALUES(337,'named|el nino 27','multi_hazard','2026-11-09T04:20:17Z','2026-11-09T04:19:19Z','2026-11-07','{"actions": ["Government of Chubut sent a bill to declare a meteorological, preventive and infrastructure emergency in response to the Super El Niño phenomenon", "Emergency planned to remain in force initially until end of April 2027"], "agencies": [{"country": "AR", "name": "Government of Chubut", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.8, "countries": [{"code": "AR", "name": "Argentina"}], "event_date": "2026-11-07", "event_location": "Chubut Province, Argentina", "event_name": "Super El Niño 2026/27", "first_seen": "2026-11-09T04:19:19Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 337, "impacts": {}, "languages": ["es"], "last_updated": "2026-11-09T04:19:19Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The article describes a preparedness decision taken ahead of the phenomenon; no outcomes are yet reported.", "pillars": [1, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-11-07T04:19:13Z", "source_name": "lmneuquen.com", "title": "Súper Niño 2026/27: una provincia se declara en emergencia y arma un plan de prevención", "title_en": "Super El Niño 2026/27: a province declares emergency and drafts a prevention plan", "url": "https://www.lmneuquen.com/patagonia/super-nino-202627-una-provincia-se-declara-emergencia-y-arma-un-plan-prevencion-n1260267"}], "summaries_original": {"es": "El Gobierno de Chubut envió un proyecto de ley para declarar la emergencia meteorológica, preventiva y de infraestructura frente al Súper Niño, con vigencia inicial hasta fines de abril de 2027."}, "summary_en": "The government of Chubut province sent a bill on 5 November 2026 to declare a meteorological, preventive and infrastructure emergency ahead of the anticipated Super El Niño phenomenon. The emergency would initially last until the end of April 2027. The item focuses on preparedness and prevention planning rather than observed impacts.", "title": "Super El Niño 2026/27: a province declares emergency and drafts a prevention plan", "wmo_regions": ["III"]}');
