INSERT INTO "stories" VALUES(339,'severe_storm|CL|metropolitan region','severe_storm','2026-11-09T04:20:19Z','2026-11-09T04:19:33Z','2026-11-09','{"actions": ["Senapred declared a Preventive Early Alert for the Metropolitan Region"], "agencies": [{"country": "CL", "name": "BioBioChile", "type": "media"}, {"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["media", "other_national_agency"], "channels": ["other"], "confidence": 0.95, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-11-09", "event_location": "Metropolitan Region, Chile", "event_name": null, "first_seen": "2026-11-09T04:19:33Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 339, "impacts": {}, "languages": ["es"], "last_updated": "2026-11-09T04:19:33Z", "lead_time": "from the afternoon of Monday 9 November 2026", "outcome": "not_reported", "outcome_justification": "The item reports only the issuance of the alert; no outcomes are described.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-11-09T00:07:13Z", "source_name": "BioBioChile nacional", "title": "Tras domingo con 33 grados: declaran Alerta Temprana en la RM por posibles tormentas eléctricas", "title_en": "After Sunday with 33 degrees: Early Alert declared in the Metropolitan Region for possible thunderstorms", "url": "https://www.biobiochile.cl/noticias/nacional/region-metropolitana/2026/11/08/declaran-alerta-temprana-preventiva-en-la-region-metropolitana-por-probables-tormentas-electricas.shtml"}], "summaries_original": {"es": "Senapred declaró durante la noche del domingo Alerta Temprana Preventiva en la Región Metropolitana por probables tormentas eléctricas con posibles precipitaciones fuertes en un corto periodo de tiempo en precordillera, valles precordilleranos y cordillera, vigente desde la tarde del lunes 09 de noviembre."}, "summary_en": "Chile''s national disaster agency Senapred declared a Preventive Early Alert in the Metropolitan Region overnight on Sunday, warning of probable thunderstorms and possible short-duration heavy rainfall in the precordillera, pre-Andean valleys and mountains. The alert is in effect from the afternoon of Monday 9 November, following a day with temperatures near 33 degrees.", "title": "After Sunday with 33 degrees: Early Alert declared in the Metropolitan Region for possible thunderstorms", "wmo_regions": ["III"]}');
