INSERT INTO "stories" VALUES(342,'flood|CL|monte patria','flood','2026-11-09T04:20:20Z','2026-11-09T04:19:19Z','2026-11-09','{"actions": ["Declaration of Red Alert for Monte Patria commune", "Cancellation of prior Yellow Alert for flooding"], "agencies": [{"country": "CL", "name": "Senapred", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.9, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-11-09", "event_location": "Monte Patria, Coquimbo Region, Chile", "event_name": null, "first_seen": "2026-11-09T04:19:19Z", "hazard": "flood", "hazards": ["flood"], "id": 342, "impacts": {}, "languages": ["es"], "last_updated": "2026-11-09T04:19:19Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports only the issuance and change of alert levels; no outcomes are described.", "pillars": [3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-11-09T04:19:13Z", "source_name": "vlnradio.cl", "title": "Senapred declara Alerta Roja para la comuna de Monte Patria por desborde y cancela Alerta Amarilla por crecida", "title_en": "Senapred declares Red Alert for Monte Patria commune due to overflow and cancels Yellow Alert for flooding", "url": "https://www.vlnradio.cl/noticias/nacional/region-de-coquimbo/2026/11/09/senapred-declara-alerta-roja-para-la-comuna-de-monte-patria-por-desborde-y-cancela-alerta-amarilla-por-crecida"}], "summaries_original": {"es": "Senapred declaró Alerta Roja para la comuna de Monte Patria, en la Región de Coquimbo, por un desborde, cancelando la Alerta Amarilla por crecida. La nueva alerta está vigente desde el 08 de noviembre de 2026."}, "summary_en": "Chile''s emergency agency Senapred declared a Red Alert for Monte Patria commune in Coquimbo Region due to an overflow, cancelling the earlier Yellow Alert for river flooding. The new Red Alert has been in effect since 8 November 2026.", "title": "Senapred declares Red Alert for Monte Patria commune due to overflow and cancels Yellow Alert for flooding", "wmo_regions": ["III"]}');
