INSERT INTO "stories" VALUES(345,'other|GB|central england and wales','other','2026-11-10T04:18:50Z','2026-11-10T04:09:56Z','2026-11-10','{"actions": [], "agencies": [{"country": "GB", "name": "Met Office", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": ["website"], "confidence": 0.8, "countries": [{"code": "GB", "name": "United Kingdom"}], "event_date": "2026-11-10", "event_location": "Central England and Wales, United Kingdom", "event_name": null, "first_seen": "2026-11-10T04:09:56Z", "hazard": "other", "hazards": ["other"], "id": 345, "impacts": {}, "languages": ["en"], "last_updated": "2026-11-10T04:09:56Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports a yellow fog warning issued for parts of central England and Wales and forecast colder, frosty conditions, but gives no information on impacts or public response.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": null, "source_name": "UK Met Office news", "title": "Fog giving way to colder weather and frost later this week Fog and rain will affect parts of the UK this week, with a yellow fog warning in place overnight for parts of central England and Wales, before colder and increasingly frosty conditions spread south. Read more", "title_en": "Fog giving way to colder weather and frost later this week", "url": "https://www.metoffice.gov.uk/about-us/news-and-media/media-centre/weather-and-climate-news/2026/fog-giving-way-to-colder-weather-and-frost-later-this-week"}], "summaries_original": {}, "summary_en": "The UK Met Office issued a yellow fog warning overnight for parts of central England and Wales, with fog and rain affecting parts of the UK this week. Colder and increasingly frosty conditions are forecast to spread south later in the week. The item concerns forecasting and warning issuance only, with no reported outcomes.", "title": "Fog giving way to colder weather and frost later this week", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(346,'named|el nino','multi_hazard','2026-11-10T04:18:51Z','2026-11-10T04:17:06Z','2026-11-10','{"actions": ["Participation in regional working meeting convened by the Gobierno Regional de Ica", "Verification and evaluation of regional response capacity", "Provision of scientific information and technical assistance for El Niño preparedness"], "agencies": [{"country": "PE", "name": "SENAMHI", "type": "NMHS"}, {"country": "PE", "name": "Gobierno Regional de Ica", "type": "other_national_agency"}, {"country": "PE", "name": "Ministerio del Ambiente (MINAM)", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other"], "confidence": 0.85, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-11-10", "event_location": "Ica, Peru", "event_name": "El Niño", "first_seen": "2026-11-10T04:17:06Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 346, "impacts": {}, "languages": ["es"], "last_updated": "2026-11-10T04:17:06Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes preparedness coordination and technical support but reports no outcomes of warnings or response.", "pillars": [1, 2, 4], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "SENAMHI Perú noticias", "title": "SENAMHI fortalece la preparación ante el Fenómeno El Niño en Ica con información científica y asistencia técnica", "title_en": "SENAMHI strengthens preparedness for El Niño phenomenon in Ica with scientific information and technical assistance", "url": "https://www.gob.pe/institucion/senamhi/noticias/1471601-senamhi-fortalece-la-preparacion-ante-el-fenomeno-el-nino-en-ica-con-informacion-cientifica-y-asistencia-tecnica"}], "summaries_original": {"es": "SENAMHI participó en una reunión de trabajo convocada por el Gobierno Regional de Ica para verificar y evaluar la capacidad de respuesta ante El Niño, brindando información científica y asistencia técnica para fortalecer la preparación."}, "summary_en": "SENAMHI, Peru''s national meteorological and hydrological service, took part in a regional working meeting convened by the Ica regional government to assess the region''s capacity to respond to the El Niño phenomenon. SENAMHI provided scientific information and technical assistance to strengthen preparedness. The item focuses on risk knowledge and preparedness coordination rather than on a specific warning event.", "title": "SENAMHI strengthens preparedness for El Niño phenomenon in Ica with scientific information and technical assistance", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(347,'multi_hazard|PE|lambayeque','multi_hazard','2026-11-10T04:18:52Z','2026-11-10T04:17:17Z','2026-11-10','{"actions": ["Participation in governance and risk knowledge work to strengthen multi-hazard early warning system in Lambayeque"], "agencies": [{"country": "PE", "name": "Cenepred", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.8, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-11-10", "event_location": "Lambayeque, Peru", "event_name": null, "first_seen": "2026-11-10T04:17:17Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 347, "impacts": {}, "languages": ["es"], "last_updated": "2026-11-10T04:17:17Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes capacity-building and risk knowledge activities for an early warning system but reports no specific warning event or outcome.", "pillars": [1, 3], "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "CENEPRED Perú noticias", "title": "Cenepred aporta al conocimiento del riesgo en Lambayeque, en el marco del Sistema de Alerta Temprana Multiamenaza", "title_en": "Cenepred contributes to risk knowledge in Lambayeque, within the Multi-hazard Early Warning System framework", "url": "https://www.gob.pe/institucion/cenepred/noticias/1471638-cenepred-aporta-al-conocimiento-del-riesgo-en-lambayeque-en-el-marco-del-sistema-de-alerta-temprana-multiamenaza"}], "summaries_original": {"es": "El Cenepred participó en jornadas para fortalecer la gobernanza en gestión del riesgo de desastres en Lambayeque, con énfasis en el conocimiento del riesgo dentro del Sistema de Alerta Temprana Multiamenaza."}, "summary_en": "Cenepred, Peru''s national disaster risk estimation and reduction centre, took part in workshops in Lambayeque aimed at strengthening disaster risk management governance with emphasis on risk knowledge. The activities are framed within the development of a multi-hazard early warning system. No specific hazard event or warning outcome is described in the snippet.", "title": "Cenepred contributes to risk knowledge in Lambayeque, within the Multi-hazard Early Warning System framework", "wmo_regions": ["III"]}');
