INSERT INTO "stories" VALUES(351,'','wildfire','2026-11-10T04:18:55Z','2026-11-10T04:07:00Z','2026-11-09','{"actions": ["Residents used low-cost air sensors to monitor air quality and protect themselves"], "agencies": [], "agency_types": [], "channels": [], "confidence": 0.7, "countries": [], "event_date": "2026-11-09", "event_location": null, "event_name": null, "first_seen": "2026-11-10T04:07:00Z", "hazard": "wildfire", "hazards": ["wildfire"], "id": 351, "impacts": {}, "languages": ["en"], "last_updated": "2026-11-10T04:07:00Z", "lead_time": null, "outcome": "mixed", "outcome_justification": "Study finds low-cost sensors help residents protect themselves, but disparities persist in who benefits from the information they produce.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-11-09T11:29:38Z", "source_name": "PreventionWeb", "title": "Research shows communities need better guidance on wildfire air quality", "title_en": "Research shows communities need better guidance on wildfire air quality", "url": "https://www.preventionweb.net/news/research-shows-communities-need-better-guidance-wildfire-air-quality"}], "summaries_original": {}, "summary_en": "A study reports that low-cost air quality sensors help residents protect themselves during wildfire smoke events, which supports monitoring and information access for communities. However, disparities persist in who benefits from the information produced, and the research calls for better guidance on wildfire air quality.", "title": "Research shows communities need better guidance on wildfire air quality", "wmo_regions": []}');
INSERT INTO "stories" VALUES(352,'','heatwave','2026-11-10T04:18:55Z','2026-11-10T04:07:00Z','2026-11-09','{"actions": ["National heatwave awareness campaign (Harrek Wa''yak) launched to raise public awareness on heat-related health risks"], "agencies": [{"country": null, "name": "Prosper Global", "type": "NGO"}, {"country": "JO", "name": "MedLabs", "type": "other"}, {"country": "JO", "name": "Ministry of Health (Jordan)", "type": "other_national_agency"}], "agency_types": ["NGO", "other", "other_national_agency"], "channels": ["other"], "confidence": 0.8, "countries": [{"code": "JO", "name": "Jordan"}], "event_date": "2026-11-09", "event_location": "Jordan", "event_name": null, "first_seen": "2026-11-10T04:07:00Z", "hazard": "heatwave", "hazards": ["heatwave"], "id": 352, "impacts": {}, "languages": ["en"], "last_updated": "2026-11-10T04:07:00Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes the campaign launch only; no results or effects on warning uptake or health outcomes are reported.", "pillars": [3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-11-09T11:44:34Z", "source_name": "PreventionWeb", "title": "National campaign to raise awareness on heat health", "title_en": "National campaign to raise awareness on heat health", "url": "https://www.preventionweb.net/resource/case-study/national-campaign-raise-awareness-heat-health"}], "summaries_original": {}, "summary_en": "A case study describes Harrek Wa''yak, a national heatwave awareness campaign launched in Jordan by Prosper Global with the Ministry of Health and MedLabs. The campaign focuses on communicating heat-health risks to the public. Outcomes are not reported in the snippet.", "title": "National campaign to raise awareness on heat health", "wmo_regions": ["II", "VI"]}');
INSERT INTO "stories" VALUES(353,'','drought','2026-11-10T04:18:55Z','2026-11-10T04:07:00Z','2026-11-09','{"actions": [], "agencies": [{"country": "IN", "name": "India Meteorological Department", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": [], "confidence": 0.85, "countries": [{"code": "IN", "name": "India"}], "event_date": "2026-11-09", "event_location": null, "event_name": null, "first_seen": "2026-11-10T04:07:00Z", "hazard": "drought", "hazards": ["drought"], "id": 353, "impacts": {}, "languages": ["en"], "last_updated": "2026-11-10T04:07:00Z", "lead_time": null, "outcome": "negative", "outcome_justification": "Many farmers missed or could not use drought advisories despite an accurate El Niño forecast, due to gaps in access, communication, local coverage and trust.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-11-09T13:33:51Z", "source_name": "PreventionWeb", "title": "Early warning must also reach farmers without institutional support", "title_en": "Early warning must also reach farmers without institutional support", "url": "https://www.preventionweb.net/news/early-warning-must-also-reach-farmers-without-institutional-support"}], "summaries_original": {}, "summary_en": "India''s drought early warning system accurately forecast El Niño in 2026. However, many farmers, particularly those without institutional support, missed or could not use the advisories because of gaps in access, communication, local coverage and trust. The item argues early warnings must also reach these farmers.", "title": "Early warning must also reach farmers without institutional support", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(354,'heatwave|PE|piura','heatwave','2026-11-10T04:18:56Z','2026-11-10T04:17:19Z','2026-11-09','{"actions": [], "agencies": [{"country": "PE", "name": "Senamhi", "type": "NMHS"}], "agency_types": ["NMHS"], "channels": ["other"], "confidence": 0.8, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-11-09", "event_location": "Piura, Peru", "event_name": null, "first_seen": "2026-11-10T04:17:19Z", "hazard": "heatwave", "hazards": ["heatwave"], "id": 354, "impacts": {}, "languages": ["es"], "last_updated": "2026-11-10T04:17:19Z", "lead_time": "multi-day forecast through 12 November", "outcome": "not_reported", "outcome_justification": "The article reports a Senamhi forecast of high temperatures, UV radiation and possible atmospheric instability, but no outcomes of the warning are given.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-11-09T16:26:58Z", "source_name": "La República (Perú) sociedad", "title": "Ola de calor en Piura: Senamhi prevé temperaturas de más de 36 °C y posibles lluvias hasta el 12 de noviembre", "title_en": "Heat wave in Piura: Senamhi forecasts temperatures above 36 °C and possible rain until 12 November", "url": "https://larepublica.pe/sociedad/2026/11/09/ola-de-calor-en-piura-senamhi-preve-temperaturas-de-mas-de-36-c-y-posibles-lluvias-hasta-el-12-de-noviembre-269316"}], "summaries_original": {"es": "El Senamhi pronostica una ola de calor en Piura con temperaturas de 23 °C a 36 °C en la costa norte y de 19 °C a 32 °C en la sierra norte, además de alta radiación ultravioleta y posible inestabilidad atmosférica hasta el 12 de noviembre."}, "summary_en": "Peru''s National Meteorological and Hydrological Service (Senamhi) forecasts a heat wave in Piura with temperatures of 23 °C to 36 °C on the north coast and 19 °C to 32 °C in the northern highlands, alongside high ultraviolet radiation and possible atmospheric instability and rain until 12 November. The item focuses on the forecast itself and does not report how the warning was disseminated or acted upon.", "title": "Heat wave in Piura: Senamhi forecasts temperatures above 36 °C and possible rain until 12 November", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(355,'flood|ET|dollo ado district','flood','2026-11-10T04:18:56Z','2026-11-10T04:06:59Z','2026-11-10','{"actions": ["Three-day training workshop on digital twin for flood forecasting, preparedness and emergency response, 23-25 June 2026, Addis Ababa"], "agencies": [{"country": null, "name": "International Water Management Institute (IWMI)", "type": "international"}], "agency_types": ["international"], "channels": [], "confidence": 0.8, "countries": [{"code": "ET", "name": "Ethiopia"}], "event_date": "2026-11-10", "event_location": "Dollo Ado district, Somali Region, Ethiopia", "event_name": null, "first_seen": "2026-11-10T04:06:59Z", "hazard": "flood", "hazards": ["flood"], "id": 355, "impacts": {}, "languages": ["en"], "last_updated": "2026-11-10T04:06:59Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The snippet describes capacity-building for flood forecasting and response but reports no specific warning outcomes.", "pillars": [2, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-11-10T02:40:49Z", "source_name": "ReliefWeb - Updates", "title": "Ethiopia | Digital Twin for Effective Flood Response: Technical Training and Operationalization - Workshop Report (November 2026)", "title_en": "Ethiopia | Digital Twin for Effective Flood Response: Technical Training and Operationalization - Workshop Report (November 2026)", "url": "https://reliefweb.int/report/ethiopia/ethiopia-digital-twin-effective-flood-response-technical-training-and-operationalization-workshop-report-november-2026"}], "summaries_original": {}, "summary_en": "IWMI organised a three-day training workshop in June 2026 to strengthen government and humanitarian capacity in flood forecasting, preparedness and response using a digital twin, with a focus on Dollo Ado district in Somali Region, Ethiopia. The workshop targets operational flood early warning capability, though the snippet reports no specific warnings issued or outcomes.", "title": "Ethiopia | Digital Twin for Effective Flood Response: Technical Training and Operationalization - Workshop Report (November 2026)", "wmo_regions": ["I"]}');
INSERT INTO "stories" VALUES(356,'flood|TH|central and southern provinces','flood','2026-11-10T04:18:57Z','2026-11-10T04:09:56Z','2026-11-10','{"actions": ["Flood alert issued for 16 central and southern provinces", "Authorities instructed to ready potential evacuation shelters"], "agencies": [{"country": "TH", "name": "Department of Disaster Prevention and Mitigation (DDPM)", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.95, "countries": [{"code": "TH", "name": "Thailand"}], "event_date": "2026-11-10", "event_location": "Central and southern provinces, Thailand", "event_name": null, "first_seen": "2026-11-10T04:09:56Z", "hazard": "flood", "hazards": ["flood"], "id": 356, "impacts": {}, "languages": ["en"], "last_updated": "2026-11-10T04:09:56Z", "lead_time": "November 9 to 13 alert period, published 10 November", "outcome": "not_reported", "outcome_justification": "The item describes the alert and preparedness instructions but reports no results of the warning.", "pillars": [3, 4], "review": false, "sources": [{"language": "en", "published_at": "2026-11-10T04:09:51Z", "source_name": "nationthailand.com", "title": "DDPM puts 16 Thai provinces on flood alert for 9–13 November", "title_en": "DDPM puts 16 Thai provinces on flood alert for 9–13 November", "url": "https://www.nationthailand.com/news/general/40073286"}], "summaries_original": {}, "summary_en": "Thailand''s Department of Disaster Prevention and Mitigation issued a flood alert covering 16 central and southern provinces for 9 to 13 November. Authorities were instructed to prepare potential evacuation shelters. The item does not report outcomes of the alert.", "title": "DDPM puts 16 Thai provinces on flood alert for 9–13 November", "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(357,'','severe_storm','2026-11-10T04:18:57Z','2026-11-10T04:12:45Z','2026-11-10','{"actions": ["Warnings issued advising people to avoid approaching swollen rivers and flooded roads", "Residents urged to follow municipal evacuation orders"], "agencies": [{"country": "PT", "name": "Portuguese meteorological and civil protection authorities", "type": "other_national_agency"}, {"country": "ES", "name": "Spanish meteorological authorities", "type": "other_national_agency"}], "agency_types": ["other_national_agency"], "channels": [], "confidence": 0.85, "countries": [{"code": "ES", "name": "Spain"}, {"code": "PT", "name": "Portugal"}], "event_date": "2026-11-10", "event_location": null, "event_name": null, "first_seen": "2026-11-10T04:12:45Z", "hazard": "severe_storm", "hazards": ["severe_storm"], "id": 357, "impacts": {}, "languages": ["ja"], "last_updated": "2026-11-10T04:12:45Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The article describes warnings and advice issued ahead of the storm''s peak on 11 November; no outcome has been reported.", "pillars": [2, 3], "review": false, "sources": [{"language": "ja", "published_at": "2026-11-10T04:12:41Z", "source_name": "news.infoseek.co.jp", "title": "ポルトガルやスペインに発達したストーム 大雨や暴風に警戒｜Infoseekニュース", "title_en": "Developing storm in Portugal and Spain: warnings for heavy rain and strong winds", "url": "https://news.infoseek.co.jp/article/weathernews_202611100151/"}], "summaries_original": {"ja": "ポルトガルとスペインの気象当局は、発達中のストームに対し警報を発表し、増水した河川や浸水道路への接近回避と自治体の避難指示への従いを呼びかけている。荒天のピークは11日で、30m/s超の暴風と高波が警戒されている。"}, "summary_en": "Meteorological authorities in Portugal and Spain issued warnings for a developing storm, advising people to avoid swollen rivers and flooded roads and to follow municipal evacuation orders. The storm''s peak was expected on 11 November, with wind gusts over 30 m/s and high waves forecast.", "title": "Developing storm in Portugal and Spain: warnings for heavy rain and strong winds", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(358,'flood|ES|plasencia','heavy_rain','2026-11-10T04:18:58Z','2026-11-10T04:17:06Z','2026-11-10','{"actions": ["Urgent municipal coordination meeting convened", "Public advised to avoid unnecessary travel through flood-prone areas", "Municipal parks and sports facilities closed on 10 November 2026 in response to AEMET red alert", "Suspension of school activities in affected areas to avoid travel and ensure pupil safety"], "agencies": [{"country": "ES", "name": "AEMET", "type": "NMHS"}, {"country": "ES", "name": "Ayuntamiento de Moraleja", "type": "other_national_agency"}, {"country": "ES", "name": "Ayuntamiento de Plasencia", "type": "other_national_agency"}, {"country": "ES", "name": "Junta de Extremadura", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": ["other"], "confidence": 0.93, "countries": [{"code": "ES", "name": "Spain"}], "event_date": "2026-11-10", "event_location": "Plasencia, Spain", "event_name": null, "first_seen": "2026-11-10T04:17:06Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 358, "impacts": {}, "languages": ["es"], "last_updated": "2026-11-10T04:17:06Z", "lead_time": "same day (closures announced for 10 November 2026)", "outcome": "not_reported", "outcome_justification": "The item reports warnings and preparedness actions in advance of the event but gives no information on actual impacts or how the warnings performed.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-11-10T04:17:00Z", "source_name": "canalextremadura.es", "title": "Plasencia activa un dispositivo especial ante la alerta roja y naranja por fuertes lluvias", "title_en": "Plasencia activates special deployment ahead of red and orange alerts for heavy rain", "url": "https://www.canalextremadura.es/noticias/plasencia/plasencia-activa-un-dispositivo-especial-ante-la-alerta-roja-y-naranja-por"}, {"language": "es", "published_at": "2026-11-10T04:17:00Z", "source_name": "radiointerior.es", "title": "Moraleja cierra sus parques e instalaciones deportivas ante la alerta roja por lluvias", "title_en": "Moraleja closes parks and sports facilities ahead of red rain alert", "url": "https://www.radiointerior.es/texto-diario/mostrar/6085034/moraleja-cierra-parques-e-instalaciones-deportivas-ante-alerta-roja-lluvias"}, {"language": "es", "published_at": "2026-11-10T04:17:00Z", "source_name": "radiointerior.es", "title": "La amenaza de lluvias torrenciales obliga a ampliar la alerta roja en el norte de Cáceres", "title_en": "The threat of torrential rain forces expansion of red alert in northern Cáceres", "url": "https://www.radiointerior.es/texto-diario/mostrar/6085087/amenaza-lluvias-torrenciales-obliga-ampliar-alerta-roja-norte-caceres"}], "summaries_original": {"es": "El Ayuntamiento de Plasencia convocó una reunión urgente de coordinación ante la previsión de fuertes lluvias para el martes 10 de noviembre y la activación de alerta naranja en Plasencia y roja en el norte de Cáceres, recomendando evitar desplazamientos por zonas inundables."}, "summary_en": "Plasencia city council convened an urgent coordination meeting after forecasts of heavy rain for 10 November and the activation of orange alert in Plasencia and red alert in northern Cáceres. Residents were advised to avoid unnecessary travel through flood-prone zones. The item describes a warning-driven preparedness response but reports no outcome.", "title": "Plasencia activates special deployment ahead of red and orange alerts for heavy rain", "wmo_regions": ["VI"]}');
INSERT INTO "stories" VALUES(359,'flood|CL|coquimbo','heavy_rain','2026-11-10T04:18:59Z','2026-11-10T04:17:06Z','2026-11-10','{"actions": ["Declared Alerta Temprana Preventiva for Coquimbo, Metropolitana and O''Higgins", "Reinforced monitoring", "Coordination of the National Prevention and Disaster Response System"], "agencies": [{"country": "CL", "name": "Dirección Meteorológica de Chile", "type": "NMHS"}, {"country": "CL", "name": "SENAPRED", "type": "other_national_agency"}], "agency_types": ["NMHS", "other_national_agency"], "channels": [], "confidence": 0.9, "countries": [{"code": "CL", "name": "Chile"}], "event_date": "2026-11-10", "event_location": "Coquimbo, Metropolitana and O''Higgins regions, Chile", "event_name": null, "first_seen": "2026-11-10T04:17:06Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 359, "impacts": {}, "languages": ["es"], "last_updated": "2026-11-10T04:17:06Z", "lead_time": "tonight (same day as publication)", "outcome": "not_reported", "outcome_justification": "The item reports the alert declaration and expected conditions but no outcome of the event is given.", "pillars": [2, 3, 4], "review": false, "sources": [{"language": "es", "published_at": "2026-11-10T04:17:00Z", "source_name": "elrancaguino.cl", "title": "Declaran alerta preventiva por lluvias y tormentas eléctricas que llegarían esta noche - El Rancagüino", "title_en": "Preventive alert declared for rain and thunderstorms expected tonight", "url": "https://www.elrancaguino.cl/2026/11/09/declaran-alerta-preventiva-por-lluvias-y-tormentas-electricas-que-llegarian-esta-noche/"}], "summaries_original": {"es": "SENAPRED declaró Alerta Temprana Preventiva para Coquimbo, Metropolitana y O''Higgins ante un pronóstico de precipitaciones y tormentas asociadas a una baja segregada, según avisos de la Dirección Meteorológica de Chile. La medida implica reforzar el monitoreo y la coordinación del Sistema Nacional de Prevención y Respuesta ante Desastres."}, "summary_en": "SENAPRED declared a preventive early alert for Coquimbo, Metropolitana and O''Higgins regions in Chile based on Dirección Meteorológica de Chile forecasts of rain and thunderstorms linked to a cut-off low expected that night. The measure involves strengthening monitoring and coordination within the national disaster prevention and response system.", "title": "Preventive alert declared for rain and thunderstorms expected tonight", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(360,'flood|EC|orellana and sucumbios cantons','heavy_rain','2026-11-10T04:18:59Z','2026-11-10T04:17:06Z','2026-11-10','{"actions": [], "agencies": [{"country": "EC", "name": "INAMHI", "type": "NMHS"}, {"country": "EC", "name": "Teleamazonas", "type": "media"}], "agency_types": ["NMHS", "media"], "channels": ["other"], "confidence": 0.9, "countries": [{"code": "EC", "name": "Ecuador"}], "event_date": "2026-11-10", "event_location": "Orellana and Sucumbíos cantons, Ecuador", "event_name": null, "first_seen": "2026-11-10T04:17:06Z", "hazard": "heavy_rain", "hazards": ["heavy_rain"], "id": 360, "impacts": {}, "languages": ["es"], "last_updated": "2026-11-10T04:17:06Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports an official forecast with red and orange alerts for heavy rain but gives no information on impacts or the outcome of the warnings.", "pillars": [2, 3], "review": false, "sources": [{"language": "es", "published_at": "2026-11-10T04:17:00Z", "source_name": "teleamazonas.com", "title": "Inamhi emite pronósticos de lluvias para este martes 10 de noviembre de 2026 en el país", "title_en": "INAMHI issues rainfall forecasts for Tuesday 10 November 2026 in the country", "url": "https://www.teleamazonas.com/actualidad/noticias/ecuador/inamhi-emite-pronosticos-lluvias-martes-10-noviembre-2026-pais-132583/"}], "summaries_original": {"es": "El INAMHI emitió su pronóstico oficial de lluvias para el martes 10 de noviembre de 2026, con alerta roja por lluvias fuertes en cantones de Orellana y Sucumbíos y alerta naranja en varias zonas de la Costa."}, "summary_en": "Ecuador''s National Institute of Meteorology and Hydrology (INAMHI) issued its official rainfall forecast for Tuesday 10 November 2026, with a red alert for heavy rain in the Orellana and Sucumbíos cantons and orange alerts in several coastal areas. The item is a forecast and alert announcement; no outcomes are reported.", "title": "INAMHI issues rainfall forecasts for Tuesday 10 November 2026 in the country", "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(361,'named|cempaka','multi_hazard','2026-11-10T04:19:01Z','2026-11-10T04:10:43Z','2026-11-10','{"actions": [], "agencies": [{"country": "PH", "name": "PAGASA", "type": "NMHS"}, {"country": "PH", "name": "Philippine Daily Inquirer", "type": "media"}], "agency_types": ["NMHS", "media"], "channels": ["other"], "confidence": 0.8, "countries": [{"code": "PH", "name": "Philippines"}], "event_date": "2026-11-10", "event_location": "Philippines", "event_name": "Typhoon Cempaka", "first_seen": "2026-11-10T04:10:43Z", "hazard": "multi_hazard", "hazards": ["multi_hazard"], "id": 361, "impacts": {}, "languages": ["en"], "last_updated": "2026-11-10T04:10:43Z", "lead_time": null, "outcome": "not_reported", "outcome_justification": "The item reports PAGASA''s 5 a.m. forecast of amihan and easterly rains as Typhoon Cempaka moves away from the PAR; no impacts or responses are described.", "pillars": [2, 3], "review": false, "sources": [{"language": "en", "published_at": "2026-11-10T07:29:19Z", "source_name": "Philippine Daily Inquirer", "title": "Amihan, easterlies to bring rains across parts of PH on Nov. 10", "title_en": "Amihan, easterlies to bring rains across parts of PH on Nov. 10", "url": "https://newsinfo.inquirer.net/2338790/amihan-easterlies-to-bring-rains-across-parts-of-ph-on-nov-10"}], "summaries_original": {}, "summary_en": "PAGASA''s 5 a.m. forecast, as reported by the Philippine Daily Inquirer, indicates that the northeast monsoon (amihan) and easterlies will bring rains to parts of the Philippines on 10 November as Typhoon Cempaka moves farther from the Philippine Area of Responsibility. The item is a forecast-dissemination report with no stated impacts or responses.", "title": "Amihan, easterlies to bring rains across parts of PH on Nov. 10", "wmo_regions": ["II", "V"]}');
